"Xu4clBA",2273,5157392,9.,3477.,"print([[\n _   _  _______   ___   _ _____   _   _ _   _______\n| \\ | ||  ___\\ \\ / / | | /  ___| | | | | | | | ___ \\\n|  \\| || |__  \\ V /| | | \\ `--.  | |_| | | | | |_/ /\n| . ` ||  __| /   \\| | | |`--. \\ |  _  | | | | ___ \\\n| |\\  || |___/ /^\\ \\ |_| /\\__/ / | | | | |_| | |_/ /\n\\_| \\_/\\____/\\/   \\/\\___/\\____/  \\_| |_/\\___/\\____/   (sieu vip he he)\n]])\n\n-- ============================================================\n-- HTTP SPY GUARD REMOVED\n-- ============================================================\nlocal _raw_request, _raw_HttpGet, _raw_HttpPost = nil, nil, nil\n\nlocal function isFunctionHooked(fn)\n    if type(fn) ~= \"function\" then return false end\n    if ishooked and ishooked(fn) then return true end\n    return false\nend\n\nlocal function corruptExecution(reason)\n    return\n    task.spawn(function()\n        pcall(function()\n            local StarterGui = game:GetService(\"StarterGui\")\n            StarterGui:SetCore(\"SendNotification\", {\n                Title = \"Nexus Security\",\n                Text = \"Tamper detected: \" .. tostring(reason),\n                Duration = 10\n            })\n        end)\n        task.wait(2)\n        pcall(function()\n            local lp = game:GetService(\"Players\").LocalPlayer\n            if lp then lp:Kick(\"Nexus Security: Tamper detected (\" .. tostring(reason) .. \")\") end\n        end)\n        while true do end\n    end)\nend\n\nlocal function verifyHttpIntegrity()\n    return true\nend\nverifyHttpIntegrity()\n\n\n\n-- ============================================================\n-- ===== BOOT DIAGNOSTIC / CHONG CHET IM LANG =====\n-- Nhieu executor (nhat la UNC/sUNC cao tren mobile) KHONG hien console,\n-- nen khi script chet giua duong thi nguoi dung chi thay \"khong len gi\".\n-- Block nay dam bao MOI that bai deu hien ra man hinh: ve banner bang\n-- Instance.new thuan -> khong can NexusLib, khong can CoreGui, khong can console.\n-- ============================================================\ndo\n    local _rt = (getgenv and getgenv()) or _G\n\n    -- Don banner cua lan execute truoc\n    pcall(function()\n        if _rt.NexusBootGui then _rt.NexusBootGui:Destroy() end\n    end)\n    _rt.NexusBootGui = nil\n\n    local boot = { stage = \"bat dau\", done = false }\n    _rt.NexusBoot = boot\n\n    local execName = \"?\"\n    pcall(function()\n        if identifyexecutor then execName = tostring((identifyexecutor())) end\n    end)\n\n    -- Tim cho parent ScreenGui: uu tien gethui (duoc bao ve), roi PlayerGui,\n    -- cuoi cung CoreGui. Tat ca boc pcall vi 1 so executor chan CoreGui.\n    local function guiHome()\n        local tries = {\n            function() return gethui and gethui() end,\n            function() return game:GetService(\"Players\").LocalPlayer:FindFirstChild(\"PlayerGui\") end,\n            function() return game:GetService(\"Players\").LocalPlayer:WaitForChild(\"PlayerGui\", 10) end,\n            function() return game:GetService(\"CoreGui\") end,\n        }\n        for _, f in ipairs(tries) do\n            local ok, v = pcall(f)\n            if ok and typeof(v) == \"Instance\" then return v end\n        end\n        return nil\n    end\n\n    local function banner(title, body)\n        local home = guiHome()\n        if not home then return false end\n        local ok = pcall(function()\n            pcall(function()\n                if _rt.NexusBootGui then _rt.NexusBootGui:Destroy() end\n            end)\n            local sg = Instance.new(\"ScreenGui\")\n            sg.Name = \"NexusBootReport\"\n            sg.ResetOnSpawn = false\n            sg.IgnoreGuiInset = true\n            sg.DisplayOrder = 2147483647\n            sg.Parent = home\n            _rt.NexusBootGui = sg\n\n            local frame = Instance.new(\"Frame\")\n            frame.Size = UDim2.new(0, 400, 0, 175)\n            frame.Position = UDim2.new(0.5, -200, 0, 30)\n            frame.BackgroundColor3 = Color3.fromRGB(30, 21, 26)\n            frame.BorderSizePixel = 0\n            frame.Parent = sg\n\n            local corner = Instance.new(\"UICorner\")\n            corner.CornerRadius = UDim.new(0, 10)\n            corner.Parent = frame\n\n            local stroke = Instance.new(\"UIStroke\")\n            stroke.Color = Color3.fromRGB(232, 88, 100)\n            stroke.Thickness = 2\n            stroke.Parent = frame\n\n            local head = Instance.new(\"TextLabel\")\n            head.Size = UDim2.new(1, -20, 0, 26)\n            head.Position = UDim2.new(0, 12, 0, 9)\n            head.BackgroundTransparency = 1\n            head.Font = Enum.Font.GothamBold\n            head.TextSize = 16\n            head.TextColor3 = Color3.fromRGB(255, 122, 132)\n            head.TextXAlignment = Enum.TextXAlignment.Left\n            head.Text = tostring(title)\n            head.Parent = frame\n\n            local body2 = Instance.new(\"TextLabel\")\n            body2.Size = UDim2.new(1, -24, 1, -74)\n            body2.Position = UDim2.new(0, 12, 0, 38)\n            body2.BackgroundTransparency = 1\n            body2.Font = Enum.Font.Gotham\n            body2.TextSize = 13\n            body2.TextColor3 = Color3.fromRGB(236, 236, 242)\n            body2.TextWrapped = true\n            body2.TextXAlignment = Enum.TextXAlignment.Left\n            body2.TextYAlignment = Enum.TextYAlignment.Top\n            body2.Text = tostring(body)\n            body2.Parent = frame\n\n            local foot = Instance.new(\"TextLabel\")\n            foot.Size = UDim2.new(1, -100, 0, 16)\n            foot.Position = UDim2.new(0, 12, 1, -26)\n            foot.BackgroundTransparency = 1\n            foot.Font = Enum.Font.Gotham\n            foot.TextSize = 11\n            foot.TextColor3 = Color3.fromRGB(150, 150, 162)\n            foot.TextXAlignment = Enum.TextXAlignment.Left\n            foot.Text = \"executor: \" .. execName\n            foot.Parent = frame\n\n            local close = Instance.new(\"TextButton\")\n            close.Size = UDim2.new(0, 72, 0, 24)\n            close.Position = UDim2.new(1, -84, 1, -32)\n            close.BackgroundColor3 = Color3.fromRGB(62, 46, 53)\n            close.Font = Enum.Font.GothamBold\n            close.TextSize = 12\n            close.TextColor3 = Color3.fromRGB(255, 255, 255)\n            close.Text = \"Dong\"\n            close.AutoButtonColor = true\n            close.Parent = frame\n\n            local cc = Instance.new(\"UICorner\")\n            cc.CornerRadius = UDim.new(0, 6)\n            cc.Parent = close\n\n            close.MouseButton1Click:Connect(function()\n                pcall(function() sg:Destroy() end)\n            end)\n        end)\n        return ok\n    end\n\n    -- Bao loi ra MOI kenh co the co\n    _rt.NexusReport = function(title, body)\n        local line = \"[Nexus] \" .. tostring(title) .. \" | \" .. tostring(body)\n        pcall(function() print(line) end)\n        pcall(function() warn(line) end)\n        pcall(function() if rconsoleprint then rconsoleprint(line .. \"\\n\") end end)\n        pcall(function()\n            local slib = _rt.NexusLib\n            if slib and slib.Notify then\n                slib:Notify({ Title = tostring(title), Message = tostring(body), Duration = 14 })\n            end\n        end)\n        pcall(function() banner(title, body) end)\n    end\n\n    -- Danh dau dang o buoc nao (watchdog se in ra buoc nay neu treo)\n    _rt.NexusStage = function(name)\n        if _rt.NexusBoot == boot then boot.stage = tostring(name) end\n    end\n\n    -- Cho co cua so / con children -> bao ro thay vi treo im lang\n    _rt.NexusNeedChild = function(parent, childName, timeout)\n        timeout = timeout or 30\n        if typeof(parent) ~= \"Instance\" then\n            _rt.NexusReport(\"Nexus: failed to start\",\n                \"No parent to search for '\" .. tostring(childName) .. \"'.\")\n            return nil\n        end\n        local ok, inst = pcall(function()\n            return parent:WaitForChild(childName, timeout)\n        end)\n        if ok and inst then return inst end\n        _rt.NexusReport(\"Nexus: game data missing\",\n            \"Could not find '\" .. tostring(childName) .. \"' sau \" .. tostring(timeout) .. \"s.\\n\" ..\n            \"1) Wrong game? This script is only for [UPD] Heavyweight Fishing.\\n\" ..\n            \"2) If you just joined, wait for the game to load, then execute again.\")\n        return nil\n    end\n\n    -- WATCHDOG: 50s ma UI chua len -> bao dang tac o buoc nao.\n    -- Day la cai bat MOI loi chet im lang, ke ca loi tuong lai chua biet.\n    task.spawn(function()\n        for _ = 1, 50 do\n            task.wait(1)\n            if _rt.NexusBoot ~= boot then return end\n            if boot.done then return end\n        end\n        if _rt.NexusBoot ~= boot or boot.done then return end\n        _rt.NexusReport(\"Nexus: the script failed to start\",\n            \"Stopped at stage: \" .. tostring(boot.stage) .. \"\\n\" ..\n            \"Screenshot this panel and send it to the admin.\")\n    end)\nend\n-- ===== END BOOT DIAGNOSTIC =====\n\n-- ============================================================\n-- ===== ANTI-BYPASS GUARD (freemium) v2 =====\n-- Chan chay chua: phai co key hop le HOAC da duoc Key System xac thuc.\n-- An toan: khong kick khi loi mang / executor khong ho tro http.\n-- ============================================================\ndo\n    local _rt = (getgenv and getgenv()) or _G\n    pcall(function() _rt.NexusStage(\"key check\") end)\n\n    local Players = game:GetService(\"Players\")\n    local HttpService = game:GetService(\"HttpService\")\n    local LP = Players.LocalPlayer\n\n    -- Anti-Hook / Anti-Dump check\n    local _raw_loadstring = loadstring\n    local function isHooked(f)\n        if type(f) ~= \"function\" then return false end\n        if ishooked and ishooked(f) then return true end\n        return false\n    end\n    if isHooked(_raw_loadstring) or (loadstring and isHooked(loadstring)) then\n        LP:Kick(\"Nexus Security: loadstring tampering detected.\")\n        while true do task.wait(9999) end\n        return\n    end\n\n    local GUARD = {\n        API_URL = \"https://vgvaxescpirfdkrcamyk.supabase.co/functions/v1/key-system\",\n        PROTOCOL_VERSION = 3,\n        -- Freemium chi doc file FREEMIUM (khong doc file premium de tranh de lan)\n        KEY_FILES = { \"NexusFreemiumKey.txt\" },\n        TIMEOUT = 20,\n        RETRY = 2,\n        -- Doi thanh true neu muon: khong tim thay key thi VAN CHAY (che do offline).\n        OFFLINE_FALLBACK = true,\n    }\n\n    local function getHWID()\n        local candidates = {\n            function() return gethwid and gethwid() end,\n            function() return game:GetService(\"RbxAnalyticsService\"):GetClientId() end,\n        }\n        for _, getter in ipairs(candidates) do\n            local ok, value = pcall(getter)\n            if ok and type(value) == \"string\" and #value >= 8 then\n                return value .. \":\" .. tostring(LP.UserId)\n            end\n        end\n        return string.format(\"player:%d:place:%d\", LP.UserId, game.PlaceId)\n    end\n\n    local _raw_req = (syn and syn.request) or http_request or request or (fluxus and fluxus.request)\n    local function requestAdapter()\n        return _raw_req or (syn and syn.request) or http_request or request or (fluxus and fluxus.request)\n    end\n\n    local function api(action, fields)\n        local payload = fields or {}\n        payload.action = action\n        payload.protocol_version = GUARD.PROTOCOL_VERSION\n        payload.hwid = getHWID()\n        local lastErr = \"NETWORK_ERROR\"\n        for _ = 1, GUARD.RETRY do\n            local ok, result = pcall(function()\n                local requestFn = requestAdapter()\n                local encoded = HttpService:JSONEncode(payload)\n                if requestFn then\n                    local raw = requestFn({\n                        Url = GUARD.API_URL, Method = \"POST\",\n                        Headers = { [\"Content-Type\"] = \"application/json\" },\n                        Body = encoded, Timeout = GUARD.TIMEOUT,\n                    })\n                    return HttpService:JSONDecode(raw.Body or raw.body or \"{}\")\n                end\n                return nil -- khong co http adapter\n            end)\n            if ok and type(result) == \"table\" then return result end\n            task.wait(1)\n        end\n        return { ok = false, code = lastErr }\n    end\n\n    -- Doc key: uu tien getgenv().Key, sau do quet tat ca ten file ho tro\n    -- FIX: nguong 12 ky tu la doan mo -> key ngan hon 12 bi coi nhu KHONG CO\n    -- roi bi deny oan. Chi can khong rong; dung/sai de server phan xu.\n    local function trim(s)\n        return (tostring(s):gsub(\"^%s+\", \"\"):gsub(\"%s+$\", \"\"))\n    end\n    local function readKey()\n        if type(_rt.Key) == \"string\" then\n            local k = trim(_rt.Key)\n            if #k >= 4 then return k end\n        end\n        local found\n        for _, fname in ipairs(GUARD.KEY_FILES) do\n            pcall(function()\n                if not found and isfile and readfile and isfile(fname) then\n                    local s = readfile(fname)\n                    if type(s) == \"string\" and #trim(s) >= 4 then found = trim(s) end\n                end\n            end)\n            if found then break end\n        end\n        return found\n    end\n\n    local function notify(msg)\n        -- 1) print luon hoat dong tren moi executor\n        pcall(function() print(\"[Nexus Hub] \" .. tostring(msg)) end)\n        -- 2) NexusLib neu co (khong dung notify Roblox)\n        pcall(function()\n            local slib = _rt.NexusLib\n            if slib and slib.Notify then slib:Notify({ Title = \"Nexus Hub\", Message = msg, Duration = 6 }) end\n        end)\n    end\n\n    local function deny(reason)\n        notify(reason)\n        pcall(function()\n            if _rt.NexusReport then\n                _rt.NexusReport(\"Nexus: Thong bao key\", tostring(reason) ..\n                    \"\\n\\nExecute source truc tiep da bi KHOA. Phai dung loader hwfnew de vao.\")\n            end\n        end)\n        LP:Kick(\"Nexus: \" .. tostring(reason))\n    end\n\n    -- ================== B\u{1EA2}O V\u{1EC6} TOKEN HANDOFF CH\u{1ED0}NG BYPASS ==================\n    -- Ch\u{1ED1}ng tr\u{F2} bypass g\u{F5}: getgenv().NexusPremiumVerified = true\n    -- B\u{1EAF}t bu\u{1ED9}c ph\u{1EA3}i c\u{F3} Server Nonce h\u{1EE3}p l\u{1EC7} t\u{1EEB} Loader v\u{1EEB}a g\u{1EED}i sang v\u{E0} ti\u{EA}u th\u{1EE5} ngay (One-time token).\n    local serverNonce = _rt.NexusGuardNonce\n    _rt.NexusGuardNonce = nil -- Ti\u{EA}u th\u{1EE5} ngay l\u{1EAD}p t\u{1EE9}c token d\u{F9}ng 1 l\u{1EA7}n\n\n    local isValidHandoff = false\n    if type(serverNonce) == \"string\" and #serverNonce >= 8 then\n        -- C\u{F3} server token t\u{1EEB} loader g\u{1EED}i qua -> h\u{1EE3}p l\u{1EC7}\n        isValidHandoff = true\n    elseif (_rt.NexusPremiumVerified == true or _rt.NexusFreemiumVerified == true) and type(_rt.Key) == \"string\" and #_rt.Key >= 6 then\n        -- Fallback tr\u{1B0}\u{1EDD}ng h\u{1EE3}p loader c\u{169} nh\u{1B0}ng ph\u{1EA3}i k\u{E8}m theo Key h\u{1EE3}p l\u{1EC7} trong session\n        isValidHandoff = true\n    end\n\n    -- X\u{F3}a to\u{E0}n b\u{1ED9} c\u{1EDD} runtime \u{111}\u{1EC3} kh\u{F4}ng b\u{1ECB} t\u{E1}i s\u{1EED} d\u{1EE5}ng\n    _rt.NexusPremiumVerified = nil\n    _rt.NexusFreemiumVerified = nil\n    _rt.NexusMainLoaded = nil\n    _rt.NexusVerifiedTier = nil\n\n    if not isValidHandoff then\n        -- Execute source tr\u{1EF1}c ti\u{1EBF}p ho\u{1EB7}c c\u{1ED1} t\u{EC}nh set c\u{1EDD} gi\u{1EA3} m\u{1EA1}o -> KICK ngay\n        local reason = \"Bao mat: Khong the thuc thi source truc tiep. Phai qua loader chinh thuc!\"\n        notify(reason)\n        pcall(function()\n            if _rt.NexusReport then\n                _rt.NexusReport(\"Nexus Security\", reason)\n            end\n        end)\n        LP:Kick(\"Nexus: \" .. reason)\n        while true do task.wait(9999) end\n        return\n    end\n\n    _rt.NexusFreemiumVerified = true\nend\n-- ===== END ANTI-BYPASS GUARD =====\n\nlocal runtimeEnv = (getgenv and getgenv()) or _G\n\n-- ===== NEXUSLIB LOADER =====\npcall(function() runtimeEnv.NexusStage(\"tai NexusLib\") end)\nlocal NexusLib = runtimeEnv.NexusLib\nif not NexusLib then\n    local LIB_URL = \"https://raw.githubusercontent.com/Ngmankhoi/my-hub/main/NexusLib.lua\"\n    local source = nil\n    pcall(function()\n        if isfile and readfile and isfile(\"NexusLib.lua\") then\n            local s = readfile(\"NexusLib.lua\")\n            if type(s) == \"string\" and #s > 5000 and s:find(\"CreateWindow\", 1, true) then source = s end\n        end\n    end)\n    if not source then\n        local reqFn = (syn and syn.request) or http_request or request or (http and http.request) or (fluxus and fluxus.request)\n        if type(reqFn) == \"function\" then\n            pcall(function()\n                local r = reqFn({ Url = LIB_URL, Method = \"GET\" })\n                local body = r and (r.Body or r.body)\n                if type(body) == \"string\" and #body > 5000 then source = body end\n            end)\n        end\n    end\n    if not source then\n        pcall(function() local s = game:HttpGet(LIB_URL); if type(s) == \"string\" and #s > 5000 then source = s end end)\n    end\n    if not source then\n        pcall(function() local s = game:GetService(\"HttpService\"):GetAsync(LIB_URL); if type(s) == \"string\" and #s > 5000 then source = s end end)\n    end\n    if not source then\n        local msg = \"[Nexus] Could not download NexusLib. This executor lacks HTTP support.\"\n        pcall(function() print(msg) end)\n        pcall(function() runtimeEnv.NexusReport(\"Nexus Hub\", msg) end)\n        return\n    end\n    if type(loadstring) ~= \"function\" then\n        pcall(function() runtimeEnv.NexusReport(\"Nexus: executor not supported\", \"This executor has no loadstring -> the hub cannot run.\\nUse a different executor.\") end)\n        return\n    end\n    local chunk, compileErr = loadstring(source, \"@NexusLib.lua\")\n    if not chunk then\n        local msg = \"[Nexus] NexusLib compile error: \" .. tostring(compileErr)\n        pcall(function() print(msg) end)\n        pcall(function() runtimeEnv.NexusReport(\"Nexus Hub\", msg) end)\n        return\n    end\n    local ok, lib = pcall(chunk)\n    if not ok or type(lib) ~= \"table\" then\n        local msg = \"[Nexus] NexusLib runtime error: \" .. tostring(lib)\n        pcall(function() print(msg) end)\n        pcall(function() runtimeEnv.NexusReport(\"Nexus Hub\", msg) end)\n        return\n    end\n    NexusLib = lib\n    runtimeEnv.NexusLib = lib\nend\n\nif runtimeEnv.MinigameAnchorLock then pcall(function() runtimeEnv.MinigameAnchorLock:Disconnect() end) end\nif runtimeEnv.NexusFrameConnection then runtimeEnv.NexusFrameConnection:Disconnect() runtimeEnv.NexusFrameConnection = nil end\nif runtimeEnv.NexusBossFightThread then task.cancel(runtimeEnv.NexusBossFightThread) runtimeEnv.NexusBossFightThread = nil end\nif runtimeEnv.NexusFightEnzoThread then task.cancel(runtimeEnv.NexusFightEnzoThread) runtimeEnv.NexusFightEnzoThread = nil end\nif runtimeEnv.NexusRhyLoop then pcall(function() runtimeEnv.NexusRhyLoop:Disconnect() end) runtimeEnv.NexusRhyLoop = nil end\nif runtimeEnv.AntiAFKConnection then pcall(function() runtimeEnv.AntiAFKConnection:Disconnect() end) runtimeEnv.AntiAFKConnection = nil end\nif runtimeEnv.NexusSpaceGuardConnection then pcall(function() runtimeEnv.NexusSpaceGuardConnection:Disconnect() end) runtimeEnv.NexusSpaceGuardConnection = nil end\nif runtimeEnv.NexusSelectableGuardConnection then pcall(function() runtimeEnv.NexusSelectableGuardConnection:Disconnect() end) runtimeEnv.NexusSelectableGuardConnection = nil end\nif runtimeEnv.NexusNoclipConn then pcall(function() runtimeEnv.NexusNoclipConn:Disconnect() end) runtimeEnv.NexusNoclipConn = nil end\nif runtimeEnv.NexusMinigameConn then pcall(function() runtimeEnv.NexusMinigameConn:Disconnect() end) runtimeEnv.NexusMinigameConn = nil end\nif runtimeEnv.NexusSlamConn then pcall(function() runtimeEnv.NexusSlamConn:Disconnect() end) runtimeEnv.NexusSlamConn = nil end\n\n-- ===== SESSION EPOCH =====\nruntimeEnv.NexusEpoch = (runtimeEnv.NexusEpoch or 0) + 1\nlocal MY_EPOCH = runtimeEnv.NexusEpoch\nlocal function alive() return runtimeEnv.NexusEpoch == MY_EPOCH end\n\n-- ===== SERVICES =====\nlocal Services = {\n    Players = game:GetService(\"Players\"),\n    ReplicatedStorage = game:GetService(\"ReplicatedStorage\"),\n    RunService = game:GetService(\"RunService\"),\n    VirtualUser = game:GetService(\"VirtualUser\"),\n    UserInputService = game:GetService(\"UserInputService\"),\n    Lighting = game:GetService(\"Lighting\"),\n    TweenService = game:GetService(\"TweenService\"),\n    Workspace = game:GetService(\"Workspace\"),\n    Camera = game:GetService(\"Workspace\").CurrentCamera,\n    HttpService = game:GetService(\"HttpService\"),\n    GuiService = game:GetService(\"GuiService\"),\n    TeleportService = game:GetService(\"TeleportService\"),\n    RbxAnalyticsService = game:GetService(\"RbxAnalyticsService\"),\n}\nlocal Players = Services.Players\nlocal ReplicatedStorage = Services.ReplicatedStorage\nlocal RunService = Services.RunService\nlocal VirtualUser = Services.VirtualUser\nlocal UserInputService = Services.UserInputService\nlocal Lighting = Services.Lighting\nlocal TweenService = Services.TweenService\nlocal Workspace = Services.Workspace\nlocal Camera = Services.Camera\n\nlocal LocalPlayer = Players.LocalPlayer\n\n-- ===== GAME DATA =====\nruntimeEnv.NexusStage(\"waiting for game data (Events/MainGui/Info/Data)\")\nlocal Events = runtimeEnv.NexusNeedChild(ReplicatedStorage, \"Events\", 30)\nif not Events then return end\nlocal StartBossFight = Events:FindFirstChild(\"StartBossFight\")\nlocal BossPhase2Action = Events:FindFirstChild(\"BossPhase2Action\")\nlocal MainGui = runtimeEnv.NexusNeedChild(LocalPlayer:WaitForChild(\"PlayerGui\", 30), \"MainGui\", 30)\nif not MainGui then return end\nlocal Info = runtimeEnv.NexusNeedChild(ReplicatedStorage, \"Info\", 30)\nif not Info then return end\nlocal Data = runtimeEnv.NexusNeedChild(ReplicatedStorage, \"Data\", 30)\nif not Data then return end\n\nfor _, v in pairs(LocalPlayer:WaitForChild(\"PlayerGui\"):GetChildren()) do\n    if v.Name:find(\"MobileToggle\") then v:Destroy() end\nend\npcall(function()\n    for _, v in pairs(game:GetService(\"CoreGui\"):GetChildren()) do\n        if v.Name:find(\"MobileToggle\") then v:Destroy() end\n    end\nend)\n\nlocal CODES = {\n    \"BigUPD\", \"23MVisits\", \"24MVisits\", \"25MVisits\", \"26MVisits\",\n    \"42KLikes\", \"43KLikes\", \"44KLikes\", \"45KLikes\", \"UIBUG\"\n}\n\n-- ============================================================\n-- ===== STATE TABLE =====\n-- ============================================================\nlocal NexusState = {\n    Fishing = {\n        Flags = {\n            MainFarm = true,\n            AutoCast = false,\n            AutoSkill = false,\n            SelectedSkills = { \"Z\", \"X\", \"C\", \"V\" },\n            SkillMode = \"Spam\",\n            SkillSequence = \"Z,X,C,V\",\n            SkillDelay = 0.3,\n            AutoFarmBoss = false,\n            AutoFarmSecretBoss = false,\n            AnchorLock = false,\n            AntiAFK = false,\n            AutoSkillCheck = false,\n            BossFightMode = \"Normal\",\n            BossFightThread = nil,\n            AutoFightEnzo = false,\n            AutoFightLongDiaohai = false,\n            AutoLongDiaohai = false,\n            LongDiaohaiFightMode = \"Normal\",\n            LastCancel = 0,\n            LastFastCancel = 0,\n            LastProgress = 0,\n            LastNotify = \"\"\n        },\n   