\u{E14}\u{E34}\u{E19}\u{E17}\u{E30}\u{E25}\u{E38}\u{E01}\u{E33}\u{E41}\u{E1E}\u{E07}\",\n            [\"Full Bright\"] = \"\u{E40}\u{E1B}\u{E34}\u{E14}\u{E41}\u{E2A}\u{E07}\u{E2A}\u{E27}\u{E48}\u{E32}\u{E07}\u{E40}\u{E15}\u{E47}\u{E21}\u{E17}\u{E35}\u{E48}\",\n            [\"Fake Name Display\"] = \"\u{E40}\u{E1B}\u{E34}\u{E14}\u{E0A}\u{E37}\u{E48}\u{E2D}\u{E1B}\u{E25}\u{E2D}\u{E21}\u{E2A}\u{E15}\u{E23}\u{E35}\u{E21}\u{E40}\u{E21}\u{E2D}\u{E23}\u{E4C}\",\n            [\"Anti-Report Nexus Users\"] = \"\u{E1A}\u{E25}\u{E47}\u{E2D}\u{E01}\u{E01}\u{E32}\u{E23}\u{E23}\u{E32}\u{E22}\u{E07}\u{E32}\u{E19}\u{E1C}\u{E39}\u{E49}\u{E43}\u{E0A}\u{E49} Nexus\",\n            [\"Enable Staff Watch\"] = \"\u{E40}\u{E1B}\u{E34}\u{E14}\u{E15}\u{E23}\u{E27}\u{E08}\u{E08}\u{E31}\u{E1A} Staff\",\n            [\"Enable Notifications\"] = \"\u{E40}\u{E1B}\u{E34}\u{E14}\u{E01}\u{E32}\u{E23}\u{E41}\u{E08}\u{E49}\u{E07}\u{E40}\u{E15}\u{E37}\u{E2D}\u{E19}\",\n            [\"UI Language\"] = \"\u{E20}\u{E32}\u{E29}\u{E32} UI\",\n            [\"Skill Mode\"] = \"\u{E42}\u{E2B}\u{E21}\u{E14}\u{E2A}\u{E01}\u{E34}\u{E25}\",\n            [\"Skill Sequence Order\"] = \"\u{E25}\u{E33}\u{E14}\u{E31}\u{E1A}\u{E2A}\u{E01}\u{E34}\u{E25}\",\n            [\"Skill Delay (seconds)\"] = \"\u{E2B}\u{E19}\u{E48}\u{E27}\u{E07}\u{E40}\u{E27}\u{E25}\u{E32}\u{E2A}\u{E01}\u{E34}\u{E25} (\u{E27}\u{E34}\u{E19}\u{E32}\u{E17}\u{E35})\",\n            [\"Select Island\"] = \"\u{E40}\u{E25}\u{E37}\u{E2D}\u{E01}\u{E40}\u{E01}\u{E32}\u{E30}\",\n            [\"Buy Now\"] = \"\u{E0B}\u{E37}\u{E49}\u{E2D}\u{E17}\u{E31}\u{E19}\u{E17}\u{E35}\",\n            [\"Craft rod now\"] = \"\u{E04}\u{E23}\u{E32}\u{E1F}\u{E15}\u{E4C}\u{E40}\u{E1A}\u{E47}\u{E14}\u{E17}\u{E31}\u{E19}\u{E17}\u{E35}\",\n            [\"Craft bait now\"] = \"\u{E04}\u{E23}\u{E32}\u{E1F}\u{E15}\u{E4C}\u{E40}\u{E2B}\u{E22}\u{E37}\u{E48}\u{E2D}\u{E17}\u{E31}\u{E19}\u{E17}\u{E35}\",\n            [\"Exchange now\"] = \"\u{E41}\u{E25}\u{E01}\u{E40}\u{E1B}\u{E25}\u{E35}\u{E48}\u{E22}\u{E19}\u{E17}\u{E31}\u{E19}\u{E17}\u{E35}\"\n        },\n        id = {\n            [\"Session\"] = \"Sesi\",\n            [\"Routine\"] = \"Memancing\",\n            [\"Shop\"] = \"Toko\",\n            [\"Exchange\"] = \"Tukar\",\n            [\"Quests\"] = \"Misi\",\n            [\"Upgrade\"] = \"Peningkatan\",\n            [\"Teleport\"] = \"Teleportasi\",\n            [\"Settings\"] = \"Pengaturan\",\n            [\"Session overview\"] = \"Ringkasan Sesi\",\n            [\"Release notes\"] = \"Catatan Pembaruan\",\n            [\"Fishing routine\"] = \"Rutinitas Memancing\",\n            [\"Farm On Weather Section\"] = \"Auto Farm Cuaca Rahasia\",\n            [\"Skill profile\"] = \"Profil Skill\",\n            [\"Auto Equip\"] = \"Auto Pasang\",\n            [\"Auto Nameless Octoparasite\"] = \"Auto Gurita Tanpa Nama\",\n            [\"Auto Favorite Fish\"] = \"Auto Favoritkan Ikan\",\n            [\"Auto Pray Spirit\"] = \"Auto Doa ke Roh\",\n            [\"Auto Farm\"] = \"Auto Farm\",\n            [\"Index\"] = \"Indeks Ikan\",\n            [\"Upgrade Skill\"] = \"Tingkatkan Skill\",\n            [\"Craft Rod\"] = \"Buat Pancingan\",\n            [\"Auto Buy Bait\"] = \"Auto Beli Umpan\",\n            [\"Auto Buy Rod\"] = \"Auto Beli Pancingan\",\n            [\"Learn Skills\"] = \"Pelajari Skill\",\n            [\"Trait Reroll\"] = \"Reroll Sifat\",\n            [\"Craft Bait\"] = \"Buat Umpan\",\n            [\"Auto Gacha\"] = \"Auto Gacha\",\n            [\"Exchange Items\"] = \"Tukar Barang\",\n            [\"Auto Claim Ticket Quest\"] = \"Auto Klaim Misi Tiket\",\n            [\"Daily Quests\"] = \"Misi Harian\",\n            [\"Material Farming\"] = \"Farm Bahan\",\n            [\"Auto Do Ticket Quest\"] = \"Auto Jalankan Misi Tiket\",\n            [\"Character Upgrade\"] = \"Tingkatkan Karakter\",\n            [\"Character\"] = \"Karakter\",\n            [\"World & Misc\"] = \"Dunia & Lainnya\",\n            [\"Streamer Mode (Fake Name)\"] = \"Mode Streamer (Nama Palsu)\",\n            [\"Language & Localization\"] = \"Bahasa & Lokalisasi\",\n            [\"Nexus Shield\"] = \"Perisai Nexus\",\n            [\"Staff Watch\"] = \"Deteksi Staff\",\n            [\"ESP\"] = \"ESP\",\n            [\"Lock catch bar\"] = \"Kunci bilah tangkapan\",\n            [\"Auto Cast\"] = \"Lempar Otomatis\",\n            [\"Auto Farm Boss\"] = \"Auto Farm Boss\",\n            [\"Auto Farm Secret Boss\"] = \"Auto Farm Secret Boss\",\n            [\"Auto Skill\"] = \"Auto Skill\",\n            [\"Auto Sell Fish\"] = \"Auto Jual Ikan\",\n            [\"Auto Enzo\"] = \"Auto Enzo QTE\",\n            [\"Anti AFK\"] = \"Anti AFK\",\n            [\"Farm On Weather\"] = \"Auto Farm Berdasarkan Cuaca\",\n            [\"Auto Equip Best Bait\"] = \"Pasang Umpan Terbaik\",\n            [\"Auto Equip Fishing Rod (Slot 1)\"] = \"Pegang Pancingan Otomatis\",\n            [\"Auto Nameless\"] = \"Auto Tanpa Nama\",\n            [\"Auto Favourite Fishes\"] = \"Auto Favoritkan Ikan\",\n            [\"Auto Teleport + Interact (Pray) Spirit\"] = \"Auto Doa Roh\",\n            [\"Enable Auto Farm Fish\"] = \"Aktifkan Auto Farm\",\n            [\"Auto Do Daily Quest\"] = \"Auto Misi Harian\",\n            [\"Auto Do Ticket Quest (Fast)\"] = \"Auto Misi Tiket (Cepat)\",\n            [\"Auto Claim Ticket Quest (Fast)\"] = \"Auto Klaim Tiket (Cepat)\",\n            [\"Auto Rebirth\"] = \"Auto Kelahiran Kembali\",\n            [\"Auto craft bait\"] = \"Auto buat umpan\",\n            [\"Auto craft selected rod\"] = \"Auto buat pancingan\",\n            [\"Auto fish for bait materials\"] = \"Auto pancing bahan umpan\",\n            [\"Fly Mode\"] = \"Mode Terbang\",\n            [\"Walk On Water\"] = \"Berjalan di Atas Air\",\n            [\"Infinite Jump\"] = \"Lompat Tak Terbatas\",\n            [\"Noclip\"] = \"Noclip\",\n            [\"Full Bright\"] = \"Kecerahan Penuh\",\n            [\"Fake Name Display\"] = \"Nama Palsu Aktif\",\n            [\"Anti-Report Nexus Users\"] = \"Anti-Laporkan Pengguna Nexus\",\n            [\"Enable Staff Watch\"] = \"Aktifkan Deteksi Staff\",\n            [\"Enable Notifications\"] = \"Aktifkan Notifikasi\",\n            [\"UI Language\"] = \"Bahasa UI\",\n            [\"Skill Mode\"] = \"Mode Skill\",\n            [\"Skill Sequence Order\"] = \"Urutan Skill\",\n            [\"Skill Delay (seconds)\"] = \"Jeda Skill (detik)\",\n            [\"Select Island\"] = \"Pilih Pulau\",\n            [\"Buy Now\"] = \"Beli Sekarang\",\n            [\"Craft rod now\"] = \"Buat Pancingan Sekarang\",\n            [\"Craft bait now\"] = \"Buat Umpan Sekarang\",\n            [\"Exchange now\"] = \"Tukar Sekarang\"\n        }\n    }\n\n    function I18n.getCurrentLanguage()\n        if NexusState.currentLanguage == \"auto\" then\n            return NexusState.detectedLanguage or \"en\"\n        end\n        return NexusState.currentLanguage or \"en\"\n    end\n\n    function I18n.get(key, fallback)\n        if not key or type(key) ~= \"string\" then return fallback or key end\n        local lang = I18n.getCurrentLanguage()\n        if lang == \"en\" then return fallback or key end\n        local dict = DICTIONARY[lang]\n        if dict and dict[key] then return dict[key] end\n        return fallback or key\n    end\n\n    local function translateObject(obj)\n        if not obj or typeof(obj) ~= \"Instance\" then return end\n        local lang = I18n.getCurrentLanguage()\n        if lang == \"en\" then return end\n        pcall(function()\n            if (obj:IsA(\"TextLabel\") or obj:IsA(\"TextButton\") or obj:IsA(\"TextBox\")) then\n                local currentText = obj.Text\n                if not currentText or #currentText == 0 then return end\n                \n                local dict = DICTIONARY[lang]\n                \n                local orig = obj:GetAttribute(\"NexusOrigText\")\n                if not orig or (dict and dict[currentText]) then\n                    orig = currentText\n                    obj:SetAttribute(\"NexusOrigText\", orig)\n                end\n                \n                if orig and #orig > 0 then\n                    if lang == \"en\" then\n                        if obj.Text ~= orig then\n                            obj.Text = orig\n                        end\n                    else\n                        local trans = dict and dict[orig]\n                        if trans and obj.Text ~= trans then\n                            obj.Text = trans\n                        end\n                    end\n                end\n            end\n        end)\n    end\n\n    local function applyLanguageToGui(gui)\n        if not gui then return end\n        pcall(function()\n            for _, desc in ipairs(gui:GetDescendants()) do\n                translateObject(desc)\n            end\n        end)\n    end\n\n    function I18n.applyLanguage()\n        local pg = LocalPlayer:FindFirstChild(\"PlayerGui\")\n        if pg then\n            applyLanguageToGui(pg:FindFirstChild(\"NexusPanel\"))\n            applyLanguageToGui(pg:FindFirstChild(\"NexusNotifications\"))\n        end\n        pcall(function()\n            local cg = game:GetService(\"CoreGui\")\n            if cg then\n                applyLanguageToGui(cg:FindFirstChild(\"NexusPanel\"))\n                applyLanguageToGui(cg:FindFirstChild(\"NexusNotifications\"))\n            end\n        end)\n    end\n\n    function I18n.initListeners()\n        local function hookGui(gui)\n            if not gui then return end\n            gui.DescendantAdded:Connect(function(desc)\n                task.wait(0.03)\n                translateObject(desc)\n            end)\n        end\n\n        local pg = LocalPlayer:FindFirstChild(\"PlayerGui\")\n        if pg then\n            local panel = pg:FindFirstChild(\"NexusPanel\")\n            if panel then hookGui(panel) end\n            local notifs = pg:FindFirstChild(\"NexusNotifications\")\n            if notifs then hookGui(notifs) end\n\n            pg.ChildAdded:Connect(function(child)\n                if child.Name == \"NexusPanel\" or child.Name == \"NexusNotifications\" then\n                    hookGui(child)\n                    task.wait(0.1)\n                    applyLanguageToGui(child)\n                end\n            end)\n        end\n\n        pcall(function()\n            local cg = game:GetService(\"CoreGui\")\n            if cg then\n                local panel = cg:FindFirstChild(\"NexusPanel\")\n                if panel then hookGui(panel) end\n                local notifs = cg:FindFirstChild(\"NexusNotifications\")\n                if notifs then hookGui(notifs) end\n\n                cg.ChildAdded:Connect(function(child)\n                    if child.Name == \"NexusPanel\" or child.Name == \"NexusNotifications\" then\n                        hookGui(child)\n                        task.wait(0.1)\n                        applyLanguageToGui(child)\n                    end\n                end)\n            end\n        end)\n    end\nend\n\n-- ===== FAKE NAME (STREAMER MODE) CORE =====\n-- ============================================================\ndo\n    local realName = LocalPlayer.Name\n    local realDisplayName = LocalPlayer.DisplayName\n    local fakeNameConn = nil\n    local fakeNameThread = nil\n    local maskIdsInText -- forward declare (dinh nghia ben duoi)\n\n    local function replacePlain(text, find, repl)\n        if find == \"\" then return text end\n        local parts = {}\n        local start = 1\n        while true do\n            local s, e = string.find(text, find, start, true)\n            if not s then\n                table.insert(parts, string.sub(text, start))\n                break\n            end\n            table.insert(parts, string.sub(text, start, s - 1))\n            table.insert(parts, repl)\n            start = e + 1\n        end\n        return table.concat(parts)\n    end\n\n    local function replaceTextInObject(obj)\n        if not NexusState.fakeNameEnabled then return end\n        if not obj or typeof(obj) ~= \"Instance\" then return end\n        pcall(function()\n            if typeof(obj) == \"Instance\" and typeof(obj) == \"Instance\" and obj:IsA(\"TextLabel\") or obj:IsA(\"TextButton\") or obj:IsA(\"TextBox\") then\n                local text = obj.Text\n                if text and #text > 0 then\n                    local updated = false\n                    if realDisplayName ~= \"\" and string.find(text, realDisplayName, 1, true) then\n                        text = replacePlain(text, realDisplayName, NexusState.fakeDisplayName or \"NexusPlayer\")\n                        updated = true\n                    end\n                    if realName ~= \"\" and string.find(text, realName, 1, true) then\n                        text = replacePlain(text, realName, NexusState.fakeName or \"NexusPlayer\")\n                        updated = true\n                    end\n                    -- Guild display: doi ten guild that -> fake guild de khong bi ban\n                    if NexusState.realGuildName and #NexusState.realGuildName > 0 then\n                        local rg = tostring(NexusState.realGuildName)\n                        if rg ~= \"ZION\" and not string.find(text, \"ZION\", 1, true) and string.find(text, rg, 1, true) then\n                            text = replacePlain(text, rg, NexusState.fakeGuildName or \"NexusGuild\")\n                            updated = true\n                        end\n                    end\n                    -- Che luon ID (UserId / PlaceId / JobId) chu khong chi ten\n                    if maskIdsInText then\n                        local masked, idChanged = maskIdsInText(text)\n                        if idChanged then\n                            text = masked\n                            updated = true\n                        end\n                    end\n                    if updated then\n                        obj.Text = text\n                    end\n                end\n            end\n        end)\n    end\n\n    -- Che ID: doi ten khong thoi van bi report vi nguoi ta doc UserId / PlaceId /\n    -- JobId tren man hinh (hoac trong anh chup). Nen phai che luon cac ID nay.\n    local realUserId = tostring(LocalPlayer.UserId)\n    local realPlaceId = tostring(game.PlaceId)\n\n    function maskIdsInText(text)\n        if not NexusState.fakeNameEnabled then return text, false end\n        local changed = false\n        if #realUserId >= 5 and string.find(text, realUserId, 1, true) then\n            if (NexusState.fakeIdMode or 1) == 2 then\n                text = string.gsub(text, realUserId, \"****\")\n            else\n                text = string.gsub(text, realUserId, tostring(NexusState.fakeUserId or \"0\"))\n            end\n            changed = true\n        end\n        if #realPlaceId >= 5 and string.find(text, realPlaceId, 1, true) then\n            text = string.gsub(text, realPlaceId, \"0000000000\")\n            changed = true\n        end\n        local guidPat = \"%x%x%x%x%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%x%x%x%x%x%x%x%x\"\n        if string.find(text, guidPat) then\n            text = string.gsub(text, guidPat, \"********-****-****-****-************\")\n            changed = true\n        end\n        return text, changed\n    end\n\n    local function applyFakeNameToAll()\n        if not NexusState.fakeNameEnabled then return end\n        local pg = LocalPlayer:FindFirstChild(\"PlayerGui\")\n        if pg then\n            for _, v in ipairs(pg:GetDescendants()) do\n                replaceTextInObject(v)\n            end\n        end\n        local char = LocalPlayer.Character\n        if char then\n            for _, v in ipairs(char:GetDescendants()) do\n                replaceTextInObject(v)\n            end\n        end\n        pcall(function()\n            local cg = game:GetService(\"CoreGui\")\n            if cg then\n                for _, v in ipairs(cg:GetDescendants()) do\n                    replaceTextInObject(v)\n                end\n            end\n        end)\n    end\n\n    function NexusState.enableFakeName()\n        if NexusState.fakeNameEnabled then return end\n        NexusState.fakeNameEnabled = true\n        applyFakeNameToAll()\n\n        local pg = LocalPlayer:FindFirstChild(\"PlayerGui\")\n        if pg then\n            fakeNameConn = pg.DescendantAdded:Connect(function(desc)\n                if NexusState.fakeNameEnabled then\n                    task.wait(0.05)\n                    replaceTextInObject(desc)\n                end\n            end)\n        end\n\n        fakeNameThread = task.spawn(function()\n            while NexusState.fakeNameEnabled do\n                pcall(applyFakeNameToAll)\n                task.wait(1.5)\n            end\n        end)\n        NexusLib:Notify({ Title = \"Streamer Mode\", Message = \"Fake name active: \" .. tostring(NexusState.fakeName), Duration = 2 })\n    end\n\n    function NexusState.disableFakeName()\n        NexusState.fakeNameEnabled = false\n        if fakeNameConn then fakeNameConn:Disconnect(); fakeNameConn = nil end\n        if fakeNameThread then task.cancel(fakeNameThread); fakeNameThread = nil end\n        NexusLib:Notify({ Title = \"Streamer Mode\", Message = \"Fake name disabled\", Duration = 2 })\n    end\nend\n\n-- Chong \"cau tren troi\": khi dang bay / vua teleport, player lo lung tren khong\n-- nen phao khong roi trung nuoc -> cast phi hoai. Raycast xuong kiem tra nuoc.\nfunction NexusState.isOverWater()\n    local ok, result = pcall(function()\n        local char = LocalPlayer.Character\n        local root = char and char:FindFirstChild(\"HumanoidRootPart\")\n        if not root then return false end\n\n        local params = RaycastParams.new()\n        params.FilterType = Enum.RaycastFilterType.Exclude\n        params.FilterDescendantsInstances = { char }\n        params.IgnoreWater = false\n\n        local hit = Workspace:Raycast(root.Position, Vector3.new(0, -200, 0), params)\n        if not hit then return false end\n\n        if hit.Instance == Workspace.Terrain and hit.Material == Enum.Material.Water then\n            return true\n        end\n        local n = string.lower(hit.Instance.Name)\n        if string.find(n, \"water\") or string.find(n, \"ocean\") or string.find(n, \"sea\") then\n            return true\n        end\n        return false\n    end)\n    if not ok then return true end -- loi thi cho cast, khong chan oan\n    return result\nend\n\nfunction NexusState.canCastNow()\n    if NexusState.flying then return false end\n    -- Khi bat auto cast / farm boss / farm secret: tele len troi la chu y\n    -- (chong detect), vay isOverWater se false -> bo qua kiem tra nuoc,\n    -- chi chan khi dang fly thu cong.\n    local F = NexusState.Fishing and NexusState.Fishing.Flags\n    if F and (F.AutoCast or F.AutoFarmBoss or F.AutoFarmSecretBoss) then\n        return true\n    end\n    return NexusState.isOverWater()\nend\n\n-- ============================================================\n-- ===== UNIVERSAL BAIT MERCHANT LOCATOR =====\n-- ============================================================\nlocal function findBaitMerchantHRP()\n    local char = LocalPlayer.Character\n    local root = char and char:FindFirstChild(\"HumanoidRootPart\")\n    local myPos = root and root.Position or Vector3.new(0, 0, 0)\n    local bestHRP = nil\n    local bestDist = math.huge\n\n    pcall(function()\n        local npcFolder = Workspace:FindFirstChild(\"NPC\")\n        if npcFolder then\n            local bb = npcFolder:FindFirstChild(\"BuyBait\")\n            if bb then\n                for _, model in ipairs(bb:GetChildren()) do\n                    if typeof(model) == \"Instance\" and typeof(model) == \"Instance\" and model:IsA(\"Model\") then\n                        local hrp = model:FindFirstChild(\"HumanoidRootPart\") or model:FindFirstChild(\"Torso\") or model.PrimaryPart\n                        if hrp then\n                            local dist = (hrp.Position - myPos).Magnitude\n                            if dist < bestDist then\n                                bestDist = dist\n                                bestHRP = hrp\n                            end\n                        end\n                    end\n                end\n            end\n            local func = npcFolder:FindFirstChild(\"Function\")\n            if func then\n                for _, model in ipairs(func:GetChildren()) do\n                    if typeof(model) == \"Instance\" and typeof(model) == \"Instance\" and model:IsA(\"Model\") and (string.find(model.Name:lower(), \"bait\") or string.find(model.Name:lower(), \"shop\") or string.find(model.Name:lower(), \"merchant\")) then\n                        local hrp = model:FindFirstChild(\"HumanoidRootPart\") or model:FindFirstChild(\"Torso\") or model.PrimaryPart\n                        if hrp then\n                            local dist = (hrp.Position - myPos).Magnitude\n                            if dist < bestDist then\n                                bestDist = dist\n                                bestHRP = hrp\n                            end\n                        end\n                    end\n                end\n            end\n            if not bestHRP then\n                for _, desc in ipairs(npcFolder:GetDescendants()) do\n                    if typeof(desc) == \"Instance\" and typeof(desc) == \"Instance\" and desc:IsA(\"Model\") and string.find(desc.Name:lower(), \"bait\") then\n                        local hrp = desc:FindFirstChild(\"HumanoidRootPart\") or desc:FindFirstChild(\"Torso\") or desc.PrimaryPart\n                        if hrp then\n                            local dist = (hrp.Position - myPos).Magnitude\n                            if dist < bestDist then\n                                bestDist = dist\n                                bestHRP = hrp\n                            end\n                        end\n                    end\n                end\n            end\n        end\n    end)\n    return bestHRP\nend\n\n-- ===== BUILD MAIN UI =====\nruntimeEnv.NexusStage(\"dung UI\")\nlocal Window\ndo\n    local ok, result = pcall(function()\n        return NexusLib:CreateWindow({\n            Title = \"NEXUS\",\n            Subtitle = \"HEAVYWEIGHT FISHING - LIVE SESSION\",\n            Keybind = Enum.KeyCode.RightAlt,\n        })\n    end)\n    if not ok or type(result) ~= \"table\" then\n        runtimeEnv.NexusStage(\"UI window failed\")\n        runtimeEnv.NexusReport(\"Nexus UI failed\", \"CreateWindow: \" .. tostring(result))\n        return\n    end\n    Window = result\nend\n\nlocal Fishing = NexusState.Fishing\nlocal MiscFlags = NexusState.MiscFlags\n\n-- ============================================================\n-- ===== SHARED HELPERS (DECLARED UP FRONT) =====\n-- ============================================================\n\nlocal function GetPlayerData()\n    if not Data then return nil end\n    return Data:FindFirstChild(tostring(LocalPlayer.UserId))\nend\n\nlocal function GetModule(folder, name)\n    local m = folder:FindFirstChild(name)\n    if m then\n        local ok, mod = pcall(require, m)\n        if ok and type(mod) == \"table\" then return mod end\n    end\n    return nil\nend\n\nlocal function GetAvailableBaits()\n    local p = GetPlayerData()\n    if not p then return {} end\n    local baits = {}\n    local baitFolder = p:FindFirstChild(\"Bait\")\n    if not baitFolder then return {} end\n    for _, b in pairs(baitFolder:GetChildren()) do\n        if typeof(b) == \"Instance\" and typeof(b) == \"Instance\" and b:IsA(\"NumberValue\") and b.Value > 0 then\n            table.insert(baits, b.Name)\n        end\n    end\n    return baits\nend\n\nlocal function GetBaitStats(baitName)\n    local mod = GetModule(Info.Bait, baitName)\n    if mod then return {Luck = mod.Luck or 0} end\n    return {Luck = 0}\nend\n\nlocal function GetBestBait()\n    local baits = GetAvailableBaits()\n    local best, bestLuck = nil, -1\n    for _, name in ipairs(baits) do\n        local s = GetBaitStats(name)\n        if s.Luck > bestLuck then bestLuck = s.Luck; best = name end\n    end\n    return best\nend\n\nlocal function EquipBait(baitName)\n    if not baitName then return false end\n    return pcall(function() Events.EquipBait:InvokeServer(baitName) end)\nend\n\nlocal function GetOwnedRods()\n    local p = GetPlayerData()\n    if not p then return {} end\n    local rods = {}\n    for _, f in pairs(p.FishingRodInventory:GetChildren()) do\n        if typeof(f) == \"Instance\" and typeof(f) == \"Instance\" and f:IsA(\"Folder\") and f.Owned and f.Owned.Value == true then\n            table.insert(rods, f.Name)\n        end\n    end\n    return rods\nend\n\nlocal function GetRodStats(rodName)\n    local mod = GetModule(Info.Inventory, rodName)\n    if mod then return {Power = mod.Power or 0, Luck = mod.Luck or 0} end\n    return {Power = 0, Luck = 0}\nend\n\nlocal function GetBestRod()\n    local rods = GetOwnedRods()\n    local best, bestScore = nil, -1\n    for _, name in ipairs(rods) do\n        local s = GetRodStats(name)\n        local score = s.Power + s.Luck\n        if score > bestScore then bestScore = score; best = name end\n    end\n    return best\nend\n\nlocal function EquipRod(rodName)\n    if not rodName then return false end\n    return pcall(function() Events.EquipFishingRod:InvokeServer(rodName) end)\nend\n\nlocal function GetAvailableOrbs()\n    local p = GetPlayerData()\n    if not p then return {} end\n    local orbs = {}\n    local orbFolder = p:FindFirstChild(\"Orb\")\n    if not orbFolder then return {} end\n    for _, f in pairs(orbFolder:GetChildren()) do\n        if typeof(f) == \"Instance\" and typeof(f) == \"Instance\" and f:IsA(\"Folder\") then\n            local eq = f:FindFirstChild(\"Equipping\")\n            if eq and eq.Value == false then\n                table.insert(orbs, f.Name)\n            end\n        end\n    end\n    return orbs\nend\n\nlocal function GetOrbStats(orbName)\n    local p = GetPlayerData()\n    if not p then return {} end\n    local f = p.Orb:FindFirstChild(orbName)\n    if not f then return {} end\n    local stats = {}\n    for _, child in pairs(f:GetChildren()) do\n        if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"NumberValue\") and child.Name ~= \"Equipping\" and child.Name ~= \"Favorite\" then\n            stats[child.Name] = child.Value\n        end\n    end\n    return stats\nend\n\nlocal function GetBestOrb()\n    local orbs = GetAvailableOrbs()\n    local best, bestScore = nil, -1\n    for _, name in ipairs(orbs) do\n        local s = GetOrbStats(name)\n        local score = (s.Damage or 0) * 2 + (s.Luck or 0) * 1.5 + (s.Cash or 0) * 0.5\n        if score > bestScore then bestScore = score; best = name end\n    end\n    return best\nend\n\nlocal function EquipOrb(orbName)\n    if not orbName then return false end\n    return pcall(function() Events.EquipOrb:InvokeServer(orbName) end)\nend\n\n-- Parse one Data inventory child into (fishName, weightKg, count).\n-- Real server format: Name = \"FishName | 3500000 KG\" (may add \" | Favorite\"),\n-- Value = stack count (IntValue). Older format kept as fallback.\nlocal function parseCraftWeight(str)\n    if not str or str == \"\" then return nil end\n    local s = tostring(str):gsub(\"^%s+\", \"\"):gsub(\"%s+$\", \"\")\n    s = s:gsub(\"%s*[Kk][Gg]%s*$\", \"\")\n    s = s:gsub(\"^%s+\", \"\"):gsub(\"%s+$\", \"\")\n    local direct = tonumber(s)\n    if direct then return direct end\n    local num, suffix = s:match(\"^([%d%.]+)%s*([KkMmBbTt])%+?$\")\n    num = tonumber(num)\n    if not num then return nil end\n    local mult = { K = 1000, M = 1000000, B = 1000000000, T = 1000000000000 }\n    local m = mult[string.upper(suffix or \"\")]\n    if not m then return nil end\n    return num * m\nend\n\nlocal function parseCraftFishEntry(item)\n    if not item then return nil, nil, 0 end\n    local rawName = tostring(item.Name or \"\")\n    rawName = string.split(rawName, \"| Favorite\")[1]\n    local count = 1\n    pcall(function()\n        if type(item.Value) == \"number\" then count = item.Value end\n    end)\n    local parts = {}\n    for part in string.gmatch(rawName, \"[^|]+\") do table.insert(parts, part) end\n    local function trim(s) return tostring(s or \"\"):gsub(\"^%s+\", \"\"):gsub(\"%s+$\", \"\") end\n    local fishName = trim(parts[1])\n    local weight = nil\n    if #parts >= 2 then\n        weight = parseCraftWeight(string.split(trim(parts[2]), \" \")[1])\n    end\n    if not weight then\n        pcall(function()\n            local w = item:GetAttribute(\"Weight\")\n            if type(w) == \"number\" and w > 0 then weight = w end\n        end)\n    end\n    if (not weight) and type(item.Value) == \"string\" and string.find(item.Value, \"|\", 1, true) then\n        local vparts = {}\n        for part in string.gmatch(item.Value, \"[^|]+\") do table.insert(vparts, part) end\n        if #vparts >= 2 then\n            weight = parseCraftWeight(string.split(trim(vparts[2]), \" \")[1])\n        end\n        if fishName == \"\" and #vparts >= 1 then fishName = trim(vparts[1]) end\n    end\n    if fishName == \"\" then return nil, nil, 0 end\n    if type(count) ~= \"number\" or count < 1 then count = 1 end\n    return fishName, weight, math.floor(count)\nend\n\nlocal function GetBuyableBaits()\n    local _bbNow = tick()\n    if NexusState.cachedBuyableBaits and NexusState.cachedBuyableBaitsAt and (_bbNow - NexusState.cachedBuyableBaitsAt < 30) then\n        return NexusState.cachedBuyableBaits\n    end\n    local baits = {}\n    if not Info or not Info:FindFirstChild(\"Bait\") then return {\"No bait available\"} end\n    for _, child in pairs(Info.Bait:GetChildren()) do\n        if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"ModuleScript\") then\n            local success, mod = pcall(require, child)\n            if success and type(mod) == \"table\" and mod.Price and mod.Price > 0 then\n                table.insert(baits, child.Name)\n            end\n        end\n    end\n    if #baits == 0 then return {\"No bait available\"} end\n    NexusState.cachedBuyableBaits = baits\n    NexusState.cachedBuyableBaitsAt = _bbNow\n    return baits\nend\n\nlocal function saveRoutineFlags()\n    NexusState.savedRoutineFlags = {\n        AutoCast = Fishing.Flags.AutoCast,\n        AnchorLock = Fishing.Flags.AnchorLock,\n        AutoSkill = Fishing.Flags.AutoSkill,\n        AutoSell = MiscFlags.AutoSell,\n        AutoSkillCheck = Fishing.Flags.AutoSkillCheck,\n        AntiAFK = Fishing.Flags.AntiAFK,\n        AutoFarmBoss = Fishing.Flags.AutoFarmBoss,\n        AutoFarmSecretBoss = Fishing.Flags.AutoFarmSecretBoss,\n        AutoBuy = MiscFlags.AutoBuy,\n        AutoEquipBait = MiscFlags.AutoEquipBait,\n        AutoEquipRod = MiscFlags.AutoEquipRod,\n    }\nend\n\nlocal function restoreRoutineFlags()\n    if NexusState.savedRoutineFlags then\n        Fishing.Flags.AutoCast = NexusState.savedRoutineFlags.AutoCast\n        Fishing.Flags.AnchorLock = NexusState.savedRoutineFlags.AnchorLock\n        Fishing.Flags.AutoSkill = NexusState.savedRoutineFlags.AutoSkill\n        MiscFlags.AutoSell = NexusState.savedRoutineFlags.AutoSell\n        Fishing.Flags.AutoSkillCheck = NexusState.savedRoutineFlags.AutoSkillCheck\n        Fishing.Flags.AntiAFK = NexusState.savedRoutineFlags.AntiAFK\n        Fishing.Flags.AutoFarmBoss = NexusState.savedRoutineFlags.AutoFarmBoss\n        Fishing.Flags.AutoFarmSecretBoss = NexusState.savedRoutineFlags.AutoFarmSecretBoss\n        MiscFlags.AutoBuy = NexusState.savedRoutineFlags.AutoBuy\n        MiscFlags.AutoEquipBait = NexusState.savedRoutineFlags.AutoEquipBait\n        MiscFlags.AutoEquipRod = NexusState.savedRoutineFlags.AutoEquipRod\n        NexusState.savedRoutineFlags = nil\n    else\n        Fishing.Flags.AutoFarmBoss = false\n        Fishing.Flags.AutoFarmSecretBoss = false\n    end\nend\n\n-- Ticket fishing mode: auto cast + anchor lock + auto skill + rod equip,\n-- so turning on Auto Do Ticket is enough to work all 8 ticket quests.\nlocal function enableBasicFishing()\n    if not NexusState.savedRoutineFlags then saveRoutineFlags() end\n    Fishing.Flags.AutoCast = true\n    Fishing.Flags.AnchorLock = true\n    Fishing.Flags.AutoSkill = true\n    Fishing.Flags.AutoSkillCheck = true\n    MiscFlags.AutoEquipRod = true\nend\n\nlocal function disableAllFishing()\n    restoreRoutineFlags()\nend\n\n-- Teleport without the sky-drop freeze: a character held at +1000 sky sits in\n-- freefall, so AssemblyLinearVelocity grows huge. Carrying that velocity into a\n-- ground teleport slams the Humanoid into the floor and sticks it (frozen).\n-- Zero it on both ends and wake the Humanoid so movement resumes instantly.\nlocal function safeTeleport(hrp, cf)\n    if not hrp or not cf then return end\n    local model = hrp.Parent\n    local humanoid = model and model:FindFirstChildOfClass(\"Humanoid\")\n    -- Never freeze the live character: Anchored + task.wait() inside a\n    -- RenderStepped/Heartbeat-adjacent call stalls physics for a frame and\n    -- leaves the Humanoid seated/stuck, so walking looks frozen afterwards.\n    -- PivotTo moves the whole model atomically with no Anchored pin.\n    local ok = false\n    if model then\n        pcall(function()\n            model:PivotTo(cf)\n            ok = true\n        end)\n    end\n    if not ok then\n        pcall(function()\n            hrp.AssemblyLinearVelocity = Vector3.zero\n            hrp.AssemblyAngularVelocity = Vector3.zero\n            hrp.CFrame = cf\n        end)\n    end\n    pcall(function()\n        hrp.Anchored = false\n        hrp.AssemblyLinearVelocity = Vector3.zero\n        hrp.AssemblyAngularVelocity = Vector3.zero\n    end)\n    if humanoid then\n        pcall(function()\n            if humanoid.Seated then humanoid.Seated = false end\n            humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)\n        end)\n    end\nend\n\n-- ===== EGO + TIGER CHECK (dieu kien cho Island 11) =====\n-- Island 11 chi duoc recommend khi user co ca rod Ego va Tiger trong kho.\nlocal function hasEgoAndTiger()\n    local p = GetPlayerData()\n    if not p then return false end\n    local rodFolder = p:FindFirstChild(\"FishingRodInventory\") or p:FindFirstChild(\"Rod\")\n    if not rodFolder then return false end\n    local hasEgo, hasTiger = false, false\n    for _, f in pairs(rodFolder:GetChildren()) do\n        local n = string.lower(tostring(f.Name))\n        if string.find(n, \"ego\") then hasEgo = true end\n        if string.find(n, \"tiger\") then hasTiger = true end\n    end\n    return hasEgo and hasTiger\nend\n\nlocal function getTotalPower()\n    local _pwNow = tick()\n    if NexusState.cachedPower and NexusState.cachedPowerAt and (_pwNow - NexusState.cachedPowerAt < 5) then\n        return NexusState.cachedPower\n    end\n    local total = 0\n    local char = LocalPlayer.Character\n    if char then\n        local stats = char:FindFirstChild(\"Stats\")\n        if stats then\n            local rp = stats:FindFirstChild(\"RodPower\")\n            if typeof(rp) == \"Instance\" and rp:IsA(\"NumberValue\") then total = total + rp.Value end\n            local fp = stats:FindFirstChild(\"FishPower\")\n            if typeof(fp) == \"Instance\" and fp:IsA(\"NumberValue\") then total = total + fp.Value end\n        end\n        local attr = char:GetAttribute(\"RodPower\")\n        if attr and type(attr) == \"number\" and attr > 0 and total == 0 then total = attr end\n    end\n    if total == 0 then\n        local userId = LocalPlayer.UserId\n        local userData = Data:FindFirstChild(tostring(userId))\n        if userData then\n            local rodNameValue = userData:FindFirstChild(\"FishingRod\")\n            if rodNameValue then\n                local rodName = rodNameValue.Value\n                if rodName and rodName ~= \"\" then\n                    local rodModule = Info:FindFirstChild(\"Inventory\") and Info.Inventory:FindFirstChild(rodName)\n                    if rodModule then\n                        local success, rodData = pcall(require, rodModule)\n                        if success and type(rodData) == \"table\" then\n                            total = rodData.Power or 0\n                        end\n                    end\n                end\n            end\n        end\n    end\n    NexusState.cachedPower = total\n    NexusState.cachedPowerAt = _pwNow\n    return total\nend\n\nlocal function getRecommendedIsland()\n    local _rcNow = tick()\n    if NexusState.cachedRecommended and NexusState.cachedRecommendedAt and (_rcNow - NexusState.cachedRecommendedAt < 5) then\n        return NexusState.cachedRecommended\n    end\n    local currentPower = getTotalPower()\n    local eligible = {}\n    for _, island in ipairs(NexusState.islands) do\n        -- Island 11 (if u have ego and tiger): chi chon khi co ca rod Ego va Tiger\n        if island.name ~= \"Island 11\" or hasEgoAndTiger() then\n            if (island.power or 0) <= currentPower then\n                table.insert(eligible, island)\n            end\n        end\n    end\n    table.sort(eligible, function(a, b) return a.power > b.power end)\n    NexusState.cachedRecommended = eligible[2] or eligible[1]\n    NexusState.cachedRecommendedAt = _rcNow\n    return NexusState.cachedRecommended\nend\n\nlocal function isHoldingFishingRod()\n    local char = LocalPlayer.Character\n    if not char then return false end\n    local typ = char:GetAttribute(\"Type\")\n    if typ and string.lower(tostring(typ)) == \"fishing rod\" then return true end\n    return false\nend\n\n-- ============================================================\n\n-- ============================================================\n-- ===== CONFIG SYSTEM (save / load / auto-load / import-export) =====\n-- ============================================================\n-- Every Toggle / Dropdown / MultiDropdown / Textbox with a static English Name is\n-- registered here through Cfg.wrap(kind, name, config) at creation time. The config\n-- table itself is untouched (defaults still come from Default = ...), the registry\n-- only keeps the live handle so save/load can Get/Set values later.\n--\n-- Save format is a flat { [controlName] = value } table, JSON-encoded. Control\n-- names are unique across the whole hub (verified), so no tab/section prefix is\n-- needed and configs stay compatible even if a control moves sections.\ndo\n    local ConfigSys = {}\n    ConfigSys.registry = {}   -- [name] = { kind = \"toggle\"|\"dropdown\"|\"multi\"|\"text\", get = fn, set = fn }\n    ConfigSys.ordered = {}    -- registration order, for stable exports\n    ConfigSys.FILE = \"NexusHub_Config.json\"\n    ConfigSys.AUTO_FILE = \"NexusHub_AutoLoad.json\"\n    ConfigSys._saving = false\n\n    local function cfgKind(callKind)\n        if callKind == \"Toggle\" then return \"toggle\" end\n        if callKind == \"Dropdown\" then return \"dropdown\" end\n        if callKind == \"MultiDropdown\" then return \"multi\" end\n        return \"text\"\n    end\n\n    -- Wrap a control config table: pass through untouched, remember the name so\n    -- the returned handle can be registered right after creation.\n    function ConfigSys.wrap(callKind, name, config)\n        config = config or {}\n        config._CfgKind = callKind\n        config._CfgName = name\n        return config\n    end\n\n    function ConfigSys.register(handle, callKind, name, config)\n        if not handle or not name then return handle end\n        local kind = cfgKind(callKind)\n        local entry = ConfigSys.registry[name]\n        if not entry then\n            entry = { kind = kind }\n            ConfigSys.registry[name] = entry\n            table.insert(ConfigSys.ordered, name)\n        end\n        entry.kind = kind\n        -- The original Callback is captured here at registration time (from the\n        -- config table), because NexusLib handles do not expose it.\n        local cb = config and config.Callback or nil\n        if type(handle.Get) == \"function\" then\n            entry.get = function()\n                local ok, v = pcall(handle.Get)\n                return ok and v or nil\n            end\n        end\n        -- NOTE: NexusLib Set() implementations do NOT fire Callback (toggle Set\n        -- calls set(v, false); dropdown/text Set only touch the label). After\n        -- Set we therefore re-fire the captured Callback so the hub state\n        -- (Fishing.Flags, NexusState, ...) actually follows the loaded value.\n        if type(handle.Set) == \"function\" then\n            entry.set = function(v)\n                pcall(handle.Set, handle, v)\n                if cb then\n                    task.spawn(cb, v)\n                end\n            end\n        elseif cb then\n            entry.set = function(v)\n                task.spawn(cb, v)\n            end\n        end\n        return handle\n    end\n\n    function ConfigSys.snapshot()\n        local out = {}\n        for name, entry in pairs(ConfigSys.registry) do\n            if entry.get then\n                local ok, v = pcall(entry.get)\n                if ok and v ~= nil then out[name] = v end\n            end\n        end\n        return out\n    end\n\n    function ConfigSys.apply(data)\n        if type(data) ~= \"table\" then return 0, 0 end\n        local okCount, missCount = 0, 0\n        for name, value in pairs(data) do\n            local entry = ConfigSys.registry[name]\n            if entry and entry.set then\n                local ok = pcall(entry.set, value)\n                if ok then okCount = okCount + 1 else missCount = missCount + 1 end\n            else\n                missCount = missCount + 1\n            end\n        end\n        return okCount, missCount\n    end\n\n    local function encode(data)\n        local HttpService = Services.HttpService\n        local ok, s = pcall(HttpService.JSONEncode, HttpService, data)\n        return ok and s or nil\n    end\n\n    local function decode(s)\n        local HttpService = Services.HttpService\n        local ok, data = pcall(HttpService.JSONDecode, HttpService, s)\n        if ok and type(data) == \"table\" then return data end\n        return nil\n    end\n\n    function ConfigSys.save(slot)\n        local payload = encode({ version = 1, savedAt = os.time(), data = ConfigSys.snapshot() })\n        if not payload then\n            NexusLib:Notify({ Title = \"Config\", Message = \"Encode failed.\", Duration = 3 })\n            return false\n        end\n        if not writefile then\n            NexusLib:Notify({ Title = \"Config\", Message = \"This executor cannot save files.\", Duration = 3 })\n            return false\n        end\n        local ok = pcall(writefile, slot or ConfigSys.FILE, payload)\n        NexusLib:Notify({ Title = \"Config\", Message = ok and \"Saved.\" or \"Save failed.\", Duration = 2 })\n        return ok\n    end\n\n    function ConfigSys.load(slot, silent)\n        if not (isfile and readfile) then\n            if not silent then NexusLib:Notify({ Title = \"Config\", Message = \"This executor cannot read files.\", Duration = 3 }) end\n            return false\n        end\n        local path = slot or ConfigSys.FILE\n        local has = false\n        pcall(function() has = isfile(path) end)\n        if not has then\n            if not silent then NexusLib:Notify({ Title = \"Config\", Message = \"No saved config found.\", Duration = 3 }) end\n            return false\n        end\n        local ok, raw = pcall(readfile, path)\n        if not ok or not raw then\n            if not silent then NexusLib:Notify({ Title = \"Config\", Message = \"Read failed.\", Duration = 3 }) end\n            return false\n        end\n        local wrap = decode(raw)\n        local data = wrap and (wrap.data or wrap) or nil\n        if not data then\n            if not silent then NexusLib:Notify({ Title = \"Config\", Message = \"Config file is corrupt.\", Duration = 3 }) end\n            return false\n        end\n        -- Defer one frame so every tab has finished building its controls.\n        task.defer(function()\n            local okCount, missCount = ConfigSys.apply(data)\n            if not silent then\n                NexusLib:Notify({ Title = \"Config\", Message = \"Loaded \" .. okCount .. \" settings\" .. (missCount > 0 and \" (\" .. missCount .. \" skipped)\" or \"\") .. \".\", Duration = 3 })\n            end\n        end)\n        return true\n    end\n\n    function ConfigSys.exportCode()\n        local payload = encode({ version = 1, savedAt = os.time(), data = ConfigSys.snapshot() })\n        if not payload then return nil end\n        local clip = (syn and syn.write_clipboard) or setclipboard or toclipboard\n        if clip then\n            pcall(clip, payload)\n            NexusLib:Notify({ Title = \"Config\", Message = \"Config code copied to clipboard.\", Duration = 3 })\n        else\n            NexusLib:Notify({ Title = \"Config\", Message = \"Clipboard not supported on this executor.\", Duration = 3 })\n        end\n        return payload\n    end\n\n    -- Import reads the clipboard when the executor exposes it; otherwise it falls\n    -- back to the textbox value typed/pasted by the user.\n    function ConfigSys.importCode(text)\n        local code = text\n        if (not code or code == \"\") and getclipboard then\n            pcall(function() code = getclipboard() end)\n        end\n        if not code or code == \"\" then\n            NexusLib:Notify({ Title = \"Config\", Message = \"Paste a config code first.\", Duration = 3 })\n            return false\n        end\n        local wrap = decode(code)\n        local data = wrap and (wrap.data or wrap) or nil\n        if not data then\n            NexusLib:Notify({ Title = \"Config\", Message = \"Invalid config code.\", Duration = 3 })\n            return false\n        end\n        task.defer(function()\n            local okCount, missCount = ConfigSys.apply(data)\n            NexusLib:Notify({ Title = \"Config\", Message = \"Imported \" .. okCount .. \" settings\" .. (missCount > 0 and \" (\" .. missCount .. \" skipped)\" or \"\") .. \".\", Duration = 3 })\n        end)\n        return true\n    end\n\n    runtimeEnv.NexusConfig = ConfigSys\n    runtimeEnv.NexusCfgWrap = ConfigSys.wrap\n    ConfigSys._saving = false\nend\n\n\nlocal Cfg = runtimeEnv.NexusConfig\n\n-- ===== HOME TAB =====\n-- ============================================================\ndo\n    runtimeEnv.NexusStage(\"dung UI: Session tab\")\n    local HomeTab\n    do\n        local ok, result = pcall(function() return Window:CreateTab(\"Session\") end)\n        if not ok or result == nil then\n            runtimeEnv.NexusStage(\"UI Session tab failed\")\n            runtimeEnv.NexusReport(\"Nexus UI failed\", \"CreateTab Session: \" .. tostring(result))\n            return\n        end\n        HomeTab = result\n    end\n    HomeTab:CreateHeader({\n        Title = \"Session overview\",\n        Subtitle = \"Live instruments for \" .. LocalPlayer.Name\n    })\n    local statRow = HomeTab:CreateStatRow({\n        {Title = \"LEVEL\", Value = \"...\", Color = Color3.fromRGB(190, 158, 103)},\n        {Title = \"BALANCE\", Value = \"...\", Color = Color3.fromRGB(128, 159, 164)},\n        {Title = \"SESSION\", Value = \"00:00:00\", Color = Color3.fromRGB(139, 161, 142)}\n    })\n        -- Add 9 new stats\n    local statRow2 = HomeTab:CreateStatRow({\n        {Title = \"ROD\", Value = \"...\", Color = Color3.fromRGB(255, 215, 0)},\n        {Title = \"CRYSTAL\", Value = \"...\", Color = Color3.fromRGB(100, 200, 255)},\n        {Title = \"ESSENCE\", Value = \"...\", Color = Color3.fromRGB(255, 100, 200)}\n    })\n    local statRow3 = HomeTab:CreateStatRow({\n        {Title = \"BAIT\", Value = \"...\", Color = Color3.fromRGB(150, 255, 150)},\n        {Title = \"FISH CAUGHT\", Value = \"...\", Color = Color3.fromRGB(255, 200, 100)},\n        {Title = \"TICKET\", Value = \"...\", Color = Color3.fromRGB(200, 150, 255)}\n    })\n    local statRow4 = HomeTab:CreateStatRow({\n        {Title = \"TRAIT REROLL\", Value = \"...\", Color = Color3.fromRGB(255, 150, 150)},\n        {Title = \"HEAVIEST FISH\", Value = \"...\", Color = Color3.fromRGB(255, 180, 50)},\n        {Title = \"BASE HP\", Value = \"...\", Color = Color3.fromRGB(255, 100, 100)}\n    })\n    local hwid = \"N/A\"\n    pcall(function() hwid = Services.RbxAnalyticsService:GetClientId() end)\n    HomeTab:CreateFeaturedCard({\n        Tag = \"Nexus\",\n        Title = \"Heavyweight Fishing\",\n        Description = \"Script by: Ngmankhoi,NgdepZaiNhatTG,Ethangcuto\\n\\nHWID: \" .. string.sub(hwid, 1, 15) .. \"...\",\n        ButtonText = \"DISCORD\",\n        Callback = function()\n            NexusLib:Notify({ Title = \"Discord\", Message = \"Link copied to clipboard!\", Duration = 3 })\n            if setclipboard then setclipboard(\"https://discord.gg/QAdVUX2wCH\") end\n        end\n    })\n\n        local scriptStartTime = time()\n        task.spawn(function()\n        -- Cache for every stat row\n        local cachedStat1, cachedStat2, cachedStat3\n        local cachedStat2_1, cachedStat2_2, cachedStat2_3\n        local cachedStat3_1, cachedStat3_2, cachedStat3_3\n        local cachedStat4_1\n        local cachedStat4_2, cachedStat4_3\n        local labelCache = {}\n\n        local function setStat(statFrame, text)\n            if not statFrame then return end\n            local lbl = labelCache[statFrame]\n            if not lbl or not lbl.Parent then\n                for _, child in ipairs(statFrame:GetDescendants()) do\n                    if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"TextLabel\") and child.TextSize >= 18 then\n                        lbl = child\n                        labelCache[statFrame] = child\n                        break\n                    end\n                end\n            end\n            if lbl and lbl.Text ~= text then lbl.Text = text end\n        end\n\n        -- Stats fetch helper\n        local function getHomeStats()\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not userData then return {} end\n            local stats = {}\n            local levelFolder = userData:FindFirstChild(\"Level\")\n            stats.Level = levelFolder and levelFolder:FindFirstChild(\"Level\") and tostring(levelFolder.Level.Value) or \"N/A\"\n            stats.Cash = userData:FindFirstChild(\"Cash\") and tostring(userData.Cash.Value) or \"N/A\"\n            stats.Rod = userData:FindFirstChild(\"FishingRod\") and tostring(userData.FishingRod.Value) or \"N/A\"\n            stats.Crystal = userData:FindFirstChild(\"Crystal\") and tostring(userData.Crystal.Value) or \"N/A\"\n            stats.EssenceOrb = userData:FindFirstChild(\"EssenceOrb\") and tostring(userData.EssenceOrb.Value) or \"N/A\"\n            stats.Bait = userData:FindFirstChild(\"EquippedBait\") and tostring(userData.EquippedBait.Value) or \"N/A\"\n            stats.FishCaught = userData:FindFirstChild(\"FishCaught\") and tostring(userData.FishCaught.Value) or \"N/A\"\n            stats.Ticket = userData:FindFirstChild(\"Ticket\") and tostring(userData.Ticket.Value) or \"N/A\"\n            stats.TraitReroll = userData:FindFirstChild(\"Trait Reroll\") and tostring(userData[\"Trait Reroll\"].Value) or \"N/A\"\n            stats.HeaviestWeight = userData:FindFirstChild(\"HeaviestWeight\") and tostring(userData.HeaviestWeight.Value) or \"N/A\"\n            stats.BaseHP = userData:FindFirstChild(\"BaseHP\") and tostring(userData.BaseHP.Value) or \"N/A\"\n            return stats\n        end\n\n        while task.wait(1) do\n            if not alive() then break end\n            pcall(function()\n                local mg = MainGui\n                local leaderstats = LocalPlayer:FindFirstChild(\"leaderstats\")\n                local function readNumber(names)\n                    for _, name in ipairs(names) do\n                        local value = (leaderstats and leaderstats:FindFirstChild(name)) or LocalPlayer:GetAttribute(name)\n                        if value then\n                            local raw = (typeof(value) == \"Instance\" and value:IsA(\"ValueBase\")) and value.Value or value\n                            if type(raw) == \"number\" then return tostring(raw) end\n                        end\n                    end\n                    return nil\n                end\n\n                -- Level and Cash from leaderstats or the UI\n                local lvlText = readNumber({\"Level\", \"level\", \"LVL\"}) or \"N/A\"\n                if mg then\n                    local lvlNode = mg:FindFirstChild(\"Level\")\n                    if lvlNode then\n                        local val = lvlNode:FindFirstChild(\"Value\")\n                        if val and typeof(val) == \"Instance\" and val:IsA(\"TextLabel\") then\n                            local match = val.Text:match(\"Level:%s*(%d+)\")\n                            if match then lvlText = match else lvlText = val.Text end\n                        end\n                    end\n                end\n                local cashText = readNumber({\"Money\", \"Cash\", \"Coins\", \"Gold\", \"money\", \"cash\"}) or \"N/A\"\n                if mg then\n                    local cashNode = mg:FindFirstChild(\"Main\") and mg.Main:FindFirstChild(\"Stats\") and mg.Main.Stats:FindFirstChild(\"Cash\")\n                    if cashNode then\n                        local tl = cashNode:FindFirstChildOfClass(\"TextLabel\")\n                        if tl then cashText = tl.Text end\n                    end\n                end\n\n                -- Pull the 9 stats out of Data\n                local homeStats = getHomeStats()\n\n                -- Session time\n                local uptime = math.floor(time() - scriptStartTime)\n                local h = math.floor(uptime / 3600)\n                local m = math.floor((uptime % 3600) / 60)\n                local s = uptime % 60\n                local timeText = string.format(\"%02d:%02d:%02d\", h, m, s)\n\n                -- Update statRow1 (Level, Cash, Session)\n                if statRow and statRow._frame then\n                    if not cachedStat1 then\n                        cachedStat1 = statRow._frame:FindFirstChild(\"Stat_1\")\n                        cachedStat2 = statRow._frame:FindFirstChild(\"Stat_2\")\n                        cachedStat3 = statRow._frame:FindFirstChild(\"Stat_3\")\n                    end\n                    setStat(cachedStat1, lvlText)\n                    setStat(cachedStat2, cashText)\n                    setStat(cachedStat3, timeText)\n                end\n\n                -- Update statRow2 (Rod, Crystal, Essence)\n                if statRow2 and statRow2._frame then\n                    if not cachedStat2_1 then\n                        cachedStat2_1 = statRow2._frame:FindFirstChild(\"Stat_1\")\n                        cachedStat2_2 = statRow2._frame:FindFirstChild(\"Stat_2\")\n                        cachedStat2_3 = statRow2._frame:FindFirstChild(\"Stat_3\")\n                    end\n                    setStat(cachedStat2_1, homeStats.Rod)\n                    setStat(cachedStat2_2, homeStats.Crystal)\n                    setStat(cachedStat2_3, homeStats.EssenceOrb)\n                end\n\n                -- Update statRow3 (Bait, FishCaught, Ticket)\n                if statRow3 and statRow3._frame then\n                    if not cachedStat3_1 then\n                        cachedStat3_1 = statRow3._frame:FindFirstChild(\"Stat_1\")\n                        cachedStat3_2 = statRow3._frame:FindFirstChild(\"Stat_2\")\n                        cachedStat3_3 = statRow3._frame:FindFirstChild(\"Stat_3\")\n                    end\n                    setStat(cachedStat3_1, homeStats.Bait)\n                    setStat(cachedStat3_2, homeStats.FishCaught)\n                    setStat(cachedStat3_3, homeStats.Ticket)\n                end\n\n                -- Update statRow4 (TraitReroll)\n                if statRow4 and statRow4._frame then\n                    if not cachedStat4_1 then\n                        cachedStat4_1 = statRow4._frame:FindFirstChild(\"Stat_1\")\n                    end\n                    setStat(cachedStat4_1, homeStats.TraitReroll)\n                end\n\n                -- Update statRow5 (Heaviest Fish, BaseHP)\n                if statRow4 and statRow4._frame then\n                    if not cachedStat4_2 and not cachedStat4_3 then\n                        cachedStat4_2 = statRow4._frame:FindFirstChild(\"Stat_2\")\n                        cachedStat4_3 = statRow4._frame:FindFirstChild(\"Stat_3\")\n                    end\n                    setStat(cachedStat4_2, homeStats.HeaviestWeight)\n                    setStat(cachedStat4_3, homeStats.BaseHP)\n                end\n            end)\n        end\n    end)\nend\n\n-- ============================================================\n-- ===== ROUTINE TAB =====\n-- ============================================================\ndo\n    local FarmingTab = Window:CreateTab(\"Routine\")\n    local FarmSection = FarmingTab:CreateSection(\"Fishing routine\")\n\n    Cfg.register(FarmSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Lock catch bar\", { Name = \"Lock catch bar\", Default = false, Callback = function(V) Fishing.Flags.AnchorLock = V end })), \"Toggle\", \"Lock catch bar\", { Name = \"Lock catch bar\", Default = false, Callback = function(V) Fishing.Flags.AnchorLock = V end })\n    Cfg.register(FarmSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Cast\", { Name = \"Auto Cast\", Default = false, Callback = function(V) Fishing.Flags.AutoCast = V end })), \"Toggle\", \"Auto Cast\", { Name = \"Auto Cast\", Default = false, Callback = function(V) Fishing.Flags.AutoCast = V end })\n    Cfg.register(FarmSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Farm Boss\", { Name = \"Auto Farm Boss\", Default = false, Callback = function(V)\n        Fishing.Flags.AutoFarmBoss = V\n        if V then Fishing.Flags.AutoCast = false end\n        if not V and not Fishing.Flags.AutoFarmSecretBoss then\n            Fishing.BossFarm.CurrentTarget = nil\n            Fishing.BossFarm.CurrentType = nil\n            Fishing.BossFarm.CurrentToken = nil\n            Fishing.BossFarm.HasHooked = false\n            Fishing.BossFarm.PendingCancel = false\n            Fishing.BossFarm.CurrentRunId = Fishing.BossFarm.CurrentRunId + 1\n        end\n    end })), \"Toggle\", \"Auto Farm Boss\", { Name = \"Auto Farm Boss\", Default = false, Callback = function(V)\n        Fishing.Flags.AutoFarmBoss = V\n        if V then Fishing.Flags.AutoCast = false end\n        if not V and not Fishing.Flags.AutoFarmSecretBoss then\n            Fishing.BossFarm.CurrentTarget = nil\n            Fishing.BossFarm.CurrentType = nil\n            Fishing.BossFarm.CurrentToken = nil\n            Fishing.BossFarm.HasHooked = false\n            Fishing.BossFarm.PendingCancel = false\n            Fishing.BossFarm.CurrentRunId = Fishing.BossFarm.CurrentRunId + 1\n        end\n    end })\n    Cfg.register(FarmSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Farm Secret Boss\", { Name = \"Auto Farm Secret Boss\", Default = false, Callback = function(V)\n        Fishing.Flags.AutoFarmSecretBoss = V\n        if V then Fishing.Flags.AutoCast = false end\n        if not V and not Fishing.Flags.AutoFarmBoss then\n            Fishing.BossFarm.CurrentTarget = nil\n            Fishing.BossFarm.CurrentType = nil\n            Fishing.BossFarm.CurrentToken = nil\n            Fishing.BossFarm.HasHooked = false\n            Fishing.BossFarm.PendingCancel = false\n            Fishing.BossFarm.CurrentRunId = Fishing.BossFarm.CurrentRunId + 1\n        end\n    end })), \"Toggle\", \"Auto Farm Secret Boss\", { Name = \"Auto Farm Secret Boss\", Default = false, Callback = function(V)\n        Fishing.Flags.AutoFarmSecretBoss = V\n        if V then Fishing.Flags.AutoCast = false end\n        if not V and not Fishing.Flags.AutoFarmBoss then\n            Fishing.BossFarm.CurrentTarget = nil\n            Fishing.BossFarm.CurrentType = nil\n            Fishing.BossFarm.CurrentToken = nil\n            Fishing.BossFarm.HasHooked = false\n            Fishing.BossFarm.PendingCancel = false\n            Fishing.BossFarm.CurrentRunId = Fishing.BossFarm.CurrentRunId + 1\n        end\n    end })\n    Cfg.register(FarmSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Sell Fish\", { Name = \"Auto Sell Fish\", Default = false, Callback = function(V) MiscFlags.AutoSell = V end })), \"Toggle\", \"Auto Sell Fish\", { Name = \"Auto Sell Fish\", Default = false, Callback = function(V) MiscFlags.AutoSell = V end })\n    Cfg.register(FarmSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Method Sell #1\", {\n        Name = \"Method Sell #1\",\n        Options = {\"Spam\", \"When full\"},\n        Default = \"Spam\",\n        Callback = function(value) NexusState.sellMethod1 = value end\n    })), \"Dropdown\", \"Method Sell #1\", {\n        Name = \"Method Sell #1\",\n        Options = {\"Spam\", \"When full\"},\n        Default = \"Spam\",\n        Callback = function(value) NexusState.sellMethod1 = value end\n    })\n    Cfg.register(FarmSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Method Sell #2\", {\n        Name = \"Method Sell #2\",\n        Options = {\"Instant\", \"Teleport\"},\n        Default = \"Instant\",\n        Callback = function(value) NexusState.sellMethod2 = value end\n    })), \"Dropdown\", \"Method Sell #2\", {\n        Name = \"Method Sell #2\",\n        Options = {\"Instant\", \"Teleport\"},\n        Default