               NexusLib:Notify({ Title = \"Auto Equip Rod\", Message = \"Disabled\", Duration = 2 })\n            end\n        end\n    })), \"Toggle\", \"Auto Equip Fishing Rod (Slot 1)\", {\n        Name = \"Auto Equip Fishing Rod (Slot 1)\",\n        Default = false,\n        Callback = function(value)\n            MiscFlags.AutoEquipRod = value\n            if value then\n                NexusLib:Notify({ Title = \"Auto Equip Rod\", Message = \"Will equip rod if not holding\", Duration = 2 })\n            else\n                NexusLib:Notify({ Title = \"Auto Equip Rod\", Message = \"Disabled\", Duration = 2 })\n            end\n        end\n    })\n\n    task.spawn(function()\n        local ToggleHotbar = Events:FindFirstChild(\"ToggleHotbar\")\n        if not ToggleHotbar then return end\n        while task.wait(1) do\n            if not alive() then break end\n            if MiscFlags.AutoEquipRod then\n                pcall(function()\n                    if not isHoldingFishingRod() then\n                        ToggleHotbar:InvokeServer(\"1\", nil)\n                    end\n                end)\n            end\n        end\n    end)\n\n    EquipSection:CreateButton({\n        Name = \"Equip Best Rod\",\n        Callback = function()\n            local best = GetBestRod()\n            if best then\n                if EquipRod(best) then\n                    NexusLib:Notify({ Title = \"Equip Rod\", Message = \"Equipped best rod: \" .. best, Duration = 2 })\n                else\n                    NexusLib:Notify({ Title = \"Equip Rod\", Message = \"Failed to equip rod\", Duration = 2 })\n                end\n            else\n                NexusLib:Notify({ Title = \"Equip Rod\", Message = \"No rod available\", Duration = 2 })\n            end\n        end\n    })\n\n    EquipSection:CreateButton({\n        Name = \"Equip Best Orb\",\n        Callback = function()\n            local best = GetBestOrb()\n            if best then\n                if EquipOrb(best) then\n                    NexusLib:Notify({ Title = \"Equip Orb\", Message = \"Equipped best orb: \" .. best, Duration = 2 })\n                else\n                    NexusLib:Notify({ Title = \"Equip Orb\", Message = \"Failed to equip orb\", Duration = 2 })\n                end\n            else\n                NexusLib:Notify({ Title = \"Equip Orb\", Message = \"No orb available\", Duration = 2 })\n            end\n        end\n    })\n\n    task.spawn(function()\n        while task.wait(3) do\n            if MiscFlags.AutoEquipBait then\n                pcall(function()\n                    local userId = LocalPlayer.UserId\n                    local userData = Data:FindFirstChild(tostring(userId))\n                    if not userData then return end\n                    local equippedBaitValue = userData:FindFirstChild(\"EquippedBait\")\n                    if not equippedBaitValue then return end\n                    local currentBait = equippedBaitValue.Value or \"\"\n                    local best = GetBestBait()\n                    if best and best ~= currentBait then\n                        if EquipBait(best) then\n                            NexusLib:Notify({ Title = \"Auto Equip\", Message = \"Equipped best bait: \" .. best, Duration = 2 })\n                        end\n                    end\n                end)\n            end\n        end\n    end)\n\n    -- ===== AUTO NAMELESS OCTOPARASITE =====\n    do\n        local NAMELESS_NAME = \"Nameless Octoparasite\"\n        local RHY_LANES = { \"A\", \"S\", \"D\" }\n        local RHY_KEYS = { A = Enum.KeyCode.A, S = Enum.KeyCode.S, D = Enum.KeyCode.D }\n        local RHY_WINDOW = 0.22\n        local RHY_SPEED = 1.15 / 1.4\n        local RHY_BAR_FALLBACK = 0.85\n\n        NexusState.Nameless = {\n            Enabled = false,\n            Mode = \"Safe\",\n            RiskRate = 25,\n            Band = 0.08,\n            Lag = 0.03,\n            Active = false,\n            SignalUntil = 0,\n            Config = nil,\n            Method = nil,\n            RiskThread = nil,\n            NextPress = {},\n            Stats = { hit = 0, spam = 0 },\n        }\n        local Rhy = NexusState.Nameless\n\n        local function rhyFindNameless()\n            local roots = {}\n            local ocean = Workspace:FindFirstChild(\"Ocean\")\n            if ocean then\n                local boss = ocean:FindFirstChild(\"Boss\")\n                if boss then\n                    local fn = boss:FindFirstChild(\"FishName\")\n                    if fn then table.insert(roots, fn) end\n                    table.insert(roots, boss)\n                end\n                table.insert(roots, ocean)\n            end\n            local fishes = Workspace:FindFirstChild(\"Fishes\")\n            if fishes then table.insert(roots, fishes) end\n            for _, root in ipairs(roots) do\n                local ok, found = pcall(function() return root:FindFirstChild(NAMELESS_NAME, true) end)\n                if ok and found then return found end\n            end\n            return nil\n        end\n\n        local function rhyPivotOf(inst)\n            if not inst then return nil end\n            local ok, cf = pcall(function()\n                if typeof(inst) == \"Instance\" and typeof(inst) == \"Instance\" and inst:IsA(\"BasePart\") then return inst.CFrame end\n                if typeof(inst) == \"Instance\" and typeof(inst) == \"Instance\" and inst:IsA(\"Model\") then\n                    if inst.PrimaryPart then return inst.PrimaryPart.CFrame end\n                    return inst:GetPivot()\n                end\n                local part = inst:FindFirstChildWhichIsA(\"BasePart\", true)\n                if part then return part.CFrame end\n                return nil\n            end)\n            if ok and cf then return cf end\n            return nil\n        end\n\n        local function rhyTeleportToNameless()\n            local model = rhyFindNameless()\n            if not model then\n                NexusLib:Notify({ Title = \"Nameless\", Message = \"Cannot find \" .. NAMELESS_NAME .. \" in Workspace (boss not spawned yet?)\", Duration = 3 })\n                return false\n            end\n            local cf = rhyPivotOf(model)\n            if not cf then\n                NexusLib:Notify({ Title = \"Nameless\", Message = \"Found boss but could not get its position!\", Duration = 3 })\n                return false\n            end\n            local char = LocalPlayer.Character\n            local hrp = char and (char:FindFirstChild(\"HumanoidRootPart\") or char.PrimaryPart)\n            if not hrp then\n                NexusLib:Notify({ Title = \"Nameless\", Message = \"Character not found!\", Duration = 2 })\n                return false\n            end\n            hrp.CFrame = cf + Vector3.new(0, 12, 0)\n            NexusLib:Notify({ Title = \"Nameless\", Message = \"Teleported to \" .. NAMELESS_NAME, Duration = 2 })\n            return true\n        end\n\n        local function rhyPress(laneFrame, lane)\n            local methods = {\n                function()\n                    if not firesignal then return false end\n                    local btn = laneFrame and laneFrame:FindFirstChild(\"Button\")\n                    if not btn then return false end\n                    if not (typeof(btn) == \"Instance\" and (btn:IsA(\"TextButton\") or btn:IsA(\"ImageButton\"))) then return false end\n                    firesignal(btn.MouseButton1Click)\n                    return true\n                end,\n                function()\n                    local vim = game:GetService(\"VirtualInputManager\")\n                    vim:SendKeyEvent(true, RHY_KEYS[lane], false, game)\n                    vim:SendKeyEvent(false, RHY_KEYS[lane], false, game)\n                    return true\n                end,\n                function()\n                    local vim = game:GetService(\"VirtualInputManager\")\n                    vim:SendKeyEvent(true, RHY_KEYS[lane], false, nil)\n                    vim:SendKeyEvent(false, RHY_KEYS[lane], false, nil)\n                    return true\n                end,\n            }\n            if Rhy.Method then\n                local ok, res = pcall(methods[Rhy.Method])\n                if ok and res then return true end\n                Rhy.Method = nil\n            end\n            for i, fn in ipairs(methods) do\n                local ok, res = pcall(fn)\n                if ok and res then\n                    Rhy.Method = i\n                    return true\n                end\n            end\n            return false\n        end\n\n        local function rhyGui()\n            local fishing = MainGui and MainGui:FindFirstChild(\"Fishing\")\n            if not fishing then return nil, nil end\n            return fishing:FindFirstChild(\"Rhythm\"), fishing\n        end\n\n        local function rhyUiActive()\n            local gui, fishing = rhyGui()\n            if not gui or not fishing then return false end\n            return gui.Visible == true and fishing.Visible == true\n        end\n\n        local function rhyMaxBand()\n            local m = RHY_WINDOW - RHY_SPEED * (Rhy.Lag or 0) - 0.02\n            if m < 0.01 then m = 0.01 end\n            return m\n        end\n\n        local function rhyScan(now)\n            local gui = rhyGui()\n            if not gui then return end\n            for _, lane in ipairs(RHY_LANES) do\n                local laneFrame = gui:FindFirstChild(\"Progression\" .. lane)\n                if laneFrame then\n                    local barY = RHY_BAR_FALLBACK\n                    local barFrame = laneFrame:FindFirstChild(\"BarFrame\")\n                    if barFrame then\n                        local okB, y = pcall(function() return barFrame.Position.Y.Scale end)\n                        if okB and type(y) == \"number\" then barY = y end\n                    end\n                    local band = math.clamp(Rhy.Band, 0.01, rhyMaxBand())\n                    local inWindow = 0\n                    for _, note in ipairs(laneFrame:GetChildren()) do\n                        if note.Name == \"Note_FX\" then\n                            local okP, y = pcall(function() return note.Position.Y.Scale end)\n                            if okP and type(y) == \"number\" then\n                                if math.abs((y + RHY_SPEED * Rhy.Lag) - barY) <= band then\n                                    inWindow = inWindow + 1\n                                end\n                            end\n                        end\n                    end\n                    if inWindow > 5 then inWindow = 5 end\n                    for _ = 1, inWindow do\n                        if rhyPress(laneFrame, lane) then\n                            Rhy.Stats.hit = Rhy.Stats.hit + 1\n                        end\n                    end\n                end\n            end\n        end\n\n        local function rhyStartRisk()\n            if Rhy.RiskThread then return end\n            Rhy.RiskThread = task.spawn(function()\n                while alive() and Rhy.Enabled and Rhy.Mode == \"Risk\" and Rhy.Active do\n                    local rate = math.clamp(tonumber(Rhy.RiskRate) or 25, 1, 200)\n                    local burst = math.max(1, math.floor(rate / 20))\n                    for _ = 1, burst do\n                        pcall(function() Events.RhythmHit:FireServer(\"hit\") end)\n                        Rhy.Stats.spam = Rhy.Stats.spam + 1\n                    end\n                    task.wait(burst / rate)\n                end\n                Rhy.RiskThread = nil\n            end)\n        end\n\n        if runtimeEnv.NexusRhyStart then pcall(function() runtimeEnv.NexusRhyStart:Disconnect() end) end\n        if runtimeEnv.NexusRhyStop then pcall(function() runtimeEnv.NexusRhyStop:Disconnect() end) end\n        if runtimeEnv.NexusRhyLoop then pcall(function() runtimeEnv.NexusRhyLoop:Disconnect() end) end\n        if runtimeEnv.NexusNamelessBGM then pcall(function() runtimeEnv.NexusNamelessBGM:Disconnect() end) end\n        if runtimeEnv.NexusNamelessP2 then pcall(function() runtimeEnv.NexusNamelessP2:Disconnect() end) end\n\n        pcall(function()\n            local evStart = Events:FindFirstChild(\"RhythmStart\")\n            if evStart then\n                runtimeEnv.NexusRhyStart = evStart.OnClientEvent:Connect(function(cfg)\n                    if not alive() then return end\n                    Rhy.Config = cfg\n                    Rhy.Active = true\n                    Rhy.SignalUntil = tick() + 8\n                    Rhy.Stats = { hit = 0, spam = 0 }\n                    Rhy.NextPress = {}\n                    if Rhy.Enabled then\n                        local hp = cfg and (cfg.FinalMaxHP or cfg.HPFinalPhase)\n                        NexusLib:Notify({\n                            Title = \"Auto Nameless\",\n                            Message = \"Nameless started [\" .. tostring(Rhy.Mode) .. \"]\" .. (hp and (\" | HP \" .. tostring(hp)) or \"\"),\n                            Duration = 3,\n                        })\n                        if Rhy.Mode == \"Risk\" then rhyStartRisk() end\n                    end\n                end)\n            end\n            local evStop = Events:FindFirstChild(\"RhythmStop\")\n            if evStop then\n                runtimeEnv.NexusRhyStop = evStop.OnClientEvent:Connect(function()\n                    Rhy.Active = false\n                    Rhy.SignalUntil = 0\n                end)\n            end\n        end)\n\n        -- Nameless remotes captured after kill (remote.txt): BossPhaseBGM(name, sound) + BossPhase2Setup().\n        -- Arm the minigame on either remote so Auto Nameless works even when RhythmStart is late/missing.\n        pcall(function()\n            local evBGM = Events:FindFirstChild(\"BossPhaseBGM\")\n            if evBGM then\n                runtimeEnv.NexusNamelessBGM = evBGM.OnClientEvent:Connect(function(bossName, _sound)\n                    if not alive() then return end\n                    if bossName ~= nil and tostring(bossName) ~= \"Nameless Octoparasite\" then return end\n                    Rhy.Active = true\n                    Rhy.SignalUntil = tick() + 8\n                    if Rhy.Enabled then\n                        NexusLib:Notify({ Title = \"Auto Nameless\", Message = \"Nameless boss signal [\" .. tostring(Rhy.Mode) .. \"]\", Duration = 3 })\n                    end\n                end)\n            end\n            local evP2 = Events:FindFirstChild(\"BossPhase2Setup\")\n            if evP2 then\n                runtimeEnv.NexusNamelessP2 = evP2.OnClientEvent:Connect(function()\n                    if not alive() then return end\n                    Rhy.Active = true\n                    Rhy.SignalUntil = tick() + 8\n                    if Rhy.Enabled then\n                        NexusLib:Notify({ Title = \"Auto Nameless\", Message = \"Nameless phase 2 [\" .. tostring(Rhy.Mode) .. \"]\", Duration = 3 })\n                    end\n                end)\n            end\n        end)\n\n\n        runtimeEnv.NexusRhyLoop = RunService.Heartbeat:Connect(function()\n            if not alive() or not Rhy.Enabled then return end\n            local now = tick()\n            Rhy.Active = rhyUiActive() or now < (Rhy.SignalUntil or 0)\n            if not Rhy.Active then return end\n            if Rhy.Mode == \"Risk\" then rhyStartRisk() end\n            rhyScan(now)\n        end)\n\n        local NamelessSection = FarmingTab:CreateSection(\"Auto Nameless Octoparasite\")\n        NamelessSection:CreateButton({\n            Name = \"Teleport to Nameless Octoparasite\",\n            Callback = function() pcall(rhyTeleportToNameless) end\n        })\n        Cfg.register(NamelessSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Nameless\", {\n            Name = \"Auto Nameless\",\n            Default = false,\n            Callback = function(value)\n                Rhy.Enabled = value\n                if value then\n                    NexusLib:Notify({ Title = \"Auto Nameless\", Message = \"Enabled [\" .. tostring(Rhy.Mode) .. \"]. Waiting for Nameless signal from server.\", Duration = 3 })\n                    if Rhy.Active and Rhy.Mode == \"Risk\" then rhyStartRisk() end\n                else\n                    Rhy.Active = false\n                    Rhy.SignalUntil = 0\n                    NexusLib:Notify({ Title = \"Auto Nameless\", Message = \"Disabled | hit \" .. tostring(Rhy.Stats.hit) .. \" | remote \" .. tostring(Rhy.Stats.spam), Duration = 3 })\n                end\n            end\n        })), \"Toggle\", \"Auto Nameless\", {\n            Name = \"Auto Nameless\",\n            Default = false,\n            Callback = function(value)\n                Rhy.Enabled = value\n                if value then\n                    NexusLib:Notify({ Title = \"Auto Nameless\", Message = \"Enabled [\" .. tostring(Rhy.Mode) .. \"]. Waiting for Nameless signal from server.\", Duration = 3 })\n                    if Rhy.Active and Rhy.Mode == \"Risk\" then rhyStartRisk() end\n                else\n                    Rhy.Active = false\n                    Rhy.SignalUntil = 0\n                    NexusLib:Notify({ Title = \"Auto Nameless\", Message = \"Disabled | hit \" .. tostring(Rhy.Stats.hit) .. \" | remote \" .. tostring(Rhy.Stats.spam), Duration = 3 })\n                end\n            end\n        })\n    end\n\n    -- ===== FAVORITES =====\n    do\n        local FavSection = FarmingTab:CreateSection(\"Auto Favorite Fish\")\n        local allFishNames = {}\n        pcall(function()\n            local rarityModule = require(Info.FishingAreaRarity)\n            if type(rarityModule) == \"table\" then\n                for _, fishTable in pairs(rarityModule) do\n                    if type(fishTable) == \"table\" then\n                        for fishName in pairs(fishTable) do\n                            if type(fishName) == \"string\" and fishName ~= \"\" then\n                                table.insert(allFishNames, fishName)\n                            end\n                        end\n                    end\n                end\n            end\n        end)\n        local uniqueFish = {}\n        for _, name in ipairs(allFishNames) do uniqueFish[name] = true end\n        local fishOptions = {}\n        for name in pairs(uniqueFish) do table.insert(fishOptions, name) end\n        table.sort(fishOptions)\n\n        local fishDropdown = Cfg.register(FavSection:CreateMultiDropdown(Cfg.wrap(\"MultiDropdown\", \"Select fish to auto-favourite\", {\n            Name = \"Select fish to auto-favourite\",\n            Options = fishOptions,\n            Default = NexusState.favorites.selectedFish or {},\n            Callback = function(values) NexusState.favorites.selectedFish = values end\n        })), \"MultiDropdown\", \"Select fish to auto-favourite\", {\n            Name = \"Select fish to auto-favourite\",\n            Options = fishOptions,\n            Default = NexusState.favorites.selectedFish or {},\n            Callback = function(values) NexusState.favorites.selectedFish = values end\n        })\n\n        local autoFavToggle = Cfg.register(FavSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Favourite Fishes\", {\n            Name = \"Auto Favourite Fishes\",\n            Default = false,\n            Callback = function(value)\n                NexusState.favorites.autoEnabled = value\n                if value then\n                    if NexusState.favorites.thread then\n                        task.cancel(NexusState.favorites.thread)\n                        NexusState.favorites.thread = nil\n                    end\n                    NexusState.favorites.thread = task.spawn(function()\n                        local favoriteEvent = Events:FindFirstChild(\"FavoriteItem\")\n                        if not favoriteEvent then\n                            NexusLib:Notify({ Title = \"Auto Favourite\", Message = \"FavoriteItem remote not found!\", Duration = 3 })\n                            NexusState.favorites.autoEnabled = false\n                            if autoFavToggle and type(autoFavToggle.SetValue) == \"function\" then\n                                autoFavToggle:SetValue(false)\n                            end\n                            return\n                        end\n                        while NexusState.favorites.autoEnabled do\n                            pcall(function()\n                                local userId = LocalPlayer.UserId\n                                local userData = Data:FindFirstChild(tostring(userId))\n                                if not userData then return end\n                                local inventory = userData:FindFirstChild(\"Inventory\")\n                                if not inventory then return end\n                                local selected = NexusState.favorites.selectedFish or {}\n                                if #selected == 0 then return end\n                                local selectedSet = {}\n                                for _, name in ipairs(selected) do selectedSet[name] = true end\n                                for _, item in pairs(inventory:GetChildren()) do\n                                    local fullName = item.Name\n                                    if not string.find(fullName, \"| Favorite$\") then\n                                        local fishName = fullName:match(\"^(.-)%s*|\") or fullName\n                                        if selectedSet[fishName] then\n                                            favoriteEvent:FireServer(fullName)\n                                        end\n                                    end\n                                end\n                            end)\n                            task.wait(0.3)\n                        end\n                    end)\n                    NexusLib:Notify({ Title = \"Auto Favourite\", Message = \"Enabled - scanning every 0.3s\", Duration = 2 })\n                else\n                    if NexusState.favorites.thread then\n                        task.cancel(NexusState.favorites.thread)\n                        NexusState.favorites.thread = nil\n                    end\n                    NexusLib:Notify({ Title = \"Auto Favourite\", Message = \"Disabled\", Duration = 2 })\n                end\n            end\n        })), \"Toggle\", \"Auto Favourite Fishes\", {\n            Name = \"Auto Favourite Fishes\",\n            Default = false,\n            Callback = function(value)\n                NexusState.favorites.autoEnabled = value\n                if value then\n                    if NexusState.favorites.thread then\n                        task.cancel(NexusState.favorites.thread)\n                        NexusState.favorites.thread = nil\n                    end\n                    NexusState.favorites.thread = task.spawn(function()\n                        local favoriteEvent = Events:FindFirstChild(\"FavoriteItem\")\n                        if not favoriteEvent then\n                            NexusLib:Notify({ Title = \"Auto Favourite\", Message = \"FavoriteItem remote not found!\", Duration = 3 })\n                            NexusState.favorites.autoEnabled = false\n                            if autoFavToggle and type(autoFavToggle.SetValue) == \"function\" then\n                                autoFavToggle:SetValue(false)\n                            end\n                            return\n                        end\n                        while NexusState.favorites.autoEnabled do\n                            pcall(function()\n                                local userId = LocalPlayer.UserId\n                                local userData = Data:FindFirstChild(tostring(userId))\n                                if not userData then return end\n                                local inventory = userData:FindFirstChild(\"Inventory\")\n                                if not inventory then return end\n                                local selected = NexusState.favorites.selectedFish or {}\n                                if #selected == 0 then return end\n                                local selectedSet = {}\n                                for _, name in ipairs(selected) do selectedSet[name] = true end\n                                for _, item in pairs(inventory:GetChildren()) do\n                                    local fullName = item.Name\n                                    if not string.find(fullName, \"| Favorite$\") then\n                                        local fishName = fullName:match(\"^(.-)%s*|\") or fullName\n                                        if selectedSet[fishName] then\n                                            favoriteEvent:FireServer(fullName)\n                                        end\n                                    end\n                                end\n                            end)\n                            task.wait(0.3)\n                        end\n                    end)\n                    NexusLib:Notify({ Title = \"Auto Favourite\", Message = \"Enabled - scanning every 0.3s\", Duration = 2 })\n                else\n                    if NexusState.favorites.thread then\n                        task.cancel(NexusState.favorites.thread)\n                        NexusState.favorites.thread = nil\n                    end\n                    NexusLib:Notify({ Title = \"Auto Favourite\", Message = \"Disabled\", Duration = 2 })\n                end\n            end\n        })\n    end\n    -- ===== AUTO PRAY SPIRIT =====\n    do\n        local PraySection = FarmingTab:CreateSection(\"Auto Pray Spirit\")\n        local prayEnabled = false\n        local prayThread = nil\n        local prayConnections = {}\n        local lastInteractTime = 0\n        local cooldown = 2 -- seconds between interactions\n\n        -- Scan and handle spirits\n        local function scanAndPray()\n            local godFolder = workspace:FindFirstChild(\"NPC\") and workspace.NPC:FindFirstChild(\"God\")\n            if not godFolder then return end\n\n            local now = tick()\n            if now - lastInteractTime < cooldown then return end\n\n            -- Find every model in the God folder (sub-models included)\n            local models = {}\n            for _, child in ipairs(godFolder:GetDescendants()) do\n                if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"Model\") then\n                    table.insert(models, child)\n                end\n            end\n\n            for _, model in ipairs(models) do\n                -- Find HumanoidRootPart or PrimaryPart\n                local hrp = model:FindFirstChild(\"HumanoidRootPart\")\n                if not hrp then\n                    hrp = model.PrimaryPart\n                end\n                if hrp then\n                -- Find Talk and ProximityPrompt\n                local talk = hrp:FindFirstChild(\"Talk\")\n                if talk then\n                local prompt = talk:FindFirstChild(\"ProximityPrompt\")\n                if prompt then\n                -- Configure ProximityPrompt\n                pcall(function()\n                    prompt.RequiresLineOfSight = false\n                    prompt.HoldDuration = 0\n                end)\n\n                -- Teleport to the spirit position\n                local char = LocalPlayer.Character\n                if char then\n                    local root = char:FindFirstChild(\"HumanoidRootPart\")\n                    if root then\n                        root.CFrame = hrp.CFrame + Vector3.new(0, 2, 0)\n                    end\n                end\n\n                -- Trigger ProximityPrompt\n                local success = false\n                -- Cach 1: Fire Proximity Prompt\n                if fireproximityprompt and prompt then\n                    pcall(function()\n                        fireproximityprompt(prompt)\n                        success = true\n                    end)\n                end\n                -- Method 2: firesignal\n                if firesignal and prompt then\n                    pcall(function()\n                        firesignal(prompt.PromptButtonHoldBegan)\n                        task.wait(0.1)\n                        firesignal(prompt.PromptButtonHoldEnded)\n                        success = true\n                    end)\n                end\n                -- Method 2: use VirtualInputManager to press E\n                if not success then\n                    pcall(function()\n                        local vim = game:GetService(\"VirtualInputManager\")\n                        if vim then\n                            vim:SendKeyEvent(true, Enum.KeyCode.E, false, game)\n                            task.wait(0.1)\n                            vim:SendKeyEvent(false, Enum.KeyCode.E, false, game)\n                            success = true\n                        end\n                    end)\n                end\n                -- Method 3: use VirtualUser (last fallback)\n                if not success then\n                    pcall(function()\n                        if VirtualUser then\n                            VirtualUser:Button2Down(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n                            task.wait(0.1)\n                            VirtualUser:Button2Up(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n                            success = true\n                        end\n                    end)\n                end\n\n                if success then\n                    lastInteractTime = now\n                    NexusLib:Notify({ Title = \"Pray\", Message = \"Prayed to \" .. model.Name, Duration = 2 })\n                    break -- only interact with one spirit per pass\n                end\n                end\n                end\n                end\n            end\n        end\n\n        -- Start helper\n        local function startPray()\n            if prayEnabled then return end\n            prayEnabled = true\n            prayThread = task.spawn(function()\n                while prayEnabled do\n                    pcall(scanAndPray)\n                    task.wait(1.5) -- scan every 1.5 seconds\n                end\n            end)\n            NexusLib:Notify({ Title = \"Auto Pray\", Message = \"Enabled\", Duration = 2 })\n        end\n\n        local function stopPray()\n            prayEnabled = false\n            if prayThread then\n                task.cancel(prayThread)\n                prayThread = nil\n            end\n            for _, conn in ipairs(prayConnections) do\n                pcall(function() conn:Disconnect() end)\n            end\n            prayConnections = {}\n            NexusLib:Notify({ Title = \"Auto Pray\", Message = \"Disabled\", Duration = 2 })\n        end\n\n        -- Toggle\n        Cfg.register(PraySection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Teleport + Interact (Pray) Spirit\", {\n            Name = \"Auto Teleport + Interact (Pray) Spirit\",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    startPray()\n                else\n                    stopPray()\n                end\n            end\n        })), \"Toggle\", \"Auto Teleport + Interact (Pray) Spirit\", {\n            Name = \"Auto Teleport + Interact (Pray) Spirit\",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    startPray()\n                else\n                    stopPray()\n                end\n            end\n        })\n    end\n\nend\n\n-- ============================================================\n-- ===== SHOP TAB =====\n-- ============================================================\ndo\n    local ShopTab = Window:CreateTab(\"Shop\")\n\n    -- Index\n    do\n        local IndexSection = ShopTab:CreateSection(\"Index\")\n        IndexSection:CreateButton({\n            Name = \"Unlock all fish\",\n            Callback = function()\n                local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n                if not userData then\n                    NexusLib:Notify({ Title = \"Index\", Message = \"User data not found!\", Duration = 2 })\n                    return\n                end\n                local indexFolder = userData:FindFirstChild(\"Index\")\n                if not indexFolder then\n                    NexusLib:Notify({ Title = \"Index\", Message = \"Index folder not found!\", Duration = 2 })\n                    return\n                end\n                local count = 0\n                for _, child in ipairs(indexFolder:GetChildren()) do\n                    if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"NumberValue\") or child:IsA(\"IntValue\") then\n                        child.Value = 1\n                        count = count + 1\n                    elseif typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"BoolValue\") then\n                        child.Value = true\n                        count = count + 1\n                    end\n                end\n            end\n        })\n    end\n\n    -- Upgrade Skill\n    do\n        local UpgradeSkillSection = ShopTab:CreateSection(\"Upgrade Skill\")\n        local function GetOwnedSkills()\n            local userId = LocalPlayer and LocalPlayer.UserId\n            if not userId then return {} end\n            local userData = Data and Data:FindFirstChild(tostring(userId))\n            if not userData then return {} end\n            local skillFolder = userData:FindFirstChild(\"Skill\")\n            if not skillFolder then return {} end\n            local ownedSkills = {}\n            for _, child in pairs(skillFolder:GetChildren()) do\n                if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"Folder\") then\n                    local owned = child:FindFirstChild(\"Owned\")\n                    if typeof(owned) == \"Instance\" and owned:IsA(\"BoolValue\") and owned.Value == true then\n                        table.insert(ownedSkills, child.Name)\n                    end\n                end\n            end\n            return ownedSkills\n        end\n\n        local skillOptions = GetOwnedSkills()\n        if #skillOptions == 0 then skillOptions = {\"No skill owned\"} end\n        local selectedSkill = skillOptions[1] or \"No skill owned\"\n\n        local skillDropdown = Cfg.register(UpgradeSkillSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Choose A Skill That Needs To Upgrade\", {\n            Name = \"Choose A Skill That Needs To Upgrade\",\n            Options = skillOptions,\n            Default = selectedSkill,\n            Callback = function(value) selectedSkill = value end\n        })), \"Dropdown\", \"Choose A Skill That Needs To Upgrade\", {\n            Name = \"Choose A Skill That Needs To Upgrade\",\n            Options = skillOptions,\n            Default = selectedSkill,\n            Callback = function(value) selectedSkill = value end\n        })\n\n        local upgradeSkillMethodDropdown = Cfg.register(UpgradeSkillSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Upgrade Method\", {\n            Name = \"Upgrade Method\",\n            Options = {\"Instant\", \"Teleport\"},\n            Default = NexusState.upgradeSkill.method or \"Instant\",\n            Callback = function(value) NexusState.upgradeSkill.method = value end\n        })), \"Dropdown\", \"Upgrade Method\", {\n            Name = \"Upgrade Method\",\n            Options = {\"Instant\", \"Teleport\"},\n            Default = NexusState.upgradeSkill.method or \"Instant\",\n            Callback = function(value) NexusState.upgradeSkill.method = value end\n        })\n\n        UpgradeSkillSection:CreateButton({\n            Name = \"Upgrade Selected Skill\",\n            Callback = function()\n                if selectedSkill == \"No skill owned\" or not selectedSkill then\n                    NexusLib:Notify({ Title = \"Upgrade Skill\", Message = \"No skill selected!\", Duration = 2 })\n                    return\n                end\n                local userId = LocalPlayer and LocalPlayer.UserId\n                if not userId then\n                    NexusLib:Notify({ Title = \"Upgrade Skill\", Message = \"Player not ready!\", Duration = 2 })\n                    return\n                end\n                local userData = Data and Data:FindFirstChild(tostring(userId))\n                if not userData then\n                    NexusLib:Notify({ Title = \"Upgrade Skill\", Message = \"User data not found!\", Duration = 2 })\n                    return\n                end\n                local essenceOrb = userData:FindFirstChild(\"EssenceOrb\")\n                if not essenceOrb or not (typeof(essenceOrb) == \"Instance\" and essenceOrb:IsA(\"NumberValue\")) then\n                    NexusLib:Notify({ Title = \"Upgrade Skill\", Message = \"EssenceOrb not found!\", Duration = 2 })\n                    return\n                end\n                if essenceOrb.Value <= 0 then\n                    NexusLib:Notify({ Title = \"Upgrade Skill\", Message = \"Not enough EssenceOrb!\", Duration = 2 })\n                    return\n                end\n                if not Events or not Events.UpgradeSkill then\n                    NexusLib:Notify({ Title = \"Upgrade Skill\", Message = \"UpgradeSkill remote not found!\", Duration = 2 })\n                    return\n                end\n\n                NexusState.upgradeSkill.teleported = false\n                NexusState.upgradeSkill.oldPosition = nil\n                if NexusState.upgradeSkill.method == \"Teleport\" then\n                    local npc = Workspace:FindFirstChild(\"NPC\")\n                    if npc then\n                        local func = npc:FindFirstChild(\"Function\")\n                        if func then\n                            local zengTianguo = func:FindFirstChild(\"Zeng Tianguo\")\n                            if typeof(zengTianguo) == \"Instance\" and zengTianguo:IsA(\"Model\") then\n                                local hrp = zengTianguo:FindFirstChild(\"HumanoidRootPart\")\n                                if hrp then\n                                    local char = LocalPlayer.Character\n                                    if char then\n                                        local root = char:FindFirstChild(\"HumanoidRootPart\")\n                                        if root then\n                                            NexusState.upgradeSkill.oldPosition = root.Position\n                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                            NexusState.upgradeSkill.teleported = true\n                                            task.wait(0.3)\n                                        end\n                                    end\n                                end\n                            end\n                        end\n                    end\n                    if not NexusState.upgradeSkill.teleported then\n                        NexusLib:Notify({ Title = \"Upgrade Skill\", Message = \"Could not find Zeng Tianguo, teleport failed. Continuing anyway.\", Duration = 3 })\n                    end\n                end\n\n                local success, err = pcall(function()\n                    return Events.UpgradeSkill:InvokeServer(selectedSkill)\n                end)\n\n                if NexusState.upgradeSkill.teleported and NexusState.upgradeSkill.oldPosition then\n                    task.wait(0.2)\n                    local char = LocalPlayer.Character\n              