1000000},\n                {name = \"Mountain Fish\", minKg = 1000000, maxKg = 5000000},\n            }\n        }\n\n        local rodOptions = {\"Heavenpiercer Rod\", \"Pure Diamond Rod\", \"Sacred Bamboo Rod\"}\n        local selectedRod = rodOptions[1]\n\n        local rodDropdown = Cfg.register(CraftRodSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Select Rod to Craft\", {\n            Name = \"Select Rod to Craft\",\n            Options = rodOptions,\n            Default = selectedRod,\n            Callback = function(value) selectedRod = value end\n        })), \"Dropdown\", \"Select Rod to Craft\", {\n            Name = \"Select Rod to Craft\",\n            Options = rodOptions,\n            Default = selectedRod,\n            Callback = function(value) selectedRod = value end\n        })\n\n        Cfg.register(CraftRodSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Craft Method\", {\n            Name = \"Craft Method\",\n            Options = {\"Instant\", \"Teleport\"},\n            Default = \"Instant\",\n            Callback = function(value) NexusState.craftRodMethod = value end\n        })), \"Dropdown\", \"Craft Method\", {\n            Name = \"Craft Method\",\n            Options = {\"Instant\", \"Teleport\"},\n            Default = \"Instant\",\n            Callback = function(value) NexusState.craftRodMethod = value end\n        })\n\n        local function checkRodMaterials(rodName)\n            local recipe = ROD_RECIPES[rodName]\n            if not recipe then return false, \"Recipe not found for \" .. rodName end\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not userData then return false, \"Player data not found\" end\n            local inventory = userData:FindFirstChild(\"Inventory\")\n            if not inventory then return false, \"Inventory not found\" end\n            local fishCount = {}\n            for _, req in ipairs(recipe) do fishCount[req.name] = 0 end\n            for _, item in pairs(inventory:GetChildren()) do\n                local fishName, weight, count = parseCraftFishEntry(item)\n                if fishName and fishName ~= \"\" then\n                    local req = nil\n                    for _, r in ipairs(recipe) do\n                        if r.name == fishName then req = r; break end\n                    end\n                    if req then\n                        if weight and weight >= req.minKg and weight <= req.maxKg then\n                            fishCount[req.name] = fishCount[req.name] + count\n                        end\n                    end\n                end\n            end\n            local missing = {}\n            for _, req in ipairs(recipe) do\n                local count = fishCount[req.name] or 0\n                if count < 1 then\n                    table.insert(missing, req.name .. \" (need 1, have \" .. count .. \")\")\n                end\n            end\n            if #missing > 0 then\n                return false, \"Missing materials: \" .. table.concat(missing, \", \")\n            end\n            return true, \"All materials ready!\"\n        end\n\n        local function craftRod()\n            local ok, msg = checkRodMaterials(selectedRod)\n            if not ok then\n                NexusLib:Notify({ Title = \"Craft Rod\", Message = msg, Duration = 4 })\n                return\n            end\n            local method = NexusState.craftRodMethod or \"Instant\"\n            local teleported = false\n            if method == \"Teleport\" then\n                local npc = Workspace:FindFirstChild(\"NPC\")\n                if npc then\n                    local buyRod = npc:FindFirstChild(\"BuyFishingRod\")\n                    if buyRod then\n                        local biaoDi = buyRod:FindFirstChild(\"Biao Di\")\n                        if typeof(biaoDi) == \"Instance\" and biaoDi:IsA(\"Model\") then\n                            local hrp = biaoDi:FindFirstChild(\"HumanoidRootPart\")\n                            if hrp then\n                                local char = LocalPlayer.Character\n                                if char then\n                                    local root = char:FindFirstChild(\"HumanoidRootPart\")\n                                    if root then\n                                        NexusState.lastCraftPosition = root.Position\n                                        root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                        teleported = true\n                                        task.wait(0.3)\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n            end\n            local success, err = pcall(function()\n                Events.CraftRod:FireServer(selectedRod)\n            end)\n            if success then\n                NexusLib:Notify({ Title = \"Craft Rod\", Message = \"Crafted \" .. selectedRod .. \" successfully!\", Duration = 2 })\n            else\n                NexusLib:Notify({ Title = \"Craft Rod\", Message = \"Failed: \" .. tostring(err), Duration = 2 })\n            end\n            if teleported and NexusState.lastCraftPosition then\n                task.wait(0.3)\n                local char = LocalPlayer.Character\n                if char then\n                    local root = char:FindFirstChild(\"HumanoidRootPart\")\n                    if root then\n                        root.CFrame = CFrame.new(NexusState.lastCraftPosition)\n                        NexusState.lastCraftPosition = nil\n                    end\n                end\n            end\n        end\n\n        CraftRodSection:CreateButton({ Name = \"Craft rod now\", Callback = craftRod })\n        local autoCraftRodToggle = Cfg.register(CraftRodSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto craft selected rod\", {\n            Name = \"Auto craft selected rod\",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoCraftRodRunning = value\n                if value then\n                    if NexusState.autoCraftRodThread then\n                        task.cancel(NexusState.autoCraftRodThread)\n                        NexusState.autoCraftRodThread = nil\n                    end\n                    NexusState.autoCraftRodThread = task.spawn(function()\n                        while NexusState.autoCraftRodRunning do\n                            pcall(craftRod)\n                            task.wait(5)\n                        end\n                    end)\n                else\n                    if NexusState.autoCraftRodThread then\n                        task.cancel(NexusState.autoCraftRodThread)\n                        NexusState.autoCraftRodThread = nil\n                    end\n                end\n            end\n        })), \"Toggle\", \"Auto craft selected rod\", {\n            Name = \"Auto craft selected rod\",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoCraftRodRunning = value\n                if value then\n                    if NexusState.autoCraftRodThread then\n                        task.cancel(NexusState.autoCraftRodThread)\n                        NexusState.autoCraftRodThread = nil\n                    end\n                    NexusState.autoCraftRodThread = task.spawn(function()\n                        while NexusState.autoCraftRodRunning do\n                            pcall(craftRod)\n                            task.wait(5)\n                        end\n                    end)\n                else\n                    if NexusState.autoCraftRodThread then\n                        task.cancel(NexusState.autoCraftRodThread)\n                        NexusState.autoCraftRodThread = nil\n                    end\n                end\n            end\n        })\n    end