r.Character\n                                    if char then\n                                        local root = char:FindFirstChild(\"HumanoidRootPart\")\n                                        if root then\n                                            NexusState.buyRod.oldPosition = root.Position\n                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                            NexusState.buyRod.teleported = true\n                                            task.wait(0.3)\n                                        end\n                                    end\n                                end\n                            end\n                        end\n                    end\n                    if not NexusState.buyRod.teleported then\n                        NexusLib:Notify({ Title = \"Buy Rod\", Message = \"Could not find Biao Di, teleport failed. Continuing anyway.\", Duration = 3 })\n                    end\n                end\n                pcall(function()\n                    Events.BuyFishingRod:FireServer(selectedRod)\n                    NexusLib:Notify({ Title = \"Buy Rod\", Message = \"Bought \" .. selectedRod, Duration = 2 })\n                end)\n                if NexusState.buyRod.teleported and NexusState.buyRod.oldPosition then\n                    task.wait(0.2)\n                    local char = LocalPlayer.Character\n                    if char then\n                        local root = char:FindFirstChild(\"HumanoidRootPart\")\n                        if root then\n                            root.CFrame = CFrame.new(NexusState.buyRod.oldPosition)\n                            NexusState.buyRod.oldPosition = nil\n                            NexusState.buyRod.teleported = false\n                        end\n                    end\n                end\n            end\n        })\n    end\n\n    -- Learn Skills\n    do\n        local LearnSection = ShopTab:CreateSection(\"Learn Skills\")\n        local function GetLearnableSkills()\n            local p = Data and Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not p then return {\"No skill available\"} end\n            local skills = {}\n            for _, skillFolder in pairs(p.Skill:GetChildren()) do\n                if typeof(skillFolder) == \"Instance\" and typeof(skillFolder) == \"Instance\" and skillFolder:IsA(\"Folder\") then\n                    local owned = skillFolder:FindFirstChild(\"Owned\")\n                    if owned and owned.Value == false then\n                        local mod = Info and Info.Skill and Info.Skill:FindFirstChild(skillFolder.Name)\n                        if mod then\n                            local ok, m = pcall(require, mod)\n                            if ok and m and m.Price and m.Price > 0 then\n                                table.insert(skills, skillFolder.Name)\n                            end\n                        end\n                    end\n                end\n            end\n            if #skills == 0 then return {\"No skill available\"} end\n            return skills\n        end\n\n        local learnableSkills = GetLearnableSkills()\n        local selectedLearnSkills = {}\n\n        local learnDropdown = Cfg.register(LearnSection:CreateMultiDropdown(Cfg.wrap(\"MultiDropdown\", \"Select Skills to Learn\", {\n            Name = \"Select Skills to Learn\",\n            Options = learnableSkills,\n            Default = {},\n            Callback = function(values) selectedLearnSkills = values end\n        })), \"MultiDropdown\", \"Select Skills to Learn\", {\n            Name = \"Select Skills to Learn\",\n            Options = learnableSkills,\n            Default = {},\n            Callback = function(values) selectedLearnSkills = values end\n        })\n\n        local learnMethodDropdown = Cfg.register(LearnSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Learn Method\", {\n            Name = \"Learn Method\",\n            Options = {\"Instant\", \"Teleport\"},\n            Default = NexusState.learnSkill.method or \"Instant\",\n            Callback = function(value) NexusState.learnSkill.method = value end\n        })), \"Dropdown\", \"Learn Method\", {\n            Name = \"Learn Method\",\n            Options = {\"Instant\", \"Teleport\"},\n            Default = NexusState.learnSkill.method or \"Instant\",\n            Callback = function(value) NexusState.learnSkill.method = value end\n        })\n\n        LearnSection:CreateButton({\n            Name = \"Learn Selected Skills\",\n            Callback = function()\n                if #selectedLearnSkills == 0 then\n                    NexusLib:Notify({ Title = \"Learn Skills\", Message = \"No skills selected\", Duration = 2 })\n                    return\n                end\n                NexusState.learnSkill.teleported = false\n                NexusState.learnSkill.oldPosition = nil\n                if NexusState.learnSkill.method == \"Teleport\" then\n                    local npc = Workspace:FindFirstChild(\"NPC\")\n                    if npc then\n                        local learnSkill = npc:FindFirstChild(\"LearnSkill\")\n                        if learnSkill then\n                            local sageYijiu = learnSkill:FindFirstChild(\"Sage Yijiu\")\n                            if typeof(sageYijiu) == \"Instance\" and sageYijiu:IsA(\"Model\") then\n                                local hrp = sageYijiu:FindFirstChild(\"HumanoidRootPart\")\n                                if hrp then\n                                    local char = LocalPlayer.Character\n                                    if char then\n                                        local root = char:FindFirstChild(\"HumanoidRootPart\")\n                                        if root then\n                                            NexusState.learnSkill.oldPosition = root.Position\n                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                            NexusState.learnSkill.teleported = true\n                                            task.wait(0.3)\n                                        end\n                                    end\n                                end\n                            end\n                        end\n                    end\n                    if not NexusState.learnSkill.teleported then\n                        NexusLib:Notify({ Title = \"Learn Skills\", Message = \"Could not find Sage Yijiu, teleport failed. Continuing anyway.\", Duration = 3 })\n                    end\n                end\n                local learnedCount = 0\n                for _, skillName in ipairs(selectedLearnSkills) do\n                    local success, err = pcall(function()\n                        Events.BuySkill:FireServer(skillName)\n                    end)\n                    if success then\n                        learnedCount = learnedCount + 1\n                        NexusLib:Notify({ Title = \"Learn Skills\", Message = \"Learned \" .. skillName, Duration = 2 })\n                    else\n                        NexusLib:Notify({ Title = \"Learn Skills\", Message = \"Failed to learn \" .. skillName .. \": \" .. tostring(err), Duration = 2 })\n                    end\n                    task.wait(0.3)\n                end\n                if NexusState.learnSkill.teleported and NexusState.learnSkill.oldPosition then\n                    task.wait(0.2)\n                    local char = LocalPlayer.Character\n                    if char then\n                        local root = char:FindFirstChild(\"HumanoidRootPart\")\n                        if root then\n                            root.CFrame = CFrame.new(NexusState.learnSkill.oldPosition)\n                            NexusState.learnSkill.oldPosition = nil\n                            NexusState.learnSkill.teleported = false\n                        end\n                    end\n                end\n                NexusLib:Notify({ Title = \"Learn Skills\", Message = \"Learned \" .. learnedCount .. \" skill(s)!\", Duration = 3 })\n            end\n        })\n    end\n\n    -- Trait Reroll\n    do\n        local TraitSection = ShopTab:CreateSection(\"Trait Reroll\")\n        local function GetOwnedSkillNames()\n            local p = Data and Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not p then return {\"No skill owned\"} end\n            local skills = {}\n            for _, f in pairs(p.Skill:GetChildren()) do\n                if typeof(f) == \"Instance\" and typeof(f) == \"Instance\" and f:IsA(\"Folder\") and f.Owned and f.Owned.Value == true then\n                    table.insert(skills, f.Name)\n                end\n            end\n            if #skills == 0 then return {\"No skill owned\"} end\n            return skills\n        end\n\n        local function GetTraitNames()\n            local traits = {}\n            if not Info or not Info:FindFirstChild(\"Trait\") then return {\"No trait available\"} end\n            for _, child in pairs(Info.Trait:GetChildren()) do\n                if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"ModuleScript\") then\n                    local ok, mod = pcall(require, child)\n                    if ok and type(mod) == \"table\" and mod.Name then\n                        table.insert(traits, mod.Name)\n                    end\n                end\n            end\n            if #traits == 0 then return {\"No trait available\"} end\n            return traits\n        end\n\n        local ownedSkills = GetOwnedSkillNames()\n        local selectedSkillForReroll = ownedSkills[1] or \"No skill owned\"\n        local traitNames = GetTraitNames()\n        local selectedTargetTrait = traitNames[1] or \"No trait available\"\n        local ignoreLocked = false\n\n        local traitSkillDropdown = Cfg.register(TraitSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Select Skill\", {\n            Name = \"Select Skill\",\n            Options = ownedSkills,\n            Default = selectedSkillForReroll,\n            Callback = function(value) selectedSkillForReroll = value end\n        })), \"Dropdown\", \"Select Skill\", {\n            Name = \"Select Skill\",\n            Options = ownedSkills,\n            Default = selectedSkillForReroll,\n            Callback = function(value) selectedSkillForReroll = value end\n        })\n\n        local targetTraitDropdown = Cfg.register(TraitSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Target Trait\", {\n            Name = \"Target Trait\",\n            Options = traitNames,\n            Default = selectedTargetTrait,\n            Callback = function(value) selectedTargetTrait = value end\n        })), \"Dropdown\", \"Target Trait\", {\n            Name = \"Target Trait\",\n            Options = traitNames,\n            Default = selectedTargetTrait,\n            Callback = function(value) selectedTargetTrait = value end\n        })\n\n        local ignoreLockedToggle = Cfg.register(TraitSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Ignore Locked\", {\n            Name = \"Ignore Locked\",\n            Default = false,\n            Callback = function(value) ignoreLocked = value end\n        })), \"Toggle\", \"Ignore Locked\", {\n            Name = \"Ignore Locked\",\n            Default = false,\n            Callback = function(value) ignoreLocked = value end\n        })\n\n        local rerollMethodDropdown = Cfg.register(TraitSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Reroll Method\", {\n            Name = \"Reroll Method\",\n            Options = {\"Instant\", \"Teleport\"},\n            Default = NexusState.Reroll.method or \"Instant\",\n            Callback = function(value) NexusState.Reroll.method = value end\n        })), \"Dropdown\", \"Reroll Method\", {\n            Name = \"Reroll Method\",\n            Options = {\"Instant\", \"Teleport\"},\n            Default = NexusState.Reroll.method or \"Instant\",\n            Callback = function(value) NexusState.Reroll.method = value end\n        })\n\n        local RerollTrait = Events:FindFirstChild(\"RerollTrait\")\n\n        TraitSection:CreateButton({\n            Name = \"Reroll Until Trait\",\n            Callback = function()\n                if NexusState.Reroll.running then\n                    NexusState.Reroll.running = false\n                    if NexusState.Reroll.thread then\n                        task.cancel(NexusState.Reroll.thread)\n                        NexusState.Reroll.thread = nil\n                    end\n                    if NexusState.Reroll.teleported and NexusState.Reroll.oldPosition then\n                        local char = LocalPlayer.Character\n                        if char then\n                            local root = char:FindFirstChild(\"HumanoidRootPart\")\n                            if root then\n                                root.CFrame = CFrame.new(NexusState.Reroll.oldPosition)\n                                NexusState.Reroll.oldPosition = nil\n                                NexusState.Reroll.teleported = false\n                            end\n                        end\n                    end\n                    NexusLib:Notify({ Title = \"Reroll\", Message = \"Stopped\", Duration = 2 })\n                    return\n                end\n\n                local skillName = selectedSkillForReroll\n                local targetTrait = selectedTargetTrait\n                if not skillName or skillName == \"\" or skillName == \"No skill owned\" then\n                    NexusLib:Notify({ Title = \"Reroll\", Message = \"Select a valid skill\", Duration = 2 })\n                    return\n                end\n                if not targetTrait or targetTrait == \"\" or targetTrait == \"No trait available\" then\n                    NexusLib:Notify({ Title = \"Reroll\", Message = \"Select a target trait\", Duration = 2 })\n                    return\n                end\n                if not RerollTrait then\n                    NexusLib:Notify({ Title = \"Reroll\", Message = \"RerollTrait event not found\", Duration = 2 })\n                    return\n                end\n                local p = Data and Data:FindFirstChild(tostring(LocalPlayer.UserId))\n                local rerollCount = p and p:FindFirstChild(\"Trait Reroll\")\n                if rerollCount and rerollCount.Value <= 0 then\n                    NexusLib:Notify({ Title = \"Reroll\", Message = \"No rerolls left!\", Duration = 2 })\n                    return\n                end\n\n                NexusState.Reroll.teleported = false\n                NexusState.Reroll.oldPosition = nil\n                if NexusState.Reroll.method == \"Teleport\" then\n                    local npc = Workspace:FindFirstChild(\"NPC\")\n                    if npc then\n                        local func = npc:FindFirstChild(\"Function\")\n                        if func then\n                            local nanjiang = func:FindFirstChild(\"Nanjiang\")\n                            if typeof(nanjiang) == \"Instance\" and nanjiang:IsA(\"Model\") then\n                                local hrp = nanjiang:FindFirstChild(\"HumanoidRootPart\")\n                                if hrp then\n                                    local char = LocalPlayer.Character\n                                    if char then\n                                        local root = char:FindFirstChild(\"HumanoidRootPart\")\n                                        if root then\n                                            NexusState.Reroll.oldPosition = root.Position\n                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                            NexusState.Reroll.teleported = true\n                                            task.wait(0.3)\n                                        end\n                                    end\n                                end\n                            end\n                        end\n                    end\n                    if not NexusState.Reroll.teleported then\n                        NexusLib:Notify({ Title = \"Reroll\", Message = \"Could not find Nanjiang, teleport failed. Continuing anyway.\", Duration = 3 })\n                    end\n                end\n\n                NexusState.Reroll.running = true\n                NexusLib:Notify({ Title = \"Reroll\", Message = \"Reroll started... Target: \" .. targetTrait, Duration = 2 })\n\n                NexusState.Reroll.thread = task.spawn(function()\n                    local successCount = 0\n                    while NexusState.Reroll.running do\n                        local p2 = Data and Data:FindFirstChild(tostring(LocalPlayer.UserId))\n                        local count = p2 and p2:FindFirstChild(\"Trait Reroll\")\n                        if count and count.Value <= 0 then\n                            NexusLib:Notify({ Title = \"Reroll\", Message = \"No rerolls left, stopping\", Duration = 2 })\n                            break\n                        end\n                        local success, result = pcall(function()\n                            return RerollTrait:InvokeServer(skillName, ignoreLocked)\n                        end)\n                        if not success or not result then\n                            NexusLib:Notify({ Title = \"Reroll\", Message = \"Reroll failed, stopping\", Duration = 2 })\n                            break\n                        end\n                        successCount = successCount + 1\n                        local traitName = result.Name\n                        if traitName == targetTrait then\n                            NexusLib:Notify({ Title = \"Reroll\", Message = \"Got \" .. targetTrait .. \" on \" .. skillName .. \" after \" .. successCount .. \" rerolls!\", Duration = 3 })\n                            break\n                        end\n                        task.wait(0.15)\n                    end\n\n                    if NexusState.Reroll.teleported and NexusState.Reroll.oldPosition then\n                        local char = LocalPlayer.Character\n                        if char then\n                            local root = char:FindFirstChild(\"HumanoidRootPart\")\n                            if root then\n                                root.CFrame = CFrame.new(NexusState.Reroll.oldPosition)\n                                NexusState.Reroll.oldPosition = nil\n                                NexusState.Reroll.teleported = false\n                            end\n                        end\n                    end\n                    NexusState.Reroll.running = false\n                    NexusState.Reroll.thread = nil\n                    NexusLib:Notify({ Title = \"Reroll\", Message = \"Stopped\", Duration = 2 })\n                end)\n            end\n        })\n    end\n\n    -- Craft Bait\n    do\n        local CraftSection = ShopTab:CreateSection(\"Craft Bait\")\n        Cfg.register(CraftSection:CreateTextbox(Cfg.wrap(\"Textbox\", \"Number of baits to craft\", {\n            Name = \"Number of baits to craft\",\n            Placeholder = \"1\",\n            Default = \"1\",\n            Callback = function(value)\n                local num = tonumber(value)\n                if num and num >= 1 then\n                    NexusState.craftBaitQuantity = math.floor(num)\n                else\n                    NexusState.craftBaitQuantity = 1\n                end\n            end\n        })), \"Textbox\", \"Number of baits to craft\", {\n            Name = \"Number of baits to craft\",\n            Placeholder = \"1\",\n            Default = \"1\",\n            Callback = function(value)\n                local num = tonumber(value)\n                if num and num >= 1 then\n                    NexusState.craftBaitQuantity = math.floor(num)\n                else\n                    NexusState.craftBaitQuantity = 1\n                end\n            end\n        })\n\n        Cfg.register(CraftSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Choose a Bait\", {\n            Name = \"Choose a Bait\",\n            Options = {\"Rainbow Bait\", \"Frost Bait\", \"Nameless Bait\"},\n            Default = \"Rainbow Bait\",\n            Callback = function(value) NexusState.craftBaitName = value end\n        })), \"Dropdown\", \"Choose a Bait\", {\n            Name = \"Choose a Bait\",\n            Options = {\"Rainbow Bait\", \"Frost Bait\", \"Nameless Bait\"},\n            Default = \"Rainbow Bait\",\n            Callback = function(value) NexusState.craftBaitName = value end\n        })\n\n        Cfg.register(CraftSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Craft Method\", {\n            Name = \"Craft Method\",\n            Options = {\"Instant\", \"Teleport\"},\n            Default = \"Instant\",\n            Callback = function(value) NexusState.craftBaitMethod = value end\n        })), \"Dropdown\", \"Craft Method\", {\n            Name = \"Craft Method\",\n            Options = {\"Instant\", \"Teleport\"},\n            Default = \"Instant\",\n            Callback = function(value) NexusState.craftBaitMethod = value end\n        })\n\n        local BAIT_RECIPES = {\n            [\"Rainbow Bait\"] = {\n                {name = \"Colossal Tigerfish\", minKg = 3000000, maxKg = 6000000},\n                {name = \"Heavenpiercer Turtle\", minKg = 3000000, maxKg = 6000000},\n                {name = \"Golden Guardian Fish\", minKg = 1000000, maxKg = 3000000},\n                {name = \"Crimson Electric Eel\", minKg = 3000000, maxKg = 4000000},\n            },\n            [\"Frost Bait\"] = {\n                {name = \"Frost Kingfish\", minKg = 4000000, maxKg = 7000000},\n                {name = \"Ascended Perch\", minKg = 900000, maxKg = 1000000},\n                {name = \"Primordial Kunfish Overlord\", minKg = 1000000, maxKg = 1600000},\n                {name = \"Warbringer Shark\", minKg = 500000, maxKg = 800000},\n            },\n            [\"Nameless Bait\"] = {\n                {name = \"Mountain Fish\", minKg = 1000000, maxKg = 5000000},\n                {name = \"Tiger Mirefish\", minKg = 1000000, maxKg = 3000000},\n                {name = \"Mirage Lanternfish\", minKg = 3000000, maxKg = 5000000},\n                {name = \"Octoparasitic Fish\", minKg = 3000000, maxKg = 5000000},\n            }\n        }\n\n        local function checkMaterials(baitName, quantity)\n            local recipe = BAIT_RECIPES[baitName]\n            if not recipe then return false, \"No recipe found for \" .. baitName end\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not userData then return false, \"Player data not found\" end\n            local inventory = userData:FindFirstChild(\"Inventory\")\n            if not inventory then return false, \"Inventory not found\" end\n            local fishCount = {}\n            for _, req in ipairs(recipe) do fishCount[req.name] = 0 end\n            for _, item in pairs(inventory:GetChildren()) do\n                local fishName, weight, count = parseCraftFishEntry(item)\n                if fishName and fishName ~= \"\" then\n                    local req = nil\n                    for _, r in ipairs(recipe) do\n                        if r.name == fishName then req = r; break end\n                    end\n                    if req then\n                        if weight and weight >= req.minKg and weight <= req.maxKg then\n                            fishCount[req.name] = fishCount[req.name] + count\n                        end\n                    end\n                end\n            end\n            local missing = {}\n            for _, req in ipairs(recipe) do\n                local count = fishCount[req.name] or 0\n                if count < quantity then\n                    table.insert(missing, req.name .. \" (can \" .. quantity .. \", co \" .. count .. \")\")\n                end\n            end\n            if #missing > 0 then\n                return false, \"Missing materials: \" .. table.concat(missing, \", \")\n            end\n            return true, \"Materials are sufficient!\"\n        end\n\n        local function craftBait()\n            local qty = NexusState.craftBaitQuantity\n            local ok, msg = checkMaterials(NexusState.craftBaitName, qty)\n            if not ok then\n                NexusLib:Notify({ Title = \"Craft Bait\", Message = msg, Duration = 4 })\n                return\n            end\n            local method = NexusState.craftBaitMethod or \"Instant\"\n            local teleported = false\n            if method == \"Teleport\" then\n                local npc = Workspace:FindFirstChild(\"NPC\")\n                if npc then\n                    local buyBait = npc:FindFirstChild(\"BuyBait\")\n                    if buyBait then\n                        local children = buyBait:GetChildren()\n                        if #children >= 5 then\n                            local targetModel = children[5]\n                            if typeof(targetModel) == \"Instance\" and targetModel:IsA(\"Model\") then\n                                local hrp = targetModel:FindFirstChild(\"HumanoidRootPart\")\n                                if hrp then\n                                    local char = LocalPlayer.Character\n                                    if char then\n                                        local root = char:FindFirstChild(\"HumanoidRootPart\")\n                                        if root then\n                                            NexusState.lastCraftBaitPosition = root.Position\n                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                            teleported = true\n                                            task.wait(0.3)\n                                        end\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n            end\n            local success, err = pcall(function()\n                Events.CraftBait:FireServer(NexusState.craftBaitName, qty)\n            end)\n            if success then\n                NexusLib:Notify({ Title = \"Craft Bait\", Message = \"Crafted \" .. qty .. \"x \" .. NexusState.craftBaitName, Duration = 2 })\n            else\n                NexusLib:Notify({ Title = \"Craft Bait\", Message = \"Failed: \" .. tostring(err), Duration = 2 })\n            end\n            if teleported and NexusState.lastCraftBaitPosition then\n                task.wait(0.3)\n                local char = LocalPlayer.Character\n                if char then\n                    local root = char:FindFirstChild(\"HumanoidRootPart\")\n                    if root then\n                        root.CFrame = CFrame.new(NexusState.lastCraftBaitPosition)\n                        NexusState.lastCraftBaitPosition = nil\n                    end\n                end\n            end\n        end\n\n        local autoCraftToggle = Cfg.register(CraftSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto craft bait\", {\n            Name = \"Auto craft bait\",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoCraftRunning = value\n                if value then\n                    if NexusState.autoCraftThread then\n                        task.cancel(NexusState.autoCraftThread)\n                        NexusState.autoCraftThread = nil\n                    end\n                    NexusState.autoCraftThread = task.spawn(function()\n                        while NexusState.autoCraftRunning do\n                            pcall(craftBait)\n                            task.wait(5)\n                        end\n                    end)\n                else\n                    if NexusState.autoCraftThread then\n                        task.cancel(NexusState.autoCraftThread)\n                        NexusState.autoCraftThread = nil\n                    end\n                end\n            end\n        })), \"Toggle\", \"Auto craft bait\", {\n            Name = \"Auto craft bait\",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoCraftRunning = value\n                if value then\n                    if NexusState.autoCraftThread then\n                        task.cancel(NexusState.autoCraftThread)\n                        NexusState.autoCraftThread = nil\n                    end\n                    NexusState.autoCraftThread = task.spawn(function()\n                        while NexusState.autoCraftRunning do\n                            pcall(craftBait)\n                            task.wait(5)\n                        end\n                    end)\n                else\n                    if NexusState.autoCraftThread then\n                        task.cancel(NexusState.autoCraftThread)\n                        NexusState.autoCraftThread = nil\n                    end\n                end\n            end\n        })\n\n        CraftSection:CreateButton({ Name = \"Craft bait now\", Callback = craftBait })\n    end\n\n    -- Gacha\n    do\n        local gachaSection = ShopTab:CreateSection(\"Auto Gacha\")\n        local function GetTicketCount()\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not userData then return 0 end\n            local gachaData = userData:FindFirstChild(\"Gacha\")\n            if not gachaData then return 0 end\n            local tickets = gachaData:FindFirstChild(\"Tickets\")\n            if typeof(tickets) == \"Instance\" and tickets:IsA(\"NumberValue\") then\n                return tickets.Value\n            end\n            return 0\n        end\n\n        local function GetCrystals()\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not userData then return 0 end\n            local names = {\"Crystals\", \"Gems\", \"Diamonds\", \"Crystal\", \"Gem\"}\n            for _, name in ipairs(names) do\n                local val = userData:FindFirstChild(name)\n                if typeof(val) == \"Instance\" and val:IsA(\"NumberValue\") then\n                    return val.Value\n                end\n            end\n            local currency = userData:FindFirstChild(\"Currency\")\n            if currency then\n                for _, name in ipairs(names) do\n                    local val = currency:FindFirstChild(name)\n                    if typeof(val) == \"Instance\" and val:IsA(\"NumberValue\") then\n                        return val.Value\n                    end\n                end\n            end\n            return 0\n        end\n\n        local bannerOptions = {\"Egoless Banner\", \"Celestial Banner\"}\n        local selectedBanner = bannerOptions[1]\n        local amountOptions = {\"1\", \"10\"}\n        local selectedAmount = \"1\"\n\n        local bannerDropdown = Cfg.register(gachaSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Select Banner\", {\n            Name = \"Select Banner\",\n            Options = bannerOptions,\n            Default = selectedBanner,\n            Callback = function(value) selectedBanner = value end\n        })), \"Dropdown\", \"Select Banner\", {\n            Name = \"Select Banner\",\n            Options = bannerOptions,\n            Default = selectedBanner,\n            Callback = function(value) selectedBanner = value end\n        })\n        local amountDropdown = Cfg.register(gachaSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Tickets per roll\", {\n            Name = \"Tickets per roll\",\n            Options = amountOptions,\n            Default = selectedAmount,\n            Callback = function(value) selectedAmount = value end\n        })), \"Dropdown\", \"Tickets per roll\", {\n            Name = \"Tickets per roll\",\n            Options = amountOptions,\n            Default = selectedAmount,\n            Callback = function(value) selectedAmount = value end\n        })\n\n        local autoGachaToggle = Cfg.register(gachaSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Gacha\", {\n            Name = \"Auto Gacha\",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoGachaRunning = value\n                if value then\n                    if NexusState.autoGachaThread then\n                        task.cancel(NexusState.autoGachaThread)\n                        NexusState.autoGachaThread = nil\n                    end\n                    NexusState.autoGachaThread = task.spawn(function()\n                        while NexusState.autoGachaRunning do\n                            pcall(function()\n                                local ticketCount = GetTicketCount()\n                                local needed = tonumber(selectedAmount) or 1\n                                local crystalCount = GetCrystals()\n                                local canRoll = false\n                                if ticketCount >= needed then\n                                    canRoll = true\n                                else\n                                    local missing = needed - ticketCount\n                                    local crystalsNeeded = missing * 5\n                                    if crystalCount >= crystalsNeeded then\n                                        canRoll = true\n                                    else\n                                        NexusLib:Notify({\n                                            Title = \"Gacha\",\n                                            Message = \"Not enough tickets/crystals! Need \" .. crystalsNeeded .. \" crystals (have \" .. crystalCount .. \"). Stopping.\",\n                                            Duration = 4\n                                        })\n                                        NexusState.autoGachaRunning = false\n                                        return\n                                    end\n                                end\n                                if canRoll then\n                                    local isTen = (selectedAmount == \"10\")\n                                    Events.Gacha:FireServer(isTen, selectedBanner)\n                                    NexusLib:Notify({\n                                        Title = \"Gacha\",\n                                        Message = \"Rolled \" .. selectedAmount .. \" ticket(s) on \" .. selectedBanner,\n                                        Duration = 2\n                                    })\n                                end\n                            end)\n                            task.wait(2)\n                        end\n                    end)\n                else\n                    if NexusState.autoGachaThread then\n                        task.cancel(NexusState.autoGachaThread)\n                        NexusState.autoGachaThread = nil\n                    end\n                    NexusLib:Notify({ Title = \"Gacha\", Message = \"Stopped\", Duration = 2 })\n                end\n            end\n        })), \"Toggle\", \"Auto Gacha\", {\n            Name = \"Auto Gacha\",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoGachaRunning = value\n                if value then\n                    if NexusState.autoGachaThread then\n                        task.cancel(NexusState.autoGachaThread)\n                        NexusState.autoGachaThread = nil\n                    end\n                    NexusState.autoGachaThread = task.spawn(function()\n                        while NexusState.autoGachaRunning do\n                            pcall(function()\n                                local ticketCount = GetTicketCount()\n                                local needed = tonumber(selectedAmount) or 1\n                                local crystalCount = GetCrystals()\n                                local canRoll = false\n                                if ticketCount >= needed then\n                                    canRoll = true\n                                else\n                                    local missing = needed - ticketCount\n                                    local crystalsNeeded = missing * 5\n                                    if crystalCount >= crystalsNeeded then\n                                        canRoll = true\n                                    else\n                                        NexusLib:Notify({\n                                            Title = \"Gacha\",\n                                            Message = \"Not enough tickets/crystals! Need \" .. crystalsNeeded .. \" crystals (have \" .. crystalCount .. \"). Stopping.\",\n                                            Duration = 4\n                                        })\n                                        NexusState.autoGachaRunning = false\n                                        return\n                                    end\n                                end\n                                if canRoll then\n                                    local isTen = (selectedAmount == \"10\")\n                                    Events.Gacha:FireServer(isTen, selectedBanner)\n                                    NexusLib:Notify({\n                                        Title = \"Gacha\",\n                                        Message = \"Rolled \" .. selectedAmount .. \" ticket(s) on \" .. selectedBanner,\n                                        Duration = 2\n                                    })\n                                end\n                            end)\n                            task.wait(2)\n                        end\n                    end)\n                else\n                    if NexusState.autoGachaThread then\n                        task.cancel(NexusState.autoGachaThread)\n                        NexusState.autoGachaThread = nil\n                    end\n                    NexusLib:Notify({ Title = \"Gacha\", Message = \"Stopped\", Duration = 2 })\n                end\n            end\n        })\n    end\nend\n\n-- ============================================================\n-- ===== EXCHANGE TAB =====\n-- ============================================================\ndo\n    local ExchangeTab = Window:CreateTab(\"Exchange\")\n    local ExchangeSection = ExchangeTab:CreateSection(\"Exchange Items\")\n\n    local exchangeAmount = 1\n    local exchangeType = \"Trait Reroll\"\n\n    Cfg.register(ExchangeSection:CreateTextbox(Cfg.wrap(\"Textbox\", \"Quantity\", {\n        Name = \"Quantity\",\n        Placeholder = \"1\",\n        Default = \"1\",\n        Callback = function(value)\n            local num = tonumber(value)\n            if num and num >= 1 then\n                exchangeAmount = math.floor(num)\n            else\n                exchangeAmount = 1\n            end\n        end\n    })), \"Textbox\", \"Quantity\", {\n        Name = \"Quantity\",\n        Placeholder = \"1\",\n        Default = \"1\",\n        Callback = function(value)\n            local num = tonumber(value)\n            if num and num >= 1 then\n                exchangeAmount = math.floor(num)\n            else\n                exchangeAmount = 1\n            end\n        end\n    })\n\n    Cfg.register(ExchangeSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Choose an item\", {\n        Name = \"Choose an item\",\n        Options = {\"Trait Reroll\", \"EssenceOrb\"},\n        Default = \"Trait Reroll\",\n        Callback = function(value) exchangeType = value end\n    })), \"Dropdown\", \"Choose an item\", {\n        Name = \"Choose an item\",\n        Options = {\"Trait Reroll\", \"EssenceOrb\"},\n        Default = \"Trait Reroll\",\n        Callback = function(value) exchangeType = value end\n    })\n\n    local exchangeMethodDropdown = Cfg.register(ExchangeSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Exchange Method\", {\n        Name = \"Exchange Method\",\n        Options = {\"Instant\", \"Teleport\"},\n        Default = NexusState.exchange.method or \"Instant\",\n        Callback = function(value) NexusState.exchange.method = value end\n    })), \"Dropdown\", \"Exchange Method\", {\n        Name = \"Exchange Method\",\n        Options = {\"Instant\", \"Teleport\"},\n        Default = NexusState.exchange.method or \"Instant\",\n        Callback = function(value) NexusState.exchange.method = value end\n    })\n\n    ExchangeSection:CreateButton({\n        Name = \"Exchange now\",\n        Callback = function()\n            local userId = LocalPlayer.UserId\n            local userData = Data:FindFirstChild(tostring(userId))\n            if not userData then\n                NexusLib:Notify({ Title = \"Exchange\", Message = \"Player data not found!\", Duration = 2 })\n                return\n            end\n            local crystal = userData:FindFirstChild(\"Crystal\")\n            local cash = userData:FindFirstChild(\"Cash\")\n            if not crystal or not cash then\n                NexusLib:Notify({ Title = \"Exchange\", Message = \"Crystal or Cash not found!\", Duration = 2 })\n                return\n            end\n            local qty = exchangeAmount\n            local crystalNeed = qty * 5\n            local cashNeed = qty * 5000000\n            if crystal.Value < crystalNeed then\n                NexusLib:Notify({ Title = \"Exchange\", Message = \"Not enough Crystals! Need \" .. crystalNeed .. \", have \" .. crystal.Value, Duration = 3 })\n                return\n            end\n            if cash.Value < cashNeed then\n                NexusLib:Notify({ Title = \"Exchange\", Message = \"Not enough Cash! Need \" .. cashNeed .. \", have \" .. cash.Value, Duration = 3 })\n                return\n            end\n\n            NexusState.exchange.teleported = false\n            NexusState.exchange.oldPosition = nil\n            if NexusState.exchange.method == \"Teleport\" then\n                local npc = Workspace:FindFirstChild(\"NPC\")\n                if npc then\n                    local func = npc:FindFirstChild(\"Function\")\n                    if func then\n                        local nanjiang = func:FindFirstChild(\"Nanjiang\")\n                        if typeof(nanjiang) == \"Instance\" and nanjiang:IsA(\"Model\") then\n                            local hrp = nanjiang:FindFirstChild(\"HumanoidRootPart\")\n                            if hrp then\n                                local char = LocalPlayer.Character\n                                if char then\n                                    local root = char:FindFirstChild(\"HumanoidRootPart\")\n                                    if root then\n                                        NexusState.exchange.oldPosition = root.Position\n                                        root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                        NexusState.exchange.teleported = true\n                                        task.wait(0.3)\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n                if not NexusState.exchange.teleported then\n                    NexusLib:Notify({ Title = \"Exchange\", Message = \"Could not find Nanjiang, teleport failed. Continuing anyway.\", Duration = 3 })\n                end\n            end\n\n            local success, err = pcall(function()\n                Events.Exchange:FireServer(exchangeType, qty)\n            end)\n\n            if NexusState.exchange.teleported and NexusState.exchange.oldPosition then\n                task.wait(0.2)\n                local char = LocalPlayer.Character\n                if char then\n                    local root = char:FindFirstChild(\"HumanoidRootPart\")\n                    if root then\n                        root.CFrame = CFrame.new(NexusState.exchange.oldPosition)\n                        NexusState.exchange.oldPosition = nil\n                        NexusState.exchange.teleported = false\n                    end\n                end\n            end\n\n            if success then\n                NexusLib:Notify({ Title = \"Exchange\", Message = \"Exchanged \" .. qty .. \" \" .. exchangeType .. \"!\", Duration = 2 })\n            else\n                NexusLib:Notify({ Title = \"Exchange\", Message = \"Exchange failed: \" .. tostring(err), Duration = 2 })\n            end\n        end\n    })\nend\n\n-- ============================================================\n-- ===== QUESTS TAB =====\n-- ============================================================\ndo\n    local QuestsTab = Window:CreateTab(\"Quests\")\n\n    -- Teleport to Ticket Quest Giver, open dialogue, fire action, go back.\n    -- StartDialogue first: server ignores ChooseDialogueOption with no open dialogue.\n    NexusState.ticketLastFire = NexusState.ticketLastFire or 0\n    NexusState.ticketFailCount = NexusState.ticketFailCount or 0\n    local function ticketGoFire(action)\n        if _G and _G.Events then\n            local sd = _G.Events:FindFirstChild(\"StartDialogue\")\n            local cd = _G.Events:FindFirstChild(\"ChooseDialogueOption\")\n            if not sd or not cd then return false end\n        end\n        local giver = nil\n        pcall(function()\n            local npc = Workspace:FindFirstChild(\"NPC\")\n            local npcFunc = npc and npc:FindFirstChild(\"Function\")\n            giver = npcFunc and npcFunc:FindFirstChild(\"Ticket Quest Giver\")\n        end)\n        if not giver then return false end\n        local extraData = { giver }\n        local charNow = LocalPlayer.Character\n        local root = charNow and charNow:FindFirstChild(\"HumanoidRootPart\")\n        local giverPos = nil\n        pcall(function()\n            if typeof(giver) == \"Instance\" and typeof(giver) == \"Instance\" and giver:IsA(\"Model\") then\n                local hrp = giver:FindFirstChild(\"HumanoidRootPart\")\n                if hrp then\n                    giverPos = hrp.Position\n                elseif giver.PrimaryPart then\n                    giverPos = giver.PrimaryPart.Position\n                else\n                    giverPos = giver:GetPivot().Position\n                end\n            elseif typeof(giver) == \"Instance\" and typeof(giver) == \"Instance\" and giver:IsA(\"BasePart\") then\n                giverPos = giver.Position\n            end\n        end)\n        local origCF = root and root.CFrame\n        if root and giverPos then\n            pcall(function() root.CFrame = CFrame.new(giverPos + Vector3.new(0, 3, 0)) end)\n            task.wait(0.45)\n        end\n        pcall(function()\n            Events.StartDialogue:FireServer(\"Ticket Quest Giver\", giver)\n        end)\n        task.wait(0.25)\n        pcall(function()\n            Events.ChooseDialogueOption:FireServer(\"Ticket Quest Giver\", 1, action, extraData)\n        end)\n        task.wait(0.2)\n        if origCF and root and root.Parent then\n            pcall(function() root.CFrame = origCF end)\n        end\n        return true\n    end\n\n    -- ===== AUTO CLAIM TICKET QUEST =====\n    do\n        local ClaimSection = QuestsTab:CreateSection(\"Auto Claim Ticket Quest\")\n        local questTypes = {\"Easy Quest\", \"Hard Quest\"}\n        local selectedQuest = questTypes[1]\n\n        local function HasActiveQuest()\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not userData then return false end\n            local quest = userData:FindFirstChild(\"Quest\")\n            if not quest then return false end\n            local main = quest:FindFirstChild(\"Main\")\n            if not main then return false end\n            for _, child in pairs(main:GetChildren()) do\n                if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"Folder\") then\n                    local name = child.Name\n                    if name == \"Easy Ticket Quest\" or name == \"Hard Ticket Quest\" then\n                        return true\n                    end\n                end\n            end\n            return false\n        end\n\n        local claimDropdown = Cfg.register(ClaimSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Select Quest Type\", {\n            Name = \"Select Quest Type\",\n            Options = questTypes,\n            Default = selectedQuest,\n            Callback = function(value) selectedQuest = value end\n        })), \"Dropdown\", \"Select Quest Type\", {\n            Name = \"Select Quest Type\",\n            Options = questTypes,\n            Default = selectedQuest,\n            Callback = function(value) selectedQuest = value end\n        })\n\n        local autoClaimToggle = Cfg.register(ClaimSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Claim Ticket Quest (Fast)\", {\n            Name = \"Auto Claim Ticket Quest (Fast)\",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoClaimRunning = value\n                if value then\n                    if NexusState.autoClaimThread then\n                        task.cancel(NexusState.autoClaimThread)\n                        NexusState.autoClaimThread = nil\n                    end\n                    NexusState.autoClaimThread = task.spawn(function()\n                        while NexusState.autoClaimRunning do\n                            pcall(function()\n                                if not HasActiveQuest() then\n                                    if tick() - (NexusState.ticketLastFire or 0) < 3 then return end\n                                    NexusState.ticketLastFire = tick()\n                                    local selAction = nil\n                                    if selectedQuest == \"Easy Quest\" then\n                                        selAction = \"EasyAcceptQuest\"\n                                    else\n                                        selAction = \"HardAcceptQuest\"\n                                    end\n                                    if ticketGoFire(selAction) and HasActiveQuest() then\n                                        NexusState.ticketFailCount = 0\n                                        NexusLib:Notify({\n                                            Title = \"Quest\",\n                                            Message = \"Claimed \" .. selectedQuest,\n                                            Duration = 2\n                                        })\n                                    else\n                                        NexusState.ticketFailCount = (NexusState.ticketFailCount or 0) + 1\n                                        if NexusState.ticketFailCount == 5 then\n                                            NexusLib:Notify({ Title = \"Quest\", Message = \"Claim failed 5 times. Check NPC or quest type.\", Duration = 4 })\n                                        end\n                                    end\n                                else\n                                    NexusState.ticketFailCount = 0\n                                end\n                            end)\n                            task.wait(0.5)\n                        end\n                    end)\n                else\n                    if NexusState.autoClaimThread then\n                        task.cancel(NexusState.autoClaimThread)\n                        NexusState.autoClaimThread = nil\n                    end\n                    NexusState.ticketFailCount = 0\n                    NexusLib:Notify({ Title = \"Quest\", Message = \"Auto claim stopped\", Duration = 2 })\n                end\n            end\n        })), \"Toggle\", \"Auto Claim Ticket Quest (Fast)\", {\n            Name = \"Auto Claim Ticket Quest (Fast)\",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoClaimRunning = value\n                if value then\n                    if NexusState.autoClaimThread then\n                        task.cancel(NexusState.autoClaimThread)\n                        NexusState.autoClaimThread = nil\n                    end\n                    NexusState.autoClaimThread = task.spawn(function()\n                        while NexusState.autoClaimRunning do\n                            pcall(function()\n                                if not HasActiveQuest() then\n                                    if tick() - (NexusState.ticketLastFire or 0) < 3 then return end\n                                    NexusState.ticketLastFire = tick()\n                                    local selAction = nil\n                                    if selectedQuest == \"Easy Quest\" then\n                                        selAction = \"EasyAcceptQuest\"\n                                    else\n                                        selAction = \"HardAcceptQuest\"\n                                    end\n                                    if ticketGoFire(selAction) and HasActiveQuest() then\n                                        NexusState.ticketFailCount = 0\n                                        NexusLib:Notify({\n                                            Title = \"Quest\",\n                                            Message = \"Claimed \" .. selectedQuest,\n                                            Duration = 2\n                                        })\n                                    else\n                                        NexusState.ticketFailCount = (NexusState.ticketFailCount or 0) + 1\n                                        if NexusState.ticketFailCount == 5 then\n                                            NexusLib:Notify({ Title = \"Quest\", Message = \"Claim failed 5 times. Check NPC or quest type.\", Duration = 4 })\n                                        end\n                                    end\n                                else\n                                    NexusState.ticketFailCount = 0\n                                end\n                            end)\n                            task.wait(0.5)\n                        end\n                    end)\n                else\n                    if NexusState.autoClaimThread then\n                        task.cancel(NexusState.autoClaimThread)\n                        NexusState.autoClaimThread = nil\n                    end\n                    NexusState.ticketFailCount = 0\n                    NexusLib:Notify({ Title = \"Quest\", Message = \"Auto claim stopped\", Duration = 2 })\n                end\n            end\n        })\n    end\n\n    -- ===== AUTO DO TICKET QUEST =====\n    local DoSection = QuestsTab:CreateSection(\"Auto Do Ticket Quest\")\n    -- Store the dynamic controls\n    local islandModeDropdown = nil\n    local islandDropdown = nil\n    local islandDropdownFrame = nil\n    local selectedIslandMode = \"Auto Select Island\"\n    local selectedIslandName = \"Island 1\"\n    local islandList = {\"Island 1\", \"Island 2\", \"Island 3\", \"Island 4\", \"Island 5\",\n                        \"Island 6\", \"Island 7\", \"Island 8\", \"Island 9\", \"Island 10\", \"Island 11\", \"Island 12\", \"Island 13\"}\n\n    -- Remove the island dropdown (if present)\n    local function clearIslandDropdown()\n        if islandDropdownFrame and islandDropdownFrame._frame then\n            pcall(function()\n                if type(islandDropdownFrame.Destroy) == \"function\" then\n                    islandDropdownFrame:Destroy()\n                elseif islandDropdownFrame._frame and type(islandDropdownFrame._frame.Destroy) == \"function\" then\n                    islandDropdownFrame._frame:Destroy()\n                end\n            end)\n        end\n        islandDropdownFrame = nil\n        islandDropdown = nil\n    end\n\n    -- Create the island dropdown\n    -- NOTE: picking an island forces manual mode, so Auto Do Ticket\n    -- never pulls the player back to the recommended island.\n    local function createIslandDropdown()\n        clearIslandDropdown()\n        islandDropdown = Cfg.register(DoSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Choose an island\", {\n            Name = \"Choose an island\",\n            Options = islandList,\n            Default = selectedIslandName,\n            Callback = function(value)\n                selectedIslandName = value\n                selectedIslandMode = \"Choose Island Manual\"\n                pcall(function() if modeDropdown and modeDropdown.Set then modeDropdown:Set(\"Choose Island Manual\") end end)\n            end\n        })), \"Dropdown\", \"Choose an island\", {\n            Name = \"Choose an island\",\n            Options = islandList,\n            Default = selectedIslandName,\n            Callback = function(value)\n                selectedIslandName = value\n                selectedIslandMode = \"Choose Island Manual\"\n                pcall(function() if modeDropdown and modeDropdown.Set then modeDropdown:Set(\"Choose Island Manual\") end end)\n            end\n        })\n        islandDropdownFrame = islandDropdown\n    end\n\n    -- Create the mode dropdown\n    local modeDropdown = Cfg.register(DoSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Island Selection Mode\", {\n        Name = \"Island Selection Mode\",\n        Options = {\"Auto Select Island\", \"Choose Island Manual\"},\n        Default = \"Auto Select Island\",\n        Callback = function(value)\n            selectedIslandMode = value\n            if value == \"Choose Island Manual\" then\n                createIslandDropdown()\n            else\n                clearIslandDropdown()\n            end\n        end\n    })), \"Dropdown\", \"Island Selection Mode\", {\n        Name = \"Island Selection Mode\",\n        Options = {\"Auto Select Island\", \"Choose Island Manual\"},\n        Default = \"Auto Select Island\",\n        Callback = function(value)\n            selectedIslandMode = value\n            if value == \"Choose Island Manual\" then\n                createIslandDropdown()\n            else\n                clearIslandDropdown()\n            end\n        end\n    })\n\n    -- Create the default island dropdown (hidden, shown only in manual mode)\n    -- Not built up front, only once manual is picked\n\n    -- ===== Target island resolver =====\n    local function getTargetIsland()\n        if selectedIslandMode == \"Auto Select Island\" then\n            return getRecommendedIsland()\n        else\n            for _, island in ipairs(NexusState.islands) do\n                if island.name == selectedIslandName then\n                    return island\n                end\n            end\n            return nil\n        end\n    end\n\n\n    local function parseQuestString(str)\n        if not str or str == \"\" then return nil, nil end\n        local parts = {}\n        for part in string.gmatch(str, \"[^,]+\") do table.insert(parts, part) end\n        if #parts >= 3 then\n            local target = nil\n            local typ = nil\n            if string.find(parts[1], \"Boss\") then\n                target = tonumber(parts[3])\n                typ = parts[1]\n            else\n                target = tonumber(parts[2])\n                typ = parts[3]\n            end\n            if target and typ then return target, typ end\n        end\n        return nil, nil\n    end\n\n    local function getCurrentQuestProgress()\n        local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n        if not userData then return nil end\n        local quest = userData:FindFirstChild(\"Quest\")\n        if not quest then return nil end\n        local main = quest:FindFirstChild(\"Main\")\n        if not main then return nil end\n        for _, folder in pairs(main:GetChildren()) do\n            if typeof(folder) == \"Instance\" and typeof(folder) == \"Instance\" and folder:IsA(\"Folder\") and (folder.Name == \"Easy Ticket Quest\" or folder.Name == \"Hard Ticket Quest\") then\n                local current = nil\n                local target = nil\n                local typ = nil\n                local questName = folder.Name\n                for _, child in pairs(folder:GetChildren()) do\n                    if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"NumberValue\") or child:IsA(\"IntValue\") then\n                        if child.Name == \"1\" then\n                            current = child.Value\n                        end\n                    end\n                end\n                local objective = folder:FindFirstChild(\"Objective\")\n                if objective then\n                    for _, child in pairs(objective:GetChildren()) do\n                        if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"StringValue\") and child.Name == \"1\" then\n                            local val = child.Value\n                            if val and val ~= \"\" then\n                                NexusState.ticketObjectiveText = tostring(val)\n                                local t, ty = parseQuestString(val)\n                                if t and ty then\n                                    target = t\n                                    typ = ty\n                                end\n                            end\n                        end\n                    end\n                end\n                if current and target and typ then\n                    return current, target, questName, typ\n                end\n            end\n        end\n        return nil\n    end\n\n    local function updateQuestStatus()\n        local current, target, questName, typ = getCurrentQuestProgress()\n        if current and target and questName then\n            NexusState.ticketTargetCount = target\n            NexusState.ticketCurrentCount = current\n            NexusState.ticketQuestActive = true\n            if current >= target then\n                if not NexusState.ticketQuestClaimed then\n                    NexusLib:Notify({ Title = \"Quest\", Message = \"Complete! Claiming reward...\", Duration = 2 })\n                    -- TP to NPC, turn in with retries, chain next quest right away.\n                    local turnedIn = false\n                    for _ = 1, 5 do\n                        if ticketGoFire(\"Quest\") then\n                            for _ = 1, 6 do\n                                task.wait(0.15)\n                                if not getCurrentQuestProgress() then\n                                    turnedIn = true\n                                    break\n                                end\n                            end\n                        end\n                        if turnedIn then break end\n                        task.wait(0.2)\n                    end\n                    if turnedIn then\n                        NexusState.ticketQuestClaimed = true\n                        NexusState.ticketLastFire = 0\n                        NexusState.ticketFailCount = 0\n                        NexusState.isDoingUseBaitQuest = false\n                        disableAllFishing()\n                        NexusState.ticketQuestActive = false\n                        NexusLib:Notify({ Title = \"Quest\", Message = \"Turned in. Claim toggle takes next quest.\", Duration = 3 })\n                    else\n                        NexusLib:Notify({ Title = \"Quest\", Message = \"Turn-in failed, retrying...\", Duration = 2 })\n                    end\n                end\n                NexusState.isDoingUseBaitQuest = false\n                Fishing.Flags.AutoSkill = false\n                Fishing.Flags.AutoSkillCheck = false\n                NexusState.ticketQuestActive = false\n                return\n            end\n            NexusState.ticketQuestClaimed = false\n\n            -- Teleport to target island (manual choice wins)\n            local targetIsland = getTargetIsland()\n            if targetIsland then\n                local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n                if hrp then\n                    local targetPos = targetIsland.cframe.Position + Vector3.new(0, 5, 0)\n                    if (hrp.Position - targetPos).Magnitude > 25 and (tick() - (NexusState.ticketLastTele or 0) > 3) then\n                        NexusState.ticketLastTele = tick()\n                        safeTeleport(hrp, CFrame.new(targetPos))\n                    end\n                end\n            end\n\n                        local need = string.lower(tostring(typ or \"\") .. \" \" .. tostring(NexusState.ticketObjectiveText or \"\"))\n            local function needHas(...)\n                for _, k in ipairs({...}) do\n                    if string.find(need, k, 1, true) then return true end\n                end\n                return false\n            end\n            NexusState.isDoingUseBaitQuest = false\n            -- Ticket pool: use bait / catch fish / heavy fish (1.5M) / use skill.\n            -- No boss quests here, so boss words inside fish names must not trigger boss farm.\n            if needHas(\"usebait\", \"use bait\", \"bait\") then\n                NexusState.isDoingUseBaitQuest = true\n                enableBasicFishing()\n                Fishing.Flags.AutoFarmBoss = false\n                Fishing.Flags.AutoFarmSecretBoss = false\n                Fishing.Flags.AnchorLock = true\n                Fishing.Flags.AutoSkill = true\n                Fishing.Flags.AutoSkillCheck = true\n                MiscFlags.AutoBuy = true\n                local buyable = GetBuyableBaits()\n                local found = false\n                for _, name in ipairs(buyable) do\n                    if name == \"Basic Bait\" then\n                        NexusState.selectedBait = name\n                        found = true\n                        break\n                    end\n                end\n                if not found then\n                    NexusState.selectedBait = buyable[1] or \"No bait available\"\n                end\n                MiscFlags.AutoEquipBait = true\n            elseif needHas(\"skill\") then\n                enableBasicFishing()\n                Fishing.Flags.AutoFarmBoss = false\n                Fishing.Flags.AutoFarmSecretBoss = false\n                Fishing.Flags.AutoSkill = true\n                Fishing.Flags.AutoSkillCheck = true\n                Fishing.Flags.AnchorLock = true\n            elseif needHas(\"weight\", \"kg\", \"heavy\", \"1.5m\", \"1,5m\", \"1500000\") then\n                enableBasicFishing()\n                Fishing.Flags.AutoFarmBoss = false\n                Fishing.Flags.AutoFarmSecretBoss = false\n                pcall(function() Events.UpdateFishProgression:FireServer() end)\n            elseif needHas(\"fish\", \"catch\", \"fishing\") then\n                enableBasicFishing()\n                Fishing.Flags.AutoFarmBoss = false\n                Fishing.Flags.AutoFarmSecretBoss = false\n                pcall(function() Events.UpdateFishProgression:FireServer() end)\n            else\n                enableBasicFishing()\n                Fishing.Flags.AutoFarmBoss = false\n                Fishing.Flags.AutoFarmSecretBoss = false\n            end\n        else\n            if NexusState.ticketQuestActive then\n                NexusState.ticketQuestActive = false\n                NexusState.ticketTargetCount = 0\n                NexusState.ticketCurrentCount = 0\n                NexusState.isDoingUseBaitQuest = false\n                Fishing.Flags.AutoSkill = false\n                Fishing.Flags.AutoSkillCheck = false\n                disableAllFishing()\n            end\n            NexusState.isDoingUseBaitQuest = false\n            NexusState.ticketQuestClaimed = false\n            NexusState.ticketLastFire = 0\n            NexusState.ticketFailCount = 0\n            NexusState.ticketObjectiveText = nil\n        end\n    end\n\n    local function startAutoDoLoop()\n        if NexusState.autoDoThread then return end\n        NexusState.autoDoThread = task.spawn(function()\n            while NexusState.autoDoRunning do\n                pcall(updateQuestStatus)\n                task.wait(1)\n            end\n            NexusState.autoDoThread = nil\n        end)\n    end\n\n    local autoDoToggle = Cfg.register(DoSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Do Ticket Quest (Fast)\", {\n        Name = \"Auto Do Ticket Quest (Fast)\",\n        Default = false,\n        Callback = function(value)\n            NexusState.autoDoRunning = value\n            if value then\n                if NexusState.autoDoThread then\n                    task.cancel(NexusState.autoDoThread)\n                    NexusState.autoDoThread = nil\n                end\n                startAutoDoLoop()\n                NexusLib:Notify({ Title = \"Auto Do Quest\", Message = \"Started monitoring quest objective\", Duration = 2 })\n            else\n                if NexusState.autoDoThread then\n                    task.cancel(NexusState.autoDoThread)\n                    NexusState.autoDoThread = nil\n                end\n                NexusState.autoRecommendRunning = false\n                if NexusState.autoRecommendThread then\n                    task.cancel(NexusState.autoRecommendThread)\n                    NexusState.autoRecommendThread = nil\n                end\n                disableAllFishing()\n                NexusLib:Notify({ Title = \"Auto Do Quest\", Message = \"Stopped\", Duration = 2 })\n            end\n        end\n    })), \"Toggle\", \"Auto Do Ticket Quest (Fast)\", {\n        Name = \"Auto Do Ticket Quest (Fast)\",\n        Default = false,\n        Callback = function(value)\n            NexusState.autoDoRunning = value\n            if value then\n                if NexusState.autoDoThread then\n                    task.cancel(NexusState.autoDoThread)\n                    NexusState.autoDoThread = nil\n                end\n                startAutoDoLoop()\n                NexusLib:Notify({ Title = \"Auto Do Quest\", Message = \"Started fast quest monitoring\", Duration = 2 })\n            else\n                if NexusState.autoDoThread then\n                    task.cancel(NexusState.autoDoThread)\n                    NexusState.autoDoThread = nil\n                end\n                disableAllFishing()\n                NexusState.isDoingUseBaitQuest = false\n                NexusLib:Notify({ Title = \"Auto Do Quest\", Message = \"Stopped\", Duration = 2 })\n            end\n        end\n    })\n\n    -- ===== DAILY QUESTS =====\n    do\n        local DailySection = QuestsTab:CreateSection(\"Daily Quests\")\n        local dailyRunning = false\n        local dailyThread = nil\n\n        local function teleportToIsland(island)\n            if not island then return false end\n            local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n            if not hrp then return false end\n            local target = island.cframe.Position + Vector3.new(0, 5, 0)\n            hrp.AssemblyLinearVelocity = Vector3.zero\n            hrp.AssemblyAngularVelocity = Vector3.zero\n            hrp.CFrame = CFrame.new(target)\n            return true\n        end\n\n        local function doDailyQuest()\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not userData then\n                NexusLib:Notify({ Title = \"Daily Quest\", Message = \"User data not found!\", Duration = 2 })\n                return\n            end\n            local dailyFolder = userData:FindFirstChild(\"Quest\") and userData.Quest:FindFirstChild(\"Daily\")\n            if not dailyFolder then\n                NexusLib:Notify({ Title = \"Daily Quest\", Message = \"Daily quest folder not found!\", Duration = 2 })\n                return\n            end\n            local questFolders = {}\n            for _, child in pairs(dailyFolder:GetChildren()) do\n                if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"Folder\") then\n                    table.insert(questFolders, child)\n                end\n            end\n            if #questFolders == 0 then\n                NexusLib:Notify({ Title = \"Daily Quest\", Message = \"No daily quests available!\", Duration = 2 })\n                return\n            end\n            local selectedFolder = questFolders[math.random(1, #questFolders)]\n            local questId = selectedFolder.Name\n            local progression = selectedFolder:FindFirstChild(\"Progression\")\n            local questType = selectedFolder:FindFirstChild(\"QuestType\")\n            if not progression or not questType then\n                NexusLib:Notify({ Title = \"Daily Quest\", Message = \"Missing Progression or QuestType in quest \" .. questId, Duration = 2 })\n                return\n            end\n            local currentProgress = (typeof(progression) == \"Instance\" and progression:IsA(\"NumberValue\")) and progression.Value or 0\n            local qType = (typeof(questType) == \"Instance\" and questType:IsA(\"StringValue\")) and questType.Value or \"\"\n\n            NexusLib:Notify({\n                Title = \"Daily Quest\",\n                Message = \"Selected quest \" .. questId .. \" | Type: \" .. qType .. \" | Progress: \" .. currentProgress,\n                Duration = 4\n            })\n\n            if qType == \"PlayTime\" then\n                NexusLib:Notify({ Title = \"Daily Quest\", Message = \"PlayTime quest: just play for 30 minutes!\", Duration = 3 })\n                return\n            end\n\n            if qType == \"Fishing\" then\n                local island = getRecommendedIsland()\n                if not island then\n                    NexusLib:Notify({ Title = \"Daily Quest\", Message = \"No suitable island found!\", Duration = 2 })\n                    return\n                end\n                if not teleportToIsland(island) then\n                    NexusLib:Notify({ Title = \"Daily Quest\", Message = \"Teleport failed!\", Duration = 2 })\n                    return\n                end\n                enableBasicFishing()\n                Fishing.Flags.AutoFarmBoss = false\n                Fishing.Flags.AutoFarmSecretBoss = false\n                NexusLib:Notify({ Title = \"Daily Quest\", Message = \"Fishing daily started on \" .. island.name, Duration = 2 })\n                while dailyRunning do\n                    local newProgress = selectedFolder:FindFirstChild(\"Progression\")\n                    if typeof(newProgress) == \"Instance\" and newProgress:IsA(\"NumberValue\") then\n                        if newProgress.Value >= 100 then\n                            NexusLib:Notify({ Title = \"Daily Quest\", Message = \"Fishing daily completed!\", Duration = 3 })\n                            break\n                        end\n                    end\n                    task.wait(2)\n                end\n            elseif qType == \"BossQuest\" then\n                local island = getRecommendedIsland()\n                if not island then\n                    NexusLib:Notify({ Title = \"Daily Quest\", Message = \"No suitable island found!\", Duration = 2 })\n                    return\n                end\n                if not teleportToIsland(island) then\n                    NexusLib:Notify({ Title = \"Daily Quest\", Message = \"Teleport failed!\", Duration = 2 })\n                    return\n                end\n                enableBasicFishing()\n                Fishing.Flags.AutoFarmBoss = true\n                Fishing.Flags.AutoFarmSecretBoss = false\n                NexusLib:Notify({ Title = \"Daily Quest\", Message = \"Boss daily started on \" .. island.name, Duration = 2 })\n                while dailyRunning do\n                    local newProgress = selectedFolder:FindFirstChild(\"Progression\")\n                    if typeof(newProgress) == \"Instance\" and newProgress:IsA(\"NumberValue\") then\n                        if newProgress.Value >= 10 then\n                            NexusLib:Notify({ Title = \"Daily Quest\", Message = \"Boss daily completed!\", Duration = 3 })\n                            break\n                        end\n                    end\n                    task.wait(2)\n                end\n            elseif qType == \"Bait\" then\n                NexusLib:Notify({ Title = \"Daily Quest\", Message = \"Bait daily: buying Basic Bait...\", Duration = 2 })\n                local buyEvent = Events:FindFirstChild(\"BuyBait\")\n                if not buyEvent then\n                    NexusLib:Notify({ Title = \"Daily Quest\", Message = \"BuyBait remote not found!\", Duration = 2 })\n                    return\n                end\n                while dailyRunning do\n                    local newProgress = selectedFolder:FindFirstChild(\"Progression\")\n                    if typeof(newProgress) == \"Instance\" and newProgress:IsA(\"NumberValue\") then\n                        if newProgress.Value >= 25 then\n                            NexusLib:Notify({ Title = \"Daily Quest\", Message = \"Bait daily completed!\", Duration = 3 })\n                            break\n                        end\n                    end\n                    pcall(function() buyEvent:FireServer(\"Basic Bait\", 1) end)\n                    task.wait(0.5)\n                end\n            else\n                NexusLib:Notify({ Title = \"Daily Quest\", Message = \"Unknown quest type: \" .. qType, Duration = 2 })\n            end\n            restoreRoutineFlags()\n        end\n\n        -- Toggle Auto Do Daily Quest\n        local autoDailyToggle = Cfg.register(DailySection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Do Daily Quest\", {\n            Name = \"Auto Do Daily Quest\",\n            Default = false,\n            Callback = function(value)\n                dailyRunning = value\n                if value then\n                    if dailyThread then\n                        task.cancel(dailyThread)\n                        dailyThread = nil\n                    end\n                    dailyThread = task.spawn(function()\n                        while dailyRunning do\n                            pcall(doDailyQuest)\n                            if dailyRunning then\n                                task.wait(5)\n                            end\n                        end\n                    end)\n                    NexusLib:Notify({ Title = \"Daily Quest\", Message = \"Auto Daily started!\", Duration = 2 })\n                else\n                    if dailyThread then\n                        task.cancel(dailyThread)\n                        dailyThread = nil\n                    end\n                    restoreRoutineFlags()\n                    NexusLib:Notify({ Title = \"Daily Quest\", Message = \"Auto Daily stopped\", Duration = 2 })\n                end\n            end\n        })), \"Toggle\", \"Auto Do Daily Quest\", {\n            Name = \"Auto Do Daily Quest\",\n            Default = false,\n            Callback = function(value)\n                dailyRunning = value\n                if value then\n                    if dailyThread then\n                        task.cancel(dailyThread)\n                        dailyThread = nil\n                    end\n                    dailyThread = task.spawn(function()\n                        while dailyRunning do\n                            pcall(doDailyQuest)\n                            if dailyRunning then\n                                task.wait(5)\n                            end\n                        end\n                    end)\n                    NexusLib:Notify({ Title = \"Daily Quest\", Message = \"Auto Daily started!\", Duration = 2 })\n                else\n                    if dailyThread then\n                        task.cancel(dailyThread)\n                        dailyThread = nil\n                    end\n                    restoreRoutineFlags()\n                    NexusLib:Notify({ Title = \"Daily Quest\", Message = \"Auto Daily stopped\", Duration = 2 })\n                end\n            end\n        })\n\n        -- ===== CLAIM DAILY REWARDS BUTTON =====\n        DailySection:CreateButton({\n            Name = \"Claim Daily Rewards\",\n            Callback = function()\n                local dailyRewardEvent = Events:FindFirstChild(\"DailyReward\")\n                if not dailyRewardEvent then\n                    NexusLib:Notify({ Title = \"Daily Rewards\", Message = \"DailyReward remote not found!\", Duration = 3 })\n                    return\n                end\n                NexusLib:Notify({ Title = \"Daily Rewards\", Message = \"Claiming all 7 daily rewards...\", Duration = 2 })\n                task.spawn(function()\n                    for i = 1, 7 do\n                        pcall(function()\n                            dailyRewardEvent:FireServer(i)\n                        end)\n                        task.wait(0.5)\n                    end\n                    NexusLib:Notify({ Title = \"Daily Rewards\", Message = \"All 7 daily rewards claimed!\", Duration = 3 })\n                end)\n            end\n        })\n    end\n\nend\n\n-- ============================================================\n-- ===== UPGRADE TAB =====\n-- ============================================================\ndo\n    local UpgradeTab = Window:CreateTab(\"Upgrade\")\n    local UpgradeSection = UpgradeTab:CreateSection(\"Character Upgrade\")\n\n    local optionsList = {\"Cash\", \"Level\", \"Crystal\", \"Ticket\"}\n    NexusState.UpgradeCharacter = Events:WaitForChild(\"UpgradeCharacter\")\n\n    local multiDropdown = Cfg.register(UpgradeSection:CreateMultiDropdown(Cfg.wrap(\"MultiDropdown\", \"Select 2 upgrade options\", {\n        Name = \"Select 2 upgrade options\",\n        Options = optionsList,\n        Default = NexusState.selectedOptions or {\"Cash\", \"Level\"},\n        Callback = function(values)\n            if #values > 2 then\n                NexusLib:Notify({ Title = \"Upgrade\", Message = \"You can only select 2 options!\", Duration = 2 })\n                local newValues = {}\n                for i = #values - 1, #values do table.insert(newValues, values[i]) end\n                NexusState.selectedOptions = newValues\n            else\n                NexusState.selectedOptions = values\n            end\n        end\n    })), \"MultiDropdown\", \"Select 2 upgrade options\", {\n        Name = \"Select 2 upgrade options\",\n        Options = optionsList,\n        Default = NexusState.selectedOptions or {\"Cash\", \"Level\"},\n        Callback = function(values)\n            if #values > 2 then\n                NexusLib:Notify({ Title = \"Upgrade\", Message = \"You can only select 2 options!\", Duration = 2 })\n                local newValues = {}\n                for i = #values - 1, #values do table.insert(newValues, values[i]) end\n                NexusState.selectedOptions = newValues\n            else\n                NexusState.selectedOptions = values\n            end\n        end\n    })\n\n    local upgradeCharMethodDropdown = Cfg.register(UpgradeSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Upgrade Method\", {\n        Name = \"Upgrade Method\",\n        Options = {\"Instant\", \"Teleport\"},\n        Default = NexusState.upgradeCharacter.method or \"Instant\",\n        Callback = function(value) NexusState.upgradeCharacter.method = value end\n    })), \"Dropdown\", \"Upgrade Method\", {\n        Name = \"Upgrade Method\",\n        Options = {\"Instant\", \"Teleport\"},\n        Default = NexusState.upgradeCharacter.method or \"Instant\",\n        Callback = function(value) NexusState.upgradeCharacter.method = value end\n    })\n\n    local function checkResources(option1, option2)\n        local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n        if not userData then return false, \"Player data not found\" end\n        local resources = {\n            Cash = { path = userData:FindFirstChild(\"Cash\"), needed = 5000000000 },\n            Level = { path = userData:FindFirstChild(\"Level\") and userData.Level:FindFirstChild(\"Level\"), needed = 500 },\n            Crystal = { path = userData:FindFirstChild(\"Crystal\"), needed = 1000 },\n            Ticket = { path = userData:FindFirstChild(\"Ticket\"), needed = 200 }\n        }\n        local function getValue(res)\n            if res and res.path then\n                if typeof(res.path) == \"Instance\" and typeof(res.path) == \"Instance\" and res.path:IsA(\"NumberValue\") or res.path:IsA(\"IntValue\") then\n                    return res.path.Value\n                end\n            end\n            return 0\n        end\n        local need1 = resources[option1]\n        local need2 = resources[option2]\n        if not need1 or not need2 then return false, \"Invalid option\" end\n        local val1 = getValue(need1)\n        local val2 = getValue(need2)\n        if val1 >= need1.needed and val2 >= need2.needed then\n            return true, \"Enough\"\n        else\n            local msg = option1 .. \" (\" .. val1 .. \"/\" .. need1.needed .. \") or \" .. option2 .. \" (\" .. val2 .. \"/\" .. need2.needed .. \")\"\n            return false, \"Not enough: \" .. msg\n        end\n    end\n\n    local autoToggle = Cfg.register(UpgradeSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Rebirth\", {\n        Name = \"Auto Rebirth\",\n        Default = false,\n        Callback = function(value)\n            NexusState.autoRebirthRunning = value\n            if value then\n                if NexusState.autoRebirthThread then\n                    task.cancel(NexusState.autoRebirthThread)\n                    NexusState.autoRebirthThread = nil\n                end\n                NexusState.autoRebirthThread = task.spawn(function()\n                    while NexusState.autoRebirthRunning do\n                        pcall(function()\n                            if #NexusState.selectedOptions ~= 2 then\n                                NexusLib:Notify({ Title = \"Auto Rebirth\", Message = \"Please select exactly 2 options!\", Duration = 2 })\n                                task.wait(2)\n                                return\n                            end\n                            local ok, msg = checkResources(NexusState.selectedOptions[1], NexusState.selectedOptions[2])\n                            if ok then\n                                NexusState.upgradeCharacter.teleported = false\n                                NexusState.upgradeCharacter.oldPosition = nil\n                                if NexusState.upgradeCharacter.method == \"Teleport\" then\n                                    local npc = Workspace:FindFirstChild(\"NPC\")\n                                    if npc then\n                                        local func = npc:FindFirstChild(\"Function\")\n                                        if func then\n                                            local theShadow = func:FindFirstChild(\"The Shadow\")\n                                            if typeof(theShadow) == \"Instance\" and theShadow:IsA(\"Model\") then\n                                                local hrp = theShadow:FindFirstChild(\"HumanoidRootPart\")\n                                                if hrp then\n                                                    local char = LocalPlayer.Character\n                                                    if char then\n                                                        local root = char:FindFirstChild(\"HumanoidRootPart\")\n                                                        if root then\n                                                            NexusState.upgradeCharacter.oldPosition = root.Position\n                                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                                            NexusState.upgradeCharacter.teleported = true\n                                                            task.wait(0.3)\n                                                        end\n                                                    end\n                                                end\n                                            end\n                                        end\n                                    end\n                                    if not NexusState.upgradeCharacter.teleported then\n                                        NexusLib:Notify({ Title = \"Auto Rebirth\", Message = \"Could not find The Shadow, teleport failed. Continuing anyway.\", Duration = 3 })\n                                    end\n                                end\n\n                                local result = NexusState.UpgradeCharacter:InvokeServer(NexusState.selectedOptions)\n                                if result and result.ok then\n                                    NexusLib:Notify({ Title = \"Auto Rebirth\", Message = \"Upgraded successfully!\", Duration = 2 })\n                                else\n                                    NexusLib:Notify({ Title = \"Auto Rebirth\", Message = \"Upgrade failed: \" .. (result and result.msg or \"unknown error\"), Duration = 3 })\n                                end\n\n                                if NexusState.upgradeCharacter.teleported and NexusState.upgradeCharacter.oldPosition then\n                                    local char = LocalPlayer.Character\n                                    if char then\n                                        local root = char:FindFirstChild(\"HumanoidRootPart\")\n                                        if root then\n                                            root.CFrame = CFrame.new(NexusState.upgradeCharacter.oldPosition)\n                                            NexusState.upgradeCharacter.oldPosition = nil\n                                            NexusState.upgradeCharacter.teleported = false\n                                        end\n                                    end\n                                end\n                            else\n                                if math.random(1, 5) == 1 then\n                                    NexusLib:Notify({ Title = \"Auto Rebirth\", Message = msg, Duration = 3 })\n                                end\n                            end\n                        end)\n                        task.wait(2)\n                    end\n                end)\n            else\n                if NexusState.autoRebirthThread then\n                    task.cancel(NexusState.autoRebirthThread)\n                    NexusState.autoRebirthThread = nil\n                end\n                if NexusState.upgradeCharacter.teleported and NexusState.upgradeCharacter.oldPosition then\n                    local char = LocalPlayer.Character\n                    if char then\n                        local root = char:FindFirstChild(\"HumanoidRootPart\")\n                        if root then\n                            root.CFrame = CFrame.new(NexusState.upgradeCharacter.oldPosition)\n                            NexusState.upgradeCharacter.oldPosition = nil\n                            NexusState.upgradeCharacter.teleported = false\n                        end\n                    end\n                end\n                NexusLib:Notify({ Title = \"Auto Rebirth\", Message = \"Stopped\", Duration = 2 })\n            end\n        end\n    })), \"Toggle\", \"Auto Rebirth\", {\n        Name = \"Auto Rebirth\",\n        Default = false,\n        Callback = function(value)\n            NexusState.autoRebirthRunning = value\n            if value then\n                if NexusState.autoRebirthThread then\n                    task.cancel(NexusState.autoRebirthThread)\n                    NexusState.autoRebirthThread = nil\n                end\n                NexusState.autoRebirthThread = task.spawn(function()\n                    while NexusState.autoRebirthRunning do\n                        pcall(function()\n                            if #NexusState.selectedOptions ~= 2 then\n                                NexusLib:Notify({ Title = \"Auto Rebirth\", Message = \"Please select exactly 2 options!\", Duration = 2 })\n                                task.wait(2)\n                                return\n                            end\n                            local ok, msg = checkResources(NexusState.selectedOptions[1], NexusState.selectedOptions[2])\n                            if ok then\n                                NexusState.upgradeCharacter.teleported = false\n                                NexusState.upgradeCharacter.oldPosition = nil\n                                if NexusState.upgradeCharacter.method == \"Teleport\" then\n                                    local npc = Workspace:FindFirstChild(\"NPC\")\n                                    if npc then\n                                        local func = npc:FindFirstChild(\"Function\")\n                                        if func then\n                                            local theShadow = func:FindFirstChild(\"The Shadow\")\n                                            if typeof(theShadow) == \"Instance\" and theShadow:IsA(\"Model\") then\n                                                local hrp = theShadow:FindFirstChild(\"HumanoidRootPart\")\n                                                if hrp then\n                                                    local char = LocalPlayer.Character\n                                                    if char then\n                                                        local root = char:FindFirstChild(\"HumanoidRootPart\")\n                                                        if root then\n                                                            NexusState.upgradeCharacter.oldPosition = root.Position\n                                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                                            NexusState.upgradeCharacter.teleported = true\n                                                            task.wait(0.3)\n                                                        end\n                                                    end\n                                                end\n                                            end\n                                        end\n                                    end\n                                    if not NexusState.upgradeCharacter.teleported then\n                                        NexusLib:Notify({ Title = \"Auto Rebirth\", Message = \"Could not find The Shadow, teleport failed. Continuing anyway.\", Duration = 3 })\n                                    end\n                                end\n\n                                local result = NexusState.UpgradeCharacter:InvokeServer(NexusState.selectedOptions)\n                                if result and result.ok then\n                                    NexusLib:Notify({ Title = \"Auto Rebirth\", Message = \"Upgraded successfully!\", Duration = 2 })\n                                else\n                                    NexusLib:Notify({ Title = \"Auto Rebirth\", Message = \"Upgrade failed: \" .. (result and result.msg or \"unknown error\"), Duration = 3 })\n                                end\n\n                                if NexusState.upgradeCharacter.teleported and NexusState.upgradeCharacter.oldPosition then\n                                    local char = LocalPlayer.Character\n                                    if char then\n                                        local root = char:FindFirstChild(\"HumanoidRootPart\")\n                                        if root then\n                                            root.CFrame = CFrame.new(NexusState.upgradeCharacter.oldPosition)\n                                            NexusState.upgradeCharacter.oldPosition = nil\n                                            NexusState.upgradeCharacter.teleported = false\n                                        end\n                                    end\n                                end\n                            else\n                                if math.random(1, 5) == 1 then\n                                    NexusLib:Notify({ Title = \"Auto Rebirth\", Message = msg, Duration = 3 })\n                                end\n                            end\n                        end)\n                        task.wait(2)\n                    end\n                end)\n            else\n                if NexusState.autoRebirthThread then\n                    task.cancel(NexusState.autoRebirthThread)\n                    NexusState.autoRebirthThread = nil\n                end\n                if NexusState.upgradeCharacter.teleported and NexusState.upgradeCharacter.oldPosition then\n                    local char = LocalPlayer.Character\n                    if char then\n                        local root = char:FindFirstChild(\"HumanoidRootPart\")\n                        if root then\n                            root.CFrame = CFrame.new(NexusState.upgradeCharacter.oldPosition)\n                            NexusState.upgradeCharacter.oldPosition = nil\n                            NexusState.upgradeCharacter.teleported = false\n                        end\n                    end\n                end\n                NexusLib:Notify({ Title = \"Auto Rebirth\", Message = \"Stopped\", Duration = 2 })\n            end\n        end\n    })\n\n    local function displayStats()\n        local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n        if not userData then return end\n        local cash = userData:FindFirstChild(\"Cash\") and userData.Cash.Value or 0\n        local level = userData:FindFirstChild(\"Level\") and userData.Level:FindFirstChild(\"Level\") and userData.Level.Level.Value or 0\n        local crystal = userData:FindFirstChild(\"Crystal\") and userData.Crystal.Value or 0\n        local ticket = userData:FindFirstChild(\"Ticket\") and userData.Ticket.Value or 0\n        NexusLib:Notify({\n            Title = \"Resources\",\n            Message = string.format(\"Cash: %.2fB | Level: %d | Crystal: %d | Ticket: %d\", cash/1e9, level, crystal, ticket),\n            Duration = 4\n        })\n    end\n    UpgradeSection:CreateButton({ Name = \"Check Resources\", Callback = displayStats })\nend\n\n-- ============================================================\n-- ===== TELEPORT TAB =====\n-- ============================================================\ndo\n    local TeleportTab = Window:CreateTab(\"Teleport\")\n    local TPSection = TeleportTab:CreateSection(\"NPC & Weather\", \"Left\")\n\n    TPSection:CreateButton({\n        Name = \"TP to Taoist\",\n        Callback = function()\n            local taoist = nil\n            for _, v in pairs(Workspace:GetDescendants()) do\n                if typeof(v) == \"Instance\" and typeof(v) == \"Instance\" and v:IsA(\"Model\") and string.find(v.Name:lower(), \"taoist\") and v:FindFirstChild(\"HumanoidRootPart\") then\n                    taoist = v\n                    break\n                end\n            end\n            if taoist and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\") then\n                LocalPlayer.Character.HumanoidRootPart.CFrame = taoist.HumanoidRootPart.CFrame * CFrame.new(0, 0, 4)\n                NexusLib:Notify({ Title = \"Taoist\", Message = \"Teleported!\", Duration = 3 })\n            else\n                NexusLib:Notify({ Title = \"Taoist\", Message = \"Not found!\", Duration = 3 })\n            end\n        end\n    })\n\n    TPSection:CreateButton({\n        Name = \"TP to Maoshan\",\n        Callback = function()\n            local maoshan = nil\n            for _, v in pairs(Workspace:GetDescendants()) do\n                if typeof(v) == \"Instance\" and typeof(v) == \"Instance\" and v:IsA(\"Model\") and (string.find(v.Name:lower(), \"maoshan\") or string.find(v.Name:lower(), \"merchant\")) and v:FindFirstChild(\"HumanoidRootPart\") then\n                    maoshan = v\n                    break\n                end\n            end\n            if maoshan and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\") then\n                LocalPlayer.Character.HumanoidRootPart.CFrame = maoshan.HumanoidRootPart.CFrame * CFrame.new(0, 0, 4)\n                NexusLib:Notify({ Title = \"Maoshan\", Message = \"Teleported!\", Duration = 3 })\n            else\n                NexusLib:Notify({ Title = \"Maoshan\", Message = \"Not found!\", Duration = 3 })\n            end\n        end\n    })\n\n    TPSection:CreateButton({\n        Name = \"TP to Spirit\",\n        Callback = function()\n            local godFolder = Workspace:FindFirstChild(\"NPC\") and Workspace.NPC:FindFirstChild(\"God\")\n            if not godFolder then\n                NexusLib:Notify({ Title = \"Spirit\", Message = \"Folder God not found!\", Duration = 3 })\n                return\n            end\n            local target = nil\n            for _, child in pairs(godFolder:GetChildren()) do\n                if typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"Model\") then\n                    local hrp = child:FindFirstChild(\"HumanoidRootPart\")\n                    if hrp then\n                        target = hrp\n                        break\n                    end\n                elseif typeof(child) == \"Instance\" and typeof(child) == \"Instance\" and child:IsA(\"BasePart\") then\n                    target = child\n                    break\n                end\n            end\n            if not target then\n                NexusLib:Notify({ Title = \"Spirit\", Message = \"No Spirit found!\", Duration = 3 })\n                return\n            end\n            local char = LocalPlayer.Character\n            if not char then return end\n            local hrp = char:FindFirstChild(\"HumanoidRootPart\")\n            if hrp then\n                hrp.CFrame = target.CFrame + Vector3.new(0, 3, 0)\n                NexusLib:Notify({ Title = \"Spirit\", Message = \"Teleported to Spirit!\", Duration = 3 })\n            end\n        end\n    })\n\n    -- ===== NPC TELEPORT + GIVE FISH (Duan Gan / Dumb guy) =====\n    do\n        local GiveSection = TeleportTab:CreateSection(\"Quest NPC & Give Fish\", \"Right\")\n\n        local function npcRoot()\n            return Workspace:FindFirstChild(\"NPC\")\n        end\n\n        local function findNpcHrp(npcName)\n            local hrp = nil\n            pcall(function()\n                local npcFolder = npcRoot()\n                if not npcFolder then return end\n                local f = npcFolder:FindFirstChild(\"Function\")\n                local m = (f and f:FindFirstChild(npcName)) or npcFolder:FindFirstChild(npcName)\n                if m then hrp = m:FindFirstChild(\"HumanoidRootPart\") or m:FindFirstChild(\"Torso\") end\n            end)\n            return hrp\n        end\n\n        local function teleportNearNpc(npcName, offset)\n            local hrp = findNpcHrp(npcName)\n            local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n            if not hrp or not root then return false end\n            pcall(function()\n                root.CFrame = CFrame.new(hrp.Position + (offset or Vector3.new(0, 3, 0)))\n            end)\n            return true\n        end\n\n        local function parseWeightKg(text)\n            local clean = string.gsub(text, \"[,%s]\", \"\")\n            local num, suffix = string.match(clean, \"(%d+%.?%d*)([KkMmBbTt]?)\")\n            local n = tonumber(num) or 0\n            if suffix == \"K\" or suffix == \"k\" then\n                n = n * 1000\n            elseif suffix == \"M\" or suffix == \"m\" then\n                n = n * 1000000\n            elseif suffix == \"B\" or suffix == \"b\" then\n                n = n * 1000000000\n            elseif suffix == \"T\" or suffix == \"t\" then\n                n = n * 1000000000000\n            end\n            return n\n        end\n\n        local function getFishKg(item)\n            local w = 0\n            pcall(function()\n                local attr = item:GetAttribute(\"Weight\")\n                if tonumber(attr) and tonumber(attr) > 0 then\n                    w = tonumber(attr)\n                elseif typeof(item) == \"Instance\" and typeof(item) == \"Instance\" and item:IsA(\"StringValue\") then\n                    local parts = {}\n                    for part in string.gmatch(item.Value, \"[^|]+\") do table.insert(parts, part) end\n                    if #parts >= 2 then w = parseWeightKg(parts[2]) end\n                elseif typeof(item) == \"Instance\" and typeof(item) == \"Instance\" and item:IsA(\"NumberValue\") or item:IsA(\"IntValue\") then\n                    w = tonumber(item.Value) or 0\n                end\n            end)\n            return w\n        end\n\n        local function collectBigFish(minKg)\n            local out = {}\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            local inv = userData and userData:FindFirstChild(\"Inventory\")\n            if not inv then return out end\n            for _, item in pairs(inv:GetChildren()) do\n                local kg = getFishKg(item)\n                if kg >= minKg then\n                    table.insert(out, { item = item, name = item.Name, kg = kg })\n                end\n            end\n            table.sort(out, function(a, b) return a.kg > b.kg end)\n            return out\n        end\n\n        local function giveFishToDumbGuy(entry)\n            if not entry or not entry.item then return false end\n            local model = nil\n            pcall(function()\n                local npcFolder = npcRoot()\n                local f = npcFolder and npcFolder:FindFirstChild(\"Function\")\n                model = f and f:FindFirstChild(\"Dumb guy\")\n            end)\n            if not model then return false end\n            local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n            local origCF = root and root.CFrame\n            if teleportNearNpc(\"Dumb guy\", Vector3.new(0, 3, 0)) then task.wait(0.4) end\n\n            pcall(function() Events.StartDialogue:FireServer(\"Dumb guy\", model) end)\n            task.wait(0.15)\n\n            local fired = false\n            pcall(function()\n                Events.ChooseDialogueOption:FireServer(\"Dumb guy\", 1, \"GiveFish\", { model })\n                fired = true\n            end)\n\n            if origCF and root and root.Parent then\n                task.wait(0.3)\n                pcall(function() root.CFrame = origCF end)\n            end\n            return fired\n        end\n\n        GiveSection:CreateButton({\n            Name = \"Teleport To Duan Gan NPC\",\n            Callback = function()\n                if teleportNearNpc(\"Duan Gan\", Vector3.new(0, 3, 0)) then\n                    NexusLib:Notify({ Title = \"Duan Gan\", Message = \"Teleported!\", Duration = 3 })\n                else\n                    NexusLib:Notify({ Title = \"Duan Gan\", Message = \"NPC not found!\", Duration = 3 })\n                end\n            end\n        })\n\n        GiveSection:CreateButton({\n            Name = \"Teleport To Dumb Guy NPC\",\n            Callback = function()\n                if teleportNearNpc(\"Dumb guy\", Vector3.new(0, 3, 0)) then\n                    NexusLib:Notify({ Title = \"Dumb Guy\", Message = \"Teleported!\", Duration = 3 })\n                else\n                    NexusLib:Notify({ Title = \"Dumb Guy\", Message = \"NPC not found!\", Duration = 3 })\n                end\n            end\n        })\n\n        GiveSection:CreateButton({\n            Name = \"Give 1 Fish > 2M kg\",\n            Callback = function()\n                local list = collectBigFish(2000000)\n                if #list == 0 then\n                    NexusLib:Notify({ Title = \"Give Fish\", Message = \"No fish over 2M kg in inventory!\", Duration = 3 })\n                    return\n                end\n                local e = list[1]\n                if giveFishToDumbGuy(e) then\n                    NexusLib:Notify({ Title = \"Give Fish\", Message = \"Gave \" .. e.name .. \" (\" .. tostring(e.kg) .. \" kg)\", Duration = 3 })\n                else\n                    NexusLib:Notify({ Title = \"Give Fish\", Message = \"Failed to give fish!\", Duration = 3 })\n                end\n            end\n        })\n        NexusState.autoGiveFishRunning = false\n        NexusState.autoGiveFishThread = nil\n\n        Cfg.register(GiveSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Give Fish > 2M kg\", {\n            Name = \"Auto Give Fish > 2M kg\",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoGiveFishRunning = value\n                if NexusState.autoGiveFishThread then\n                    pcall(task.cancel, NexusState.autoGiveFishThread)\n                    NexusState.autoGiveFishThread = nil\n                end\n                if not value then return end\n                NexusState.autoGiveFishThread = task.spawn(function()\n                    while NexusState.autoGiveFishRunning do\n                        pcall(function()\n                            local list = collectBigFish(2000000)\n                            if #list > 0 then giveFishToDumbGuy(list[1]) end\n                        end)\n                        task.wait(2)\n                    end\n                end)\n            end\n        })), \"Toggle\", \"Auto Give Fish > 2M kg\", {\n            Name = \"Auto Give Fish > 2M kg\",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoGiveFishRunning = value\n                if NexusState.autoGiveFishThread then\n                    pcall(task.cancel, NexusState.autoGiveFishThread)\n                    NexusState.autoGiveFishThread = nil\n                end\n                if not value then return end\n                NexusState.autoGiveFishThread = task.spawn(function()\n                    while NexusState.autoGiveFishRunning do\n                        pcall(function()\n                            local list = collectBigFish(2000000)\n                            if #list > 0 then giveFishToDumbGuy(list[1]) end\n                        end)\n                        task.wait(2)\n                    end\n                end)\n            end\n        })\n\n        -- ===== AUTO FARM CA 2M+ KG =====\n        NexusState.autoFarm2MRunning = false\n        NexusState.autoFarm2MThread = nil\n\n        local function findBigKgIsland()\n            local best, bestKg = nil, 0\n            pcall(function()\n                local rarity = Info:FindFirstChild(\"FishingAreaRarity\")\n                if not rarity then return end\n                for _, area in pairs(rarity:GetChildren()) do\n                    local maxKg = area:FindFirstChild(\"MaxKg\")\n                    local v = maxKg and tonumber(maxKg.Value) or 0\n                    if v >= 2000000 and v > bestKg then\n                        bestKg = v\n                        best = area.Name\n                    end\n                end\n            end)\n            return best, bestKg\n        end\n\n        Cfg.register(GiveSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Farm 2M+ kg Fish\", {\n            Name = \"Auto Farm 2M+ kg Fish\",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoFarm2MRunning = value\n                if NexusState.autoFarm2MThread then\n                    pcall(task.cancel, NexusState.autoFarm2MThread)\n                    NexusState.autoFarm2MThread = nil\n                end\n                if not value then return end\n\n                local islandName, kg = findBigKgIsland()\n                if islandName then\n                    for _, isl in ipairs(NexusState.islands) do\n                        if isl.name == islandName then\n                            local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n                            if root then pcall(function() root.CFrame = isl.cframe end) end\n                            break\n                        end\n                    end\n                    NexusLib:Notify({\n                        Title = \"Auto Farm 2M+\",\n                        Message = \"Farming at \" .. islandName .. \" (max \" .. tostring(kg) .. \" kg)\",\n                        Duration = 3\n                    })\n                else\n                    NexusLib:Notify({ Title = \"Auto Farm 2M+\", Message = \"No 2M+ zone found, farming here.\", Duration = 3 })\n                end\n\n                NexusState.autoFarm2MThread = task.spawn(function()\n                    while NexusState.autoFarm2MRunning do\n                        pcall(function()\n                            local c = LocalPlayer.Character\n                            if c and not c:GetAttribute(\"Fishing\") and NexusState.canCastNow() then\n                                Events.Fishing:FireServer()\n                            end\n                        end)\n                        task.wait(0.6)\n                    end\n                end)\n            end\n        })), \"Toggle\", \"Auto Farm 2M+ kg Fish\", {\n            Name = \"Auto Farm 2M+ kg Fish\",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoFarm2MRunning = value\n                if NexusState.autoFarm2MThread then\n                    pcall(task.cancel, NexusState.autoFarm2MThread)\n                    NexusState.autoFarm2MThread = nil\n                end\n                if not value then return end\n\n                local islandName, kg = findBigKgIsland()\n                if islandName then\n                    for _, isl in ipairs(NexusState.islands) do\n                        if isl.name == islandName then\n                            local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n                            if root then pcall(function() root.CFrame = isl.cframe end) end\n                            break\n                        end\n                    end\n                    NexusLib:Notify({\n                        Title = \"Auto Farm 2M+\",\n                        Message = \"Farming at \" .. islandName .. \" (max \" .. tostring(kg) .. \" kg)\",\n                        Duration = 3\n                    })\n                else\n                    NexusLib:Notify({ Title = \"Auto Farm 2M+\", Message = \"No 2M+ zone found, farming here.\", Duration = 3 })\n                end\n\n                NexusState.autoFarm2MThread = task.spawn(function()\n                    while NexusState.autoFarm2MRunning do\n                        pcall(function()\n                            local c = LocalPlayer.Character\n                            if c and not c:GetAttribute(\"Fishing\") and NexusState.canCastNow() then\n                                Events.Fishing:FireServer()\n                            end\n                        end)\n                        task.wait(0.6)\n                    end\n                end)\n            end\n        })\n    end\n\n    local weatherIslands = {\n        [\"foggy\"] = \"Island 7\", [\"blazing sun\"] = \"Island 8\", [\"snowy\"] = \"Island 6\",\n        [\"windy\"] = \"Island 5\", [\"rainy\"] = \"Island 3\", [\"thunderstorm\"] = \"Island 2\"\n    }\n\n    local function getCurrentWeather()\n        local info = MainGui:FindFirstChild(\"Info\")\n        if info then\n            local infoFrame = info:FindFirstChild(\"Info\")\n            if infoFrame then\n                local weatherFrame = infoFrame:FindFirstChild(\"Weather\")\n                if weatherFrame then\n                    local val = weatherFrame:FindFirstChild(\"Value\")\n                    if val and typeof(val) == \"Instance\" then\n                        local text = ((typeof(val) == \"Instance\" and val:IsA(\"TextLabel\") and val.Text or val.Value))\n                        return text:gsub(\"Weather:%s*\", \"\")\n                    end\n                end\n            end\n        end\n        return \"Clear\"\n    end\n\n    TPSection:CreateButton({\n        Name = \"Teleport To Current Weather\",\n        Callback = function()\n            local currentWeather = getCurrentWeather()\n            if currentWeather:lower() == \"clear\" or currentWeather == \"\" then\n                NexusLib:Notify({ Title = \"Weather TP\", Message = \"Server weather is Clear, no event to TP!\", Duration = 3 })\n                return\n            end\n            local targetIslandName = weatherIslands[currentWeather:lower()]\n            if targetIslandName then\n                for _, v in ipairs(NexusState.islands) do\n                    if v.name:lower() == targetIslandName:lower() then\n                        local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n                        if hrp then\n                            hrp.CFrame = CFrame.new(v.cframe.Position) + Vector3.new(0, 5, 0)\n                            NexusLib:Notify({ Title = \"Weather TP\", Message = \"Teleported to \" .. targetIslandName .. \" for \" .. currentWeather, Duration = 4 })\n                        end\n                        return\n                    end\n                end\n            else\n                NexusLib:Notify({ Title = \"Weather TP\", Message = \"Unknown weather island mapping for: \" .. currentWeather, Duration = 4 })\n            end\n        end\n    })\n\n    -- Server\n    do\n        local ServerSection = TeleportTab:CreateSection(\"Server\", \"Left\")\n        local b64chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'\n        local function b64decode(data)\n            data = string.gsub(data, '[^'..b64chars..'=]', '')\n            return (data:gsub('.', function(x)\n                if (x == '=') then return '' end\n                local r,f='',(b64chars:find(x, 1, true)-1)\n                for i=6,1,-1 do r=r..(f%2^i-f%2^(i-1)>0 and '1' or '0') end\n                return r;\n            end):gsub('%d%d%d?%d?%d?%d?%d?%d?', function(x)\n                if (#x ~= 8) then return '' end\n                local c=0\n                for i=1,8 do c=c+(x:sub(i,i)=='1' and 2^(8-i) or 0) end\n                return string.char(c)\n            end))\n        end\n\n        local savedJobId = \"\"\n        local lastHopAt = 0\n        ServerSection:CreateTextbox({\n            Name = \"Join by Job ID\",\n            Placeholder = \"Paste Job ID here...\",\n            Default = \"\",\n            Callback = function(text)\n                if text and text ~= \"\" then\n                    local finalJobId = text\n                    local matchB64 = string.match(text, \"NEXUSHUB|([^%s]+)\")\n                    if matchB64 then\n                        local success, decoded = pcall(b64decode, matchB64)\n                        if success and decoded and decoded ~= \"\" then\n                            finalJobId = decoded\n                        end\n                    end\n                    if finalJobId == game.JobId then\n                        NexusLib:Notify({ Title = \"Server Hop\", Message = \"Already in this server.\", Duration = 3 })\n                        return\n                    end\n                    if tick() - lastHopAt < 30 then\n                        NexusLib:Notify({ Title = \"Server Hop\", Message = \"Hop cooldown, try again shortly.\", Duration = 3 })\n                        return\n                    end\n                    lastHopAt = tick()\n                    savedJobId = finalJobId\n                    NexusLib:Notify({ Title = \"Server Hop\", Message = \"Joining server...\", Duration = 3 })\n                    Services.TeleportService:TeleportToPlaceInstance(game.PlaceId, finalJobId, LocalPlayer)\n                end\n            end\n        })\n        ServerSection:CreateButton({\n            Name = \"Delete Job ID\",\n            Callback = function()\n                savedJobId = \"\"\n                NexusLib:Notify({ Title = \"Server Hop\", Message = \"Job ID cleared!\", Duration = 2 })\n            end\n        })\n    end\n\n    -- Islands\n    do\n        local IslandSection = TeleportTab:CreateSection(\"Islands\", \"Right\")\n        for _, v in ipairs(NexusState.islands) do\n            IslandSection:CreateButton({\n                Name = v.name,\n                Callback = function()\n                    local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n                    if hrp then\n                        hrp.CFrame = CFrame.new(v.cframe.Position) + Vector3.new(0, 5, 0)\n                        NexusLib:Notify({ Title = \"Teleport\", Message = \"Teleported to \" .. v.name, Duration = 3 })\n                    end\n                end\n            })\n        end\n    end\n    -- ===== PLAYERS SECTION =====\n    do\n        local PlayerSection = TeleportTab:CreateSection(\"Players\", \"Right\")\n        \n        local selectedPlayer = nil\n        local playerDropdown = nil  -- Keep a reference to the dropdown\n        local playerList = {}\n        \n        -- List refresh helper\n        local function refreshPlayerList()\n            -- Read the player list\n            playerList = {}\n            for _, player in ipairs(Players:GetPlayers()) do\n                if player ~= LocalPlayer then\n                    table.insert(playerList, player.Name)\n                end\n            end\n            if #playerList == 0 then\n                table.insert(playerList, \"No other players\")\n                selectedPlayer = \"No other players\"\n            else\n                selectedPlayer = playerList[1]\n            end\n            \n            -- Remove the old dropdown if present\n            if playerDropdown and playerDropdown._frame then\n                pcall(function()\n                    playerDropdown._frame:Destroy()\n                end)\n                playerDropdown = nil\n            end\n            \n            -- Create the new dropdown\n            playerDropdown = PlayerSection:CreateDropdown({\n                Name = \"Select Player\",\n                Options = playerList,\n                Default = selectedPlayer,\n                Callback = function(value)\n                    selectedPlayer = value\n                end\n            })\n        end\n        \n        -- Create the dropdown for the first time\n        refreshPlayerList()\n        \n        -- Refresh List button\n        PlayerSection:CreateButton({\n            Name = \"Refresh List\",\n            Callback = function()\n                refreshPlayerList()\n                NexusLib:Notify({\n                    Title = \"Players\",\n                    Message = \"Player list refreshed! Found \" .. #playerList .. \" players.\",\n                    Duration = 2\n                })\n            end\n        })\n        \n        -- Teleport to Player button\n        PlayerSection:CreateButton({\n            Name = \"Teleport to Player\",\n            Callback = function()\n                if not selectedPlayer or selectedPlayer == \"No other players\" then\n                    NexusLib:Notify({ Title = \"Teleport\", Message = \"No valid player selected!\", Duration = 2 })\n                    return\n                end\n                \n                local targetPlayer = nil\n                for _, player in ipairs(Players:GetPlayers()) do\n                    if player.Name == selectedPlayer then\n                        targetPlayer = player\n                        break\n                    end\n                end\n                \n                if not targetPlayer then\n                    NexusLib:Notify({ Title = \"Teleport\", Message = \"Player not found! Try refreshing.\", Duration = 2 })\n                    return\n                end\n                \n                local character = targetPlayer.Character\n                if not character then\n                    NexusLib:Notify({ Title = \"Teleport\", Message = targetPlayer.Name .. \" has no character!\", Duration = 2 })\n                    return\n                end\n                \n                local hrp = character:FindFirstChild(\"HumanoidRootPart\")\n                if not hrp then\n                    NexusLib:Notify({ Title = \"Teleport\", Message = \"Cannot find HumanoidRootPart!\", Duration = 2 })\n                    return\n                end\n                \n                local myChar = LocalPlayer.Character\n                if not myChar then return end\n                local myHrp = myChar:FindFirstChild(\"HumanoidRootPart\")\n                if not myHrp then return end\n                \n                myHrp.CFrame = hrp.CFrame + Vector3.new(0, 3, 0)\n                \n                NexusLib:Notify({\n                    Title = \"Teleport\",\n                    Message = \"Teleported to \" .. targetPlayer.Name,\n                    Duration = 2\n                })\n            end\n        })\n    -- ===== SPECTATE PLAYER =====\n        local spectateEnabled = false\n        local spectateTarget = nil\n        local oldSubject = nil\n        local oldCameraType = nil\n        local espConnections = {}\n        \n        -- Start spectate\n        local function startSpectate()\n            if spectateEnabled then return end\n            \n            -- Find the first player other than yourself\n            local targetPlayer = nil\n            for _, player in ipairs(Players:GetPlayers()) do\n                if player ~= LocalPlayer then\n                    targetPlayer = player\n                    break\n                end\n            end\n            \n            if not targetPlayer then\n                NexusLib:Notify({ Title = \"Spectate\", Message = \"No other players to spectate!\", Duration = 2 })\n                if NexusState.spectateToggle then\n                    NexusState.spectateToggle:Set(false)\n                end\n                return\n            end\n            \n            -- Check whether the target has a character\n            if not targetPlayer.Character then\n                NexusLib:Notify({ Title = \"Spectate\", Message = targetPlayer.Name .. \" has no character!\", Duration = 2 })\n                if NexusState.spectateToggle then\n                    NexusState.spectateToggle:Set(false)\n                end\n                return\n            end\n            \n            local targetHrp = targetPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n            if not targetHrp then\n                NexusLib:Notify({ Title = \"Spectate\", Message = \"Cannot find HumanoidRootPart of \" .. targetPlayer.Name, Duration = 2 })\n                if NexusState.spectateToggle then\n                    NexusState.spectateToggle:Set(false)\n                end\n                return\n            end\n            \n            spectateEnabled = true\n            spectateTarget = targetPlayer\n            \n            local camera = workspace.CurrentCamera\n            oldSubject = camera.CameraSubject\n            oldCameraType = camera.CameraType\n            \n            -- Lock the camera onto the target\n            camera.CameraSubject = targetHrp\n            camera.CameraType = Enum.CameraType.Custom\n            \n            NexusLib:Notify({ Title = \"Spectate\", Message = \"Spectating \" .. targetPlayer.Name, Duration = 2 })\n        end\n        \n        -- Stop spectate\n        local function stopSpectate()\n            spectateEnabled = false\n            spectateTarget = nil\n            \n            -- Reset the camera back to the local player\n            pcall(function()\n                local camera = workspace.CurrentCamera\n                if oldSubject then\n                    camera.CameraSubject = oldSubject\n                    oldSubject = nil\n                end\n                if oldCameraType then\n                    camera.CameraType = oldCameraType\n                    oldCameraType = nil\n                end\n            end)\n            \n            NexusLib:Notify({ Title = \"Spectate\", Message = \"Stopped spectating\", Duration = 2 })\n        end\n        \n        -- Toggle Spectate Player\n        local spectateToggle = Cfg.register(PlayerSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Spectate Player\", {\n            Name = \"Spectate Player\",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    startSpectate()\n                else\n                    stopSpectate()\n                end\n            end\n        })), \"Toggle\", \"Spectate Player\", {\n            Name = \"Spectate Player\",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    startSpectate()\n                else\n                    stopSpectate()\n                end\n            end\n        })\n        \n        -- Persist the toggle in NexusState\n        NexusState.spectateToggle = spectateToggle\n        \n        -- Handle the target leaving or their character resetting\n        local function onTargetCharacterAdded()\n            if spectateEnabled and spectateTarget then\n                local char = spectateTarget.Character\n                if char then\n                    local hrp = char:FindFirstChild(\"HumanoidRootPart\")\n                    if hrp then\n                        workspace.CurrentCamera.CameraSubject = hrp\n                    end\n                end\n            end\n        end\n        \n        -- Listen for the target's character changing\n        local charAddedConn = nil\n        local playerRemovingConn = Players.PlayerRemoving:Connect(function(player)\n            if spectateEnabled and player == spectateTarget then\n                stopSpectate()\n                if NexusState.spectateToggle then\n                    NexusState.spectateToggle:Set(false)\n                end\n            end\n        end)\n        \n        -- While spectating, watch the target's CharacterAdded\n        local function monitorTarget()\n            if spectateEnabled and spectateTarget then\n                if charAddedConn then charAddedConn:Disconnect() end\n                charAddedConn = spectateTarget.CharacterAdded:Connect(function()\n                    task.wait(0.5)\n                    onTargetCharacterAdded()\n                end)\n            else\n                if charAddedConn then\n                    charAddedConn:Disconnect()\n                    charAddedConn = nil\n                end\n            end\n        end\n        \n        -- Wrap startSpectate to attach the monitor\n        local originalStart = startSpectate\n        startSpectate = function()\n            originalStart()\n            monitorTarget()\n        end\n        \n        -- Wrap stopSpectate to clean up\n        local originalStop = stopSpectate\n        stopSpectate = function()\n            originalStop()\n            if charAddedConn then\n                charAddedConn:Disconnect()\n                charAddedConn = nil\n            end\n        end\n        \n        table.insert(espConnections, { conn = playerRemovingConn })\n    end\n    -- ===== NPCs SECTION =====\n    do\n        local NpcSection = TeleportTab:CreateSection(\"NPCs\", \"Right\")\n        \n        -- NPC list helper (models parented to a Folder under workspace.NPC.Function)\n        local function getNpcList()\n            local npcs = {}\n            local funcFolder = workspace:FindFirstChild(\"NPC\") and workspace.NPC:FindFirstChild(\"Function\")\n            if not funcFolder then return npcs end\n            \n            for _, child in ipairs(funcFolder:GetDescendants()) do\n                if typeof(child) == \"Instance\" and child:IsA(\"Model\") and child.Parent and typeof(child.Parent) == \"Instance\" and child.Parent:IsA(\"Folder\") then\n                    table.insert(npcs, child.Name)\n                end\n            end\n            return npcs\n        end\n        \n        local npcList = getNpcList()\n        if #npcList == 0 then\n            table.insert(npcList, \"No NPCs found\")\n        end\n        \n        local selectedNpc = npcList[1]\n        \n        -- Create the dropdown\n        local npcDropdown = NpcSection:CreateDropdown({\n            Name = \"Misc NPCs\",\n            Options = npcList,\n            Default = selectedNpc,\n            Callback = function(value)\n                selectedNpc = value\n            end\n        })\n        \n        -- Teleport to selected NPC button\n        NpcSection:CreateButton({\n            Name = \"Teleport to selected NPC\",\n            Callback = function()\n                if not selectedNpc or selectedNpc == \"No NPCs found\" then\n                    NexusLib:Notify({ Title = \"NPC Teleport\", Message = \"No NPC selected!\", Duration = 2 })\n                    return\n                end\n                \n                local funcFolder = workspace:FindFirstChild(\"NPC\") and workspace.NPC:FindFirstChild(\"Function\")\n                if not funcFolder then\n                    NexusLib:Notify({ Title = \"NPC Teleport\", Message = \"NPC.Function folder not found!\", Duration = 2 })\n                    return\n                end\n                \n                local targetModel = nil\n                for _, child in ipairs(funcFolder:GetDescendants()) do\n                    if typeof(child) == \"Instance\" and child:IsA(\"Model\") and child.Name == selectedNpc and child.Parent and typeof(child.Parent) == \"Instance\" and child.Parent:IsA(\"Folder\") then\n                        targetModel = child\n                        break\n                    end\n                end\n                \n                if not targetModel then\n                    NexusLib:Notify({ Title = \"NPC Teleport\", Message = \"NPC not found!\", Duration = 2 })\n                    return\n                end\n                \n                local hrp = targetModel:FindFirstChild(\"HumanoidRootPart\") or targetModel.PrimaryPart\n                if not hrp then\n                    hrp = targetModel:FindFirstChildWhichIsA(\"BasePart\")\n                end\n                if not hrp then\n                    NexusLib:Notify({ Title = \"NPC Teleport\", Message = \"Cannot find part to teleport to!\", Duration = 2 })\n                    return\n                end\n                \n                local myChar = LocalPlayer.Character\n                if not myChar then return end\n                local myHrp = myChar:FindFirstChild(\"HumanoidRootPart\")\n                if not myHrp then return end\n                \n                myHrp.CFrame = hrp.CFrame + Vector3.new(0, 3, 0)\n                \n                NexusLib:Notify({ Title = \"NPC Teleport\", Message = \"Teleported to \" .. selectedNpc, Duration = 2 })\n            end\n        })\n        -- ===== LEARN SKILL NPC =====\n        local selectedLearnNpc = \"Sage Yijiu\"\n        \n        -- Dropdown with a single option\n        local learnDropdown = Cfg.register(NpcSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Learn Skill NPC\", {\n            Name = \"Learn Skill NPC\",\n            Options = {\"Sage Yijiu\"},\n            Default = \"Sage Yijiu\",\n            Callback = function(value)\n                selectedLearnNpc = value\n            end\n        })), \"Dropdown\", \"Learn Skill NPC\", {\n            Name = \"Learn Skill NPC\",\n            Options = {\"Sage Yijiu\"},\n            Default = \"Sage Yijiu\",\n            Callback = function(value)\n                selectedLearnNpc = value\n            end\n        })\n        \n        -- Teleport to selected NPC button\n        NpcSection:CreateButton({\n            Name = \"Teleport to selected NPC\",\n            Callback = function()\n                local targetModel = workspace:FindFirstChild(\"NPC\") \n                    and workspace.NPC:FindFirstChild(\"LearnSkill\") \n                    and workspace.NPC.LearnSkill:FindFirstChild(\"Sage Yijiu\")\n                \n                if not targetModel then\n                    NexusLib:Notify({ Title = \"Learn Skill\", Message = \"Sage Yijiu not found!\", Duration = 2 })\n                    return\n                end\n                \n                local hrp = targetModel:FindFirstChild(\"HumanoidRootPart\") or targetModel.PrimaryPart\n                if not hrp then\n                    hrp = targetModel:FindFirstChildWhichIsA(\"BasePart\")\n                end\n                if not hrp then\n                    NexusLib:Notify({ Title = \"Learn Skill\", Message = \"Cannot find part to teleport to!\", Duration = 2 })\n                    return\n                end\n                \n                local myChar = LocalPlayer.Character\n                if not myChar then return end\n                local myHrp = myChar:FindFirstChild(\"HumanoidRootPart\")\n                if not myHrp then return end\n                \n                myHrp.CFrame = hrp.CFrame + Vector3.new(0, 3, 0)\n                \n                NexusLib:Notify({ Title = \"Learn Skill\", Message = \"Teleported to Sage Yijiu\", Duration = 2 })\n            end\n        })\n        -- ===== SECRET RODS SECTION =====\n        -- Secret Rod list (models parented to a Folder under workspace.SecretRod)\n        local function getSecretRodList()\n            local rods = {}\n            local secretRodFolder = workspace:FindFirstChild(\"SecretRod\")\n            if not secretRodFolder then return rods end\n            \n            for _, child in ipairs(secretRodFolder:GetDescendants()) do\n                if typeof(child) == \"Instance\" and child:IsA(\"Model\") and child.Parent and typeof(child.Parent) == \"Instance\" and child.Parent:IsA(\"Folder\") then\n                    table.insert(rods, child.Name)\n                end\n            end\n            return rods\n        end\n        \n        local rodList = getSecretRodList()\n        if #rodList == 0 then\n            table.insert(rodList, \"No Secret Rods found\")\n        end\n        \n        local selectedRod = rodList[1]\n        \n        -- Dropdown\n        local rodDropdown = NpcSection:CreateDropdown({\n            Name = \"Secret Rods\",\n            Options = rodList,\n            Default = selectedRod,\n            Callback = function(value)\n                selectedRod = value\n            end\n        })\n        \n        -- Teleport button\n        NpcSection:CreateButton({\n            Name = \"Teleport to selected Secret Rod\",\n            Callback = function()\n                if not selectedRod or selectedRod == \"No Secret Rods found\" then\n                    NexusLib:Notify({ Title = \"Secret Rod\", Message = \"No Secret Rod selected!\", Duration = 2 })\n                    return\n                end\n                \n                local secretRodFolder = workspace:FindFirstChild(\"SecretRod\")\n                if not secretRodFolder then\n                    NexusLib:Notify({ Title = \"Secret Rod\", Message = \"SecretRod folder not found!\", Duration = 2 })\n                    return\n                end\n                \n                local targetModel = nil\n                for _, child in ipairs(secretRodFolder:GetDescendants()) do\n                    if typeof(child) == \"Instance\" and child:IsA(\"Model\") and child.Name == selectedRod and child.Parent and typeof(child.Parent) == \"Instance\" and child.Parent:IsA(\"Folder\") then\n                        targetModel = child\n                        break\n                    end\n                end\n                \n                if not targetModel then\n                    NexusLib:Notify({ Title = \"Secret Rod\", Message = \"Secret Rod not found!\", Duration = 2 })\n                    return\n                end\n                \n                local hrp = targetModel:FindFirstChild(\"HumanoidRootPart\") or targetModel.PrimaryPart\n                if not hrp then\n                    hrp = targetModel:FindFirstChildWhichIsA(\"BasePart\")\n                end\n                if not hrp then\n                    NexusLib:Notify({ Title = \"Secret Rod\", Message = \"Cannot find part to teleport to!\", Duration = 2 })\n                    return\n                end\n                \n                local myChar = LocalPlayer.Character\n                if not myChar then return end\n                local myHrp = myChar:FindFirstChild(\"HumanoidRootPart\")\n                if not myHrp then return end\n                \n                myHrp.CFrame = hrp.CFrame + Vector3.new(0, 3, 0)\n                \n                NexusLib:Notify({ Title = \"Secret Rod\", Message = \"Teleported to \" .. selectedRod, Duration = 2 })\n            end\n        })\n    end\nend\n\n-- ============================================================\n-- ===== SETTINGS TAB =====\n-- ============================================================\ndo\n    local SettingsTab = Window:CreateTab(\"Settings\")\n\n    -- ===== CONFIG SECTION (save / load / auto-load / import-export) =====\n    do\n        local CfgUI = SettingsTab:CreateSection(\"Config\")\n        local Cfg = runtimeEnv.NexusConfig\n\n        CfgUI:CreateButton({\n            Name = \"Save Config\",\n            Callback = function() Cfg.save() end,\n        })\n\n        CfgUI:CreateButton({\n            Name = \"Load Config\",\n            Callback = function() Cfg.load() end,\n        })\n\n        CfgUI:CreateToggle({\n            Name = \"Auto Load Config\",\n            Default = false,\n            Callback = function(value)\n                if not (writefile and isfile) then\n                    NexusLib:Notify({ Title = \"Config\", Message = \"This executor cannot save files.\", Duration = 3 })\n                    return\n                end\n                if value then\n                    Cfg.save(Cfg.AUTO_FILE)\n                else\n                    pcall(function()\n                        if isfile(Cfg.AUTO_FILE) and delfile then delfile(Cfg.AUTO_FILE) end\n                    end)\n                end\n            end,\n        })\n\n        CfgUI:CreateButton({\n            Name = \"Export Config (Copy Code)\",\n            Callback = function() Cfg.exportCode() end,\n        })\n\n        local importBox = CfgUI:CreateTextbox({\n            Name = \"Import Config Code\",\n            Placeholder = \"Paste code, then press Import\",\n            Default = \"\",\n            Callback = function() end,\n        })\n\n        CfgUI:CreateButton({\n            Name = \"Import Config\",\n            Callback = function()\n                local code = \"\"\n                pcall(function() code = importBox.Get() end)\n                Cfg.importCode(code)\n            end,\n        })\n    end\n    local CharSection = SettingsTab:CreateSection(\"Character\")\n\n    Cfg.register(CharSection:CreateTextbox(Cfg.wrap(\"Textbox\", \"Walk Speed\", { Name = \"Walk Speed\", Placeholder = \"16\", Default = \"16\", Callback = function(V)\n        pcall(function() LocalPlayer.Character.Humanoid.WalkSpeed = tonumber(V) or 16 end)\n    end })), \"Textbox\", \"Walk Speed\", { Name = \"Walk Speed\", Placeholder = \"16\", Default = \"16\", Callback = function(V)\n        pcall(function() LocalPlayer.Character.Humanoid.WalkSpeed = tonumber(V) or 16 end)\n    end })\n\n    local function startFly()\n        local c = LocalPlayer.Character\n        if not c or not c:FindFirstChild(\"HumanoidRootPart\") then return end\n        if NexusState.flying then return end\n        if NexusState.bg then NexusState.bg:Destroy() end\n        if NexusState.bv then NexusState.bv:Destroy() end\n        local h = c.HumanoidRootPart\n        NexusState.bg = Instance.new(\"BodyGyro\", h)\n        NexusState.bg.P = 9e4\n        NexusState.bg.maxTorque = Vector3.new(9e9,9e9,9e9)\n        NexusState.bg.cframe = h.CFrame\n        NexusState.bv = Instance.new(\"BodyVelocity\", h)\n        NexusState.bv.velocity = Vector3.new(0,0,0)\n        NexusState.bv.maxForce = Vector3.new(9e9,9e9,9e9)\n        NexusState.flying = true\n        local humanoid = c:FindFirstChildOfClass(\"Humanoid\")\n        if humanoid then humanoid.PlatformStand = true end\n        if NexusState.flyInputConnection then NexusState.flyInputConnection:Disconnect() end\n        if NexusState.flyInputEndConnection then NexusState.flyInputEndConnection:Disconnect() end\n        NexusState.flyInputConnection = UserInputService.InputBegan:Connect(function(input, gameProcessed)\n            if gameProcessed then return end\n            if input.KeyCode == Enum.KeyCode.Space then NexusState.flyKeys.Up = true end\n            if input.KeyCode == Enum.KeyCode.LeftControl then NexusState.flyKeys.Down = true end\n        end)\n        NexusState.flyInputEndConnection = UserInputService.InputEnded:Connect(function(input)\n            if input.KeyCode == Enum.KeyCode.Space then NexusState.flyKeys.Up = false end\n            if input.KeyCode == Enum.KeyCode.LeftControl then NexusState.flyKeys.Down = false end\n        end)\n    end\n\n    local function stopFly()\n        NexusState.flying = false\n        NexusState.flyKeys.Up, NexusState.flyKeys.Down = false, false\n        if NexusState.flyInputConnection then NexusState.flyInputConnection:Disconnect(); NexusState.flyInputConnection = nil end\n        if NexusState.flyInputEndConnection then NexusState.flyInputEndConnection:Disconnect(); NexusState.flyInputEndConnection = nil end\n        if NexusState.bg then NexusState.bg:Destroy(); NexusState.bg = nil end\n        if NexusState.bv then NexusState.bv:Destroy(); NexusState.bv = nil end\n        local c = LocalPlayer.Character\n        if c then\n            local humanoid = c:FindFirstChildOfClass(\"Humanoid\")\n            if humanoid then humanoid.PlatformStand = false end\n        end\n    end\n\n    Cfg.register(CharSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Fly Mode\", { Name = \"Fly Mode\", Default = false, Callback = function(V)\n        MiscFlags.FlyMode = V\n        if V then startFly() else stopFly() end\n    end })), \"Toggle\", \"Fly Mode\", { Name = \"Fly Mode\", Default = false, Callback = function(V)\n        MiscFlags.FlyMode = V\n        if V then startFly() else stopFly() end\n    end })\n    Cfg.register(CharSection:CreateTextbox(Cfg.wrap(\"Textbox\", \"Fly Speed\", { Name = \"Fly Speed\", Placeholder = \"50\", Default = \"50\", Callback = function(V)\n        NexusState.flySpeed = tonumber(V) or 50\n    end })), \"Textbox\", \"Fly Speed\", { Name = \"Fly Speed\", Placeholder = \"50\", Default = \"50\", Callback = function(V)\n        NexusState.flySpeed = tonumber(V) or 50\n    end })\n    Cfg.register(CharSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Noclip\", { Name = \"Noclip\", Default = false, Callback = function(V) MiscFlags.Noclip = V end })), \"Toggle\", \"Noclip\", { Name = \"Noclip\", Default = false, Callback = function(V) MiscFlags.Noclip = V end })\n    Cfg.register(CharSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Infinite Jump\", { Name = \"Infinite Jump\", Default = false, Callback = function(V) MiscFlags.InfiniteJump = V end })), \"Toggle\", \"Infinite Jump\", { Name = \"Infinite Jump\", Default = false, Callback = function(V) MiscFlags.InfiniteJump = V end })\n\n    local function findWaterParts()\n        local parts = {}\n        for _, v in pairs(Workspace:GetDescendants()) do\n            if typeof(v) == \"Instance\" and typeof(v) == \"Instance\" and v:IsA(\"BasePart\") then\n                local name = v.Name:lower()\n                if name:match(\"water\") or name:match(\"ocean\") or v.Material == Enum.Material.Water then\n                    table.insert(parts, v)\n                end\n            end\n        end\n        return parts\n    end\n\n    local function enableWaterWalk()\n        if NexusState.waterWalkEnabled then return end\n        NexusState.waterWalkEnabled = true\n        NexusState.waterPartsList = findWaterParts()\n        for _, part in ipairs(NexusState.waterPartsList) do part.CanCollide = true end\n        NexusState.waterPart = Instance.new(\"Part\")\n        NexusState.waterPart.Size = Vector3.new(16, 1, 16)\n        NexusState.waterPart.Transparency = 1\n        NexusState.waterPart.Anchored = true\n        NexusState.waterPart.CanCollide = true\n        NexusState.waterPart.Name = \"WaterWalkPart\"\n        NexusState.waterPart.Parent = Workspace\n        local char = LocalPlayer.Character\n        if char and char:FindFirstChild(\"HumanoidRootPart\") then\n            NexusState.waterY = char.HumanoidRootPart.Position.Y - 3.2\n        else\n            NexusState.waterY = 0\n        end\n        if NexusState.waterWalkConnection then NexusState.waterWalkConnection:Disconnect() end\n        NexusState.waterWalkConnection = RunService.RenderStepped:Connect(function()\n            if not NexusState.waterWalkEnabled then return end\n            local char = LocalPlayer.Character\n            if not char then return end\n            local root = char:FindFirstChild(\"HumanoidRootPart\")\n            if not root then return end\n            if NexusState.waterPart then\n                NexusState.waterPart.Position = Vector3.new(root.Position.X, NexusState.waterY, root.Position.Z)\n            end\n        end)\n    end\n\n    local function disableWaterWalk()\n        if not NexusState.waterWalkEnabled then return end\n        NexusState.waterWalkEnabled = false\n        if NexusState.waterWalkConnection then\n            NexusState.waterWalkConnection:Disconnect()\n            NexusState.waterWalkConnection = nil\n        end\n        if NexusState.waterPart then\n            NexusState.waterPart:Destroy()\n            NexusState.waterPart = nil\n        end\n        for _, part in ipairs(NexusState.waterPartsList) do\n            if part and part.Parent then\n                part.CanCollide = false\n            end\n        end\n        NexusState.waterPartsList = {}\n    end\n\n    Cfg.register(CharSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Walk On Water\", {\n        Name = \"Walk On Water\",\n        Default = false,\n        Callback = function(V)\n            MiscFlags.WalkOnWater = V\n            if V then enableWaterWalk() else disableWaterWalk() end\n        end\n    })), \"Toggle\", \"Walk On Water\", {\n        Name = \"Walk On Water\",\n        Default = false,\n        Callback = function(V)\n            MiscFlags.WalkOnWater = V\n            if V then enableWaterWalk() else disableWaterWalk() end\n        end\n    })\n\n    -- World & Misc\n    do\n        local WorldSection = SettingsTab:CreateSection(\"World & Misc\")\n        local origA, origB, origT, origBr, origOA = Lighting.Ambient, Lighting.ColorShift_Bottom, Lighting.ColorShift_Top, Lighting.Brightness, Lighting.OutdoorAmbient\n        Cfg.register(WorldSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Full Bright\", {\n            Name = \"Full Bright\",\n            Default = false,\n            Callback = function(V)\n                MiscFlags.FullBright = V\n                if not V then\n                    Lighting.Ambient = origA\n                    Lighting.ColorShift_Bottom = origB\n                    Lighting.ColorShift_Top = origT\n                    Lighting.Brightness = origBr\n                    Lighting.OutdoorAmbient = origOA\n                end\n            end\n        })), \"Toggle\", \"Full Bright\", {\n            Name = \"Full Bright\",\n            Default = false,\n            Callback = function(V)\n                MiscFlags.FullBright = V\n                if not V then\n                    Lighting.Ambient = origA\n                    Lighting.ColorShift_Bottom = origB\n                    Lighting.ColorShift_Top = origT\n                    Lighting.Brightness = origBr\n                    Lighting.OutdoorAmbient = origOA\n                end\n            end\n        })\n\n        WorldSection:CreateButton({\n            Name = \"Redeem All Codes\",\n            Callback = function()\n                task.spawn(function()\n                    for _, code in ipairs(CODES) do\n                        pcall(function() Events.RedeemCode:FireServer(code) end)\n                        task.wait(0.3)\n                    end\n                    NexusLib:Notify({ Title = \"Codes\", Message = \"All codes redeemed!\", Duration = 3 })\n                end)\n            end\n        })\n\n        WorldSection:CreateButton({\n            Name = \"Performance Mod\",\n            Callback = function()\n                pcall(function() settings().Rendering.QualityLevel = Enum.QualityLevel.Level01 end)\n                local t = Workspace:FindFirstChildOfClass(\"Terrain\")\n                if t then\n                    t.WaterWaveSize = 0\n                    t.WaterWaveSpeed = 0\n                    t.WaterReflectance = 0\n                    t.WaterTransparency = 1\n                end\n                Lighting.GlobalShadows = false\n                Lighting.FogEnd = 9e9\n                Lighting.ShadowSoftness = 0\n                Lighting.EnvironmentDiffuseScale = 0\n                Lighting.EnvironmentSpecularScale = 0\n                for _, v in pairs(Lighting:GetChildren()) do\n                    if typeof(v) == \"Instance\" and (v:IsA(\"BlurEffect\") or v:IsA(\"SunRaysEffect\") or v:IsA(\"ColorCorrectionEffect\") or v:IsA(\"BloomEffect\") or v:IsA(\"DepthOfFieldEffect\")) then\n                        v:Destroy()\n                    end\n                end\n                for _, v in pairs(Workspace:GetDescendants()) do\n                    if typeof(v) == \"Instance\" then\n                        if typeof(v) == \"Instance\" and typeof(v) == \"Instance\" and v:IsA(\"BasePart\") then\n                            v.Material = Enum.Material.SmoothPlastic\n                            v.Reflectance = 0\n                            v.CastShadow = false\n                        elseif typeof(v) == \"Instance\" and typeof(v) == \"Instance\" and v:IsA(\"Decal\") or v:IsA(\"Texture\") or v:IsA(\"ParticleEmitter\") or v:IsA(\"Trail\") or v:IsA(\"Fire\") or v:IsA(\"Smoke\") or v:IsA(\"Sparkles\") then\n                            v:Destroy()\n                        end\n                    end\n                end\n                NexusLib:Notify({ Title = \"Performance\", Message = \"Optimized Game!\", Duration = 3 })\n            end\n        })\n        Cfg.register(WorldSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Enable Notifications\", {\n            Name = \"Enable Notifications\",\n            Default = true,\n            Callback = function(value)\n                NexusState.notificationsEnabled = value\n                NexusLib:Notify({\n                    Title = \"Notifications\",\n                    Message = value and \"Enabled\" or \"Disabled\",\n                    Duration = 2\n                })\n            end\n        })), \"Toggle\", \"Enable Notifications\", {\n            Name = \"Enable Notifications\",\n            Default = true,\n            Callback = function(value)\n                NexusState.notificationsEnabled = value\n                NexusLib:Notify({\n                    Title = \"Notifications\",\n                    Message = value and \"Enabled\" or \"Disabled\",\n                    Duration = 2\n                })\n            end\n        })\n    end\n\n\n        local HopSection = SettingsTab:CreateSection(\"Server Hop\")\n        NexusState.maxServerPlayers = NexusState.maxServerPlayers or 4\n        NexusState.hopCooldownAt = NexusState.hopCooldownAt or 0\n\n        local function fetchServers(cursor)\n            local reqFn = (syn and syn.request) or http_request or request or (http and http.request) or (fluxus and fluxus.request)\n            if type(reqFn) ~= \"function\" then return nil end\n            local url = string.format(\"https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Asc&limit=100\", game.PlaceId)\n            if cursor and cursor ~= \"\" then url = url .. \"&cursor=\" .. cursor end\n            local ok, res = pcall(reqFn, { Url = url, Method = \"GET\" })\n            if not ok or not res then return nil end\n            local body = res.Body or res.body\n            if type(body) ~= \"string\" or body == \"\" then return nil end\n            local ok2, data = pcall(function() return Services.HttpService:JSONDecode(body) end)\n            if not ok2 or type(data) ~= \"table\" then return nil end\n            return data\n        end\n\n        local function findLowServer(maxPlayers)\n            local cursor = \"\"\n            for _ = 1, 5 do\n                local data = fetchServers(cursor)\n                if not data or not data.data then return nil end\n                for _, srv in ipairs(data.data) do\n                    local playing = tonumber(srv.playing) or 999\n                    local maxP = tonumber(srv.maxPlayers) or 0\n                    if srv.id and srv.id ~= game.JobId and playing < maxP and playing <= maxPlayers then\n                        return srv.id, playing, maxP\n                    end\n                end\n                cursor = data.nextPageCursor\n                if not cursor or cursor == \"\" then break end\n            end\n            return nil\n        end\n\n\n        Cfg.register(HopSection:CreateTextbox(Cfg.wrap(\"Textbox\", \"Max Players\", {\n            Name = \"Max Players\",\n            Placeholder = \"4\",\n            Default = tostring(NexusState.maxServerPlayers or 4),\n            Callback = function(text)\n                local n = tonumber(text)\n                if n and n >= 1 and n <= 50 then\n                    NexusState.maxServerPlayers = math.floor(n)\n                else\n                    NexusLib:Notify({ Title = \"Server Hop\", Message = \"Enter a number 1-50.\", Duration = 3 })\n                end\n            end\n        })), \"Textbox\", \"Max Players\", {\n            Name = \"Max Players\",\n            Placeholder = \"4\",\n            Default = tostring(NexusState.maxServerPlayers or 4),\n            Callback = function(text)\n                local n = tonumber(text)\n                if n and n >= 1 and n <= 50 then\n                    NexusState.maxServerPlayers = math.floor(n)\n                else\n                    NexusLib:Notify({ Title = \"Server Hop\", Message = \"Enter a number 1-50.\", Duration = 3 })\n                end\n            end\n        })\n\n        Cfg.register(HopSection:CreateButton(Cfg.wrap(\"Button\", \"Hop to Low Player Server\", {\n            Name = \"Join\",\n            Callback = function()\n                if tick() - (NexusState.hopCooldownAt or 0) < 30 then\n                    NexusLib:Notify({ Title = \"Server Hop\", Message = \"Hop cooldown, try again shortly.\", Duration = 3 })\n                    return\n                end\n                NexusLib:Notify({ Title = \"Server Hop\", Message = \"Searching low player server...\", Duration = 3 })\n                task.spawn(function()\n                    local maxP = NexusState.maxServerPlayers or 4\n                    local jobId, playing = findLowServer(maxP)\n                    if jobId then\n                        NexusState.hopCooldownAt = tick()\n                        NexusLib:Notify({ Title = \"Server Hop\", Message = string.format(\"Joining server (%d/%d)...\", playing, maxP), Duration = 3 })\n                        pcall(function()\n                            Services.TeleportService:TeleportToPlaceInstance(game.PlaceId, jobId, LocalPlayer)\n                        end)\n                    else\n                        NexusLib:Notify({ Title = \"Server Hop\", Message = \"No low player server found, try again.\", Duration = 3 })\n                    end\n                end)\n            end\n        })), \"Button\", \"Hop to Low Player Server\", nil)\n\n    -- ===== STREAMER MODE (FAKE NAME) & LANGUAGE & NEXUS SHIELD =====\n    do\n        local StreamerSection = SettingsTab:CreateSection(\"Streamer Mode (Fake Name)\")\n        Cfg.register(StreamerSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Fake Name Display\", {\n            Name = \"Fake Name Display\",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    NexusState.enableFakeName()\n                else\n                    NexusState.disableFakeName()\n                end\n            end\n        })), \"Toggle\", \"Fake Name Display\", {\n            Name = \"Fake Name Display\",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    NexusState.enableFakeName()\n                else\n                    NexusState.disableFakeName()\n                end\n            end\n        })\n\n        Cfg.register(StreamerSection:CreateTextbox(Cfg.wrap(\"Textbox\", \"Fake Username\", {\n            Name = \"Fake Username\",\n            Placeholder = \"NexusPlayer\",\n            Default = NexusState.fakeName or \"NexusPlayer\",\n            Callback = function(value)\n                if value and #value > 0 then\n                    NexusState.fakeName = value\n                end\n            end\n        })), \"Textbox\", \"Fake Username\", {\n            Name = \"Fake Username\",\n            Placeholder = \"NexusPlayer\",\n            Default = NexusState.fakeName or \"NexusPlayer\",\n            Callback = function(value)\n                if value and #value > 0 then\n                    NexusState.fakeName = value\n                end\n            end\n        })\n\n        Cfg.register(StreamerSection:CreateTextbox(Cfg.wrap(\"Textbox\", \"Fake Display Name\", {\n            Name = \"Fake Display Name\",\n            Placeholder = \"NexusPlayer\",\n            Default = NexusState.fakeDisplayName or \"NexusPlayer\",\n            Callback = function(value)\n                if value and #value > 0 then\n                    NexusState.fakeDisplayName = value\n                end\n            end\n        })), \"Textbox\", \"Fake Display Name\", {\n            Name = \"Fake Display Name\",\n            Placeholder = \"NexusPlayer\",\n            Default = NexusState.fakeDisplayName or \"NexusPlayer\",\n            Callback = function(value)\n                if value and #value > 0 then\n                    NexusState.fakeDisplayName = value\n                end\n            end\n        })\n\n        -- Doi ten ma khong che ID thi van bi report -> them o nhap UserId gia.\n        -- PlaceId va JobId duoc che tu dong (khong can nhap).\n        Cfg.register(StreamerSection:CreateTextbox(Cfg.wrap(\"Textbox\", \"Fake User ID\", {\n            Name = \"Fake User ID\",\n            Placeholder = \"0\",\n            Default = NexusState.fakeUserId or \"0\",\n            Callback = function(value)\n                if value and #tostring(value) > 0 then\n                    NexusState.fakeUserId = tostring(value)\n                end\n            end\n        })), \"Textbox\", \"Fake User ID\", {\n            Name = \"Fake User ID\",\n            Placeholder = \"0\",\n            Default = NexusState.fakeUserId or \"0\",\n            Callback = function(value)\n                if value and #tostring(value) > 0 then\n                    NexusState.fakeUserId = tostring(value)\n                end\n            end\n        })\n\n        -- Guild display: nhap ten guild that -> se doi sang fake guild de khong bi ban\n                Cfg.register(StreamerSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Fake ID Mode\", {\n            Name = \"Fake ID Mode\",\n            Options = {\"1 - Fake Number\", \"2 - Hide ID\"},\n            Default = \"1 - Fake Number\",\n            Callback = function(value)\n                if value and string.find(tostring(value), \"^2\") then\n                    NexusState.fakeIdMode = 2\n                else\n                    NexusState.fakeIdMode = 1\n                end\n            end\n        })), \"Dropdown\", \"Fake ID Mode\", {\n            Name = \"Fake ID Mode\",\n            Options = {\"1 - Fake Number\", \"2 - Hide ID\"},\n            Default = \"1 - Fake Number\",\n            Callback = function(value)\n                if value and string.find(tostring(value), \"^2\") then\n                    NexusState.fakeIdMode = 2\n                else\n                    NexusState.fakeIdMode = 1\n                end\n            end\n        })\nCfg.register(StreamerSection:CreateTextbox(Cfg.wrap(\"Textbox\", \"Real Guild Name (Optional)\", {\n            Name = \"Real Guild Name (Optional)\",\n            Placeholder = \"Current guild name\",\n            Default = NexusState.realGuildName or \"\",\n            Callback = function(value)\n                if value then\n                    NexusState.realGuildName = tostring(value):gsub(\"^%s+\", \"\"):gsub(\"%s+$\", \"\")\n                    if #(NexusState.realGuildName or \"\") > 0 then\n                        NexusState.enableFakeName()\n                    end\n                end\n            end\n        })), \"Textbox\", \"Real Guild Name (Optional)\", {\n            Name = \"Real Guild Name (Optional)\",\n            Placeholder = \"Current guild name\",\n            Default = NexusState.realGuildName or \"\",\n            Callback = function(value)\n                if value then\n                    NexusState.realGuildName = tostring(value):gsub(\"^%s+\", \"\"):gsub(\"%s+$\", \"\")\n                    if #(NexusState.realGuildName or \"\") > 0 then\n                        NexusState.enableFakeName()\n                    end\n                end\n            end\n        })\n\n\n        local LangSection = SettingsTab:CreateSection(\"Language & Localization\")\n        local langOptions = {\"Auto (Roblox Locale)\", \"English\", \"Espanol\", \"Portugues\", \"Thai\", \"Bahasa Indonesia\"}\n        local langMap = {\n            [\"Auto (Roblox Locale)\"] = \"auto\",\n            [\"English\"] = \"en\",\n            [\"Espanol\"] = \"es\",\n            [\"Portugues\"] = \"pt\",\n            [\"Thai\"] = \"th\",\n            [\"Bahasa Indonesia\"] = \"id\"\n        }\n        Cfg.register(LangSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"UI Language\", {\n            Name = \"UI Language\",\n            Options = langOptions,\n            Default = \"Auto (Roblox Locale)\",\n            Callback = function(value)\n                NexusState.currentLanguage = langMap[value] or \"auto\"\n                pcall(function()\n                    if I18n and I18n.applyLanguage then\n                        I18n.applyLanguage()\n                    end\n                end)\n                NexusLib:Notify({\n                    Title = \"Language\",\n                    Message = \"Language set to: \" .. tostring(value),\n                    Duration = 2\n                })\n            end\n        })), \"Dropdown\", \"UI Language\", {\n            Name = \"UI Language\",\n            Options = langOptions,\n            Default = \"Auto (Roblox Locale)\",\n            Callback = function(value)\n                NexusState.currentLanguage = langMap[value] or \"auto\"\n                pcall(function()\n                    if I18n and I18n.applyLanguage then\n                        I18n.applyLanguage()\n                    end\n                end)\n                NexusLib:Notify({\n                    Title = \"Language\",\n                    Message = \"Language set to: \" .. tostring(value),\n                    Duration = 2\n                })\n            end\n        })\n\n        local ShieldSection = SettingsTab:CreateSection(\"Nexus Shield\")\n        -- AN TOAN: Nexus Shield bat vinh vien, user KHONG TAT DUOC.\n        NexusState.antiReportEnabled = true\n        Cfg.register(ShieldSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Anti-Report Nexus Users\", {\n            Name = \"Anti-Report Nexus Users\",\n            Default = true,\n            Callback = function(value)\n                -- Bao ve: bat an toan -> neu user thu tat thi bao + luon bat lai\n                NexusState.antiReportEnabled = true\n                NexusLib:Notify({\n                    Title = \"Nexus Shield\",\n                    Message = \"An toan: Nexus Shield luon bat, khong the tat!\",\n                    Duration = 3\n                })\n            end\n        })), \"Toggle\", \"Anti-Report Nexus Users\", {\n            Name = \"Anti-Report Nexus Users\",\n            Default = true,\n            Callback = function(value)\n                -- Bao ve: bat an toan -> neu user thu tat thi bao + luon bat lai\n                NexusState.antiReportEnabled = true\n                NexusLib:Notify({\n                    Title = \"Nexus Shield\",\n                    Message = \"An toan: Nexus Shield luon bat, khong the tat!\",\n                    Duration = 3\n                })\n            end\n        })\n    end\n\n    -- ===== ESP SECTION =====\n    do\n        local EspSection = SettingsTab:CreateSection(\"ESP\")\n        \n        -- ===== ESP PLAYERS =====\n        local espEnabled = false\n        local espThread = nil\n        local espConnections = {}\n        local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n        \n        local function getPlayerStats(player)\n            local stats = {\n                Level = \"N/A\",\n                Cash = \"N/A\",\n                Rod = \"N/A\",\n                Crystal = \"N/A\",\n                EssenceOrb = \"N/A\",\n                Bait = \"N/A\",\n                FishCaught = \"N/A\",\n                Ticket = \"N/A\",\n                TraitReroll = \"N/A\"\n            }\n            local dataFolder = ReplicatedStorage:FindFirstChild(\"Data\")\n            if not dataFolder then return stats end\n            local playerData = dataFolder:FindFirstChild(tostring(player.UserId))\n            if not playerData then return stats end\n            \n            local levelFolder = playerData:FindFirstChild(\"Level\")\n            if levelFolder then\n                local levelVal = levelFolder:FindFirstChild(\"Level\")\n                if levelVal then stats.Level = tostring(levelVal.Value) end\n            end\n            local cashVal = playerData:FindFirstChild(\"Cash\")\n            if cashVal then stats.Cash = tostring(cashVal.Value) end\n            local rodVal = playerData:FindFirstChild(\"FishingRod\")\n            if rodVal then stats.Rod = tostring(rodVal.Value) end\n            local crystalVal = playerData:FindFirstChild(\"Crystal\")\n            if crystalVal then stats.Crystal = tostring(crystalVal.Value) end\n            local essenceVal = playerData:FindFirstChild(\"EssenceOrb\")\n            if essenceVal then stats.EssenceOrb = tostring(essenceVal.Value) end\n            local baitVal = playerData:FindFirstChild(\"EquippedBait\")\n            if baitVal then stats.Bait = tostring(baitVal.Value) end\n            local fishCaughtVal = playerData:FindFirstChild(\"FishCaught\")\n            if fishCaughtVal then stats.FishCaught = tostring(fishCaughtVal.Value) end\n            local ticketVal = playerData:FindFirstChild(\"Ticket\")\n            if ticketVal then stats.Ticket = tostring(ticketVal.Value) end\n            local traitRerollVal = playerData:FindFirstChild(\"Trait Reroll\")\n            if traitRerollVal then stats.TraitReroll = tostring(traitRerollVal.Value) end\n            return stats\n        end\n        \n        local function createEspForPlayer(player)\n            if player == LocalPlayer then return end\n            local character = player.Character\n            if not character then return end\n            local head = character:FindFirstChild(\"Head\")\n            if not head then return end\n            if head:FindFirstChild(\"EspBillboard\") then return end\n            \n            local stats = getPlayerStats(player)\n            local billboard = Instance.new(\"BillboardGui\")\n            billboard.Name = \"EspBillboard\"\n            billboard.Size = UDim2.new(0, 300, 0, 110)\n            billboard.StudsOffset = Vector3.new(0, 3, 0)\n            billboard.AlwaysOnTop = true\n            billboard.Parent = head\n            \n            local frame = Instance.new(\"Frame\")\n            frame.Size = UDim2.new(1, 0, 1, 0)\n            frame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)\n            frame.BackgroundTransparency = 0.6\n            frame.BorderSizePixel = 0\n            frame.Parent = billboard\n            \n            local corner = Instance.new(\"UICorner\")\n            corner.CornerRadius = UDim.new(0, 4)\n            corner.Parent = frame\n            \n            local nameLabel = Instance.new(\"TextLabel\")\n            nameLabel.Size = UDim2.new(1, 0, 0, 18)\n            nameLabel.Position = UDim2.new(0, 0, 0, 0)\n            nameLabel.BackgroundTransparency = 1\n            nameLabel.Font = Enum.Font.GothamBold\n            nameLabel.TextSize = 16\n            nameLabel.TextColor3 = Color3.fromRGB(255, 255, 255)\n            nameLabel.Text = player.Name\n            nameLabel.TextXAlignment = Enum.TextXAlignment.Center\n            nameLabel.Parent = frame\n            \n            local lines = {\n                string.format(\"Lv:%s | Cash:%s\", stats.Level, stats.Cash),\n                string.format(\"Rod:%s\", stats.Rod),\n                string.format(\"Bait:%s\", stats.Bait),\n                string.format(\"Cry:%s | Ess:%s | Tick:%s | Reroll:%s\", stats.Crystal, stats.EssenceOrb, stats.Ticket, stats.TraitReroll),\n                string.format(\"Fish:%s\", stats.FishCaught)\n            }\n            \n            local yOffset = 18\n            for _, line in ipairs(lines) do\n                local label = Instance.new(\"TextLabel\")\n                label.Size = UDim2.new(1, 0, 0, 16)\n                label.Position = UDim2.new(0, 0, 0, yOffset)\n                label.BackgroundTransparency = 1\n                label.Font = Enum.Font.Gotham\n                label.TextSize = 12\n                label.TextColor3 = Color3.fromRGB(200, 200, 200)\n                label.Text = line\n                label.TextXAlignment = Enum.TextXAlignment.Center\n                label.Parent = frame\n                yOffset = yOffset + 16\n            end\n            \n            table.insert(espConnections, { player = player, billboard = billboard })\n        end\n        \n        local function removeEspForPlayer(player)\n            local character = player.Character\n            if not character then return end\n            local head = character:FindFirstChild(\"Head\")\n            if not head then return end\n            local billboard = head:FindFirstChild(\"EspBillboard\")\n            if billboard then billboard:Destroy() end\n            for i, conn in ipairs(espConnections) do\n                if conn.player == player then\n                    table.remove(espConnections, i)\n                    break\n                end\n            end\n        end\n        \n        local function clearAllEsp()\n            for _, conn in ipairs(espConnections) do\n                pcall(function()\n                    if conn.billboard and conn.billboard.Parent then\n                        conn.billboard:Destroy()\n                    end\n                end)\n            end\n            espConnections = {}\n        end\n        \n        local function updateAllEsp()\n            if not espEnabled then return end\n            clearAllEsp()\n            for _, player in ipairs(Players:GetPlayers()) do\n                if player ~= LocalPlayer then\n                    pcall(function() createEspForPlayer(player) end)\n                end\n            end\n        end\n        \n        local function startEsp()\n            if espEnabled then return end\n            espEnabled = true\n            updateAllEsp()\n            \n            local playerAddedConn = Players.PlayerAdded:Connect(function(player)\n                if espEnabled then\n                    task.wait(0.5)\n                    pcall(function() createEspForPlayer(player) end)\n                end\n            end)\n            table.insert(espConnections, { conn = playerAddedConn })\n            \n            local playerRemovingConn = Players.PlayerRemoving:Connect(function(player)\n                pcall(function() removeEspForPlayer(player) end)\n            end)\n            table.insert(espConnections, { conn = playerRemovingConn })\n            \n            local characterAddedConn = Players.PlayerAdded:Connect(function(player)\n                if espEnabled then\n                    player.CharacterAdded:Connect(function()\n                        task.wait(0.5)\n                        pcall(function() createEspForPlayer(player) end)\n                    end)\n                end\n            end)\n            table.insert(espConnections, { conn = characterAddedConn })\n            \n            espThread = task.spawn(function()\n                while espEnabled do\n                    task.wait(10)\n                    if espEnabled then\n                        pcall(updateAllEsp)\n                    end\n                end\n            end)\n            \n            NexusLib:Notify({ Title = \"ESP\", Message = \"Players ESP enabled!\", Duration = 2 })\n        end\n        \n        local function stopEsp()\n            espEnabled = false\n            if espThread then\n                task.cancel(espThread)\n                espThread = nil\n            end\n            clearAllEsp()\n            for _, conn in ipairs(espConnections) do\n                if conn.conn then\n                    pcall(function() conn.conn:Disconnect() end)\n                end\n            end\n            espConnections = {}\n            NexusLib:Notify({ Title = \"ESP\", Message = \"Players ESP disabled!\", Duration = 2 })\n        end\n        \n        Cfg.register(EspSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Players\", {\n            Name = \"Players\",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    startEsp()\n                else\n                    stopEsp()\n                end\n            end\n        })), \"Toggle\", \"Players\", {\n            Name = \"Players\",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    startEsp()\n                else\n                    stopEsp()\n                end\n            end\n        })\n        \n        -- ===== BOAT ESP =====\n        do\n            local boatEspEnabled = false\n            local boatEspThread = nil\n            local boatEspHighlights = {}\n            local boatFolder = workspace:FindFirstChild(\"Boat\")\n            \n            local function createBoatEsp(boatModel)\n                if not boatModel or typeof(boatModel) ~= \"Instance\" or not boatModel:IsA(\"Model\") then return end\n                if boatEspHighlights[boatModel] then return end\n                \n                -- Only handle it when the parent is a Folder\n                if not boatModel.Parent or typeof(boatModel.Parent) ~= \"Instance\" or not boatModel.Parent:IsA(\"Folder\") then return end\n                \n                local attachPart = boatModel:FindFirstChildWhichIsA(\"BasePart\")\n                if not attachPart then\n                    attachPart = boatModel:FindFirstChildWhichIsA(\"BasePart\", true)\n                end\n                if not attachPart then return end\n                \n                local parentName = \"Boat\"\n                local parent = boatModel.Parent\n                if parent and parent ~= boatFolder then\n                    parentName = parent.Name\n                end\n                \n                local highlight = Instance.new(\"Highlight\")\n                highlight.FillColor = Color3.fromRGB(0, 150, 255)\n                highlight.FillTransparency = 0.5\n                highlight.OutlineColor = Color3.fromRGB(0, 255, 255)\n                highlight.OutlineTransparency = 0.3\n                highlight.Adornee = boatModel\n                highlight.Parent = boatModel\n                \n                local billboard = Instance.new(\"BillboardGui\")\n                billboard.Name = \"BoatEspBillboard\"\n                billboard.Size = UDim2.new(0, 150, 0, 30)\n                billboard.StudsOffset = Vector3.new(0, 2, 0)\n                billboard.AlwaysOnTop = true\n                billboard.Parent = attachPart\n                \n                local frame = Instance.new(\"Frame\")\n                frame.Size = UDim2.new(1, 0, 1, 0)\n                frame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)\n                frame.BackgroundTransparency = 0.5\n                frame.BorderSizePixel = 0\n                frame.Parent = billboard\n                \n                local corner = Instance.new(\"UICorner\")\n                corner.CornerRadius = UDim.new(0, 4)\n                corner.Parent = frame\n                \n                local label = Instance.new(\"TextLabel\")\n                label.Size = UDim2.new(1, 0, 1, 0)\n                label.BackgroundTransparency = 1\n                label.Font = Enum.Font.GothamBold\n                label.TextSize = 14\n                label.TextColor3 = Color3.fromRGB(0, 0, 255)\n                label.Text = \"Boat | \" .. parentName\n                label.TextScaled = false\n                label.TextXAlignment = Enum.TextXAlignment.Center\n                label.TextYAlignment = Enum.TextYAlignment.Center\n                label.Parent = frame\n                \n                boatEspHighlights[boatModel] = {\n                    highlight = highlight,\n                    billboard = billboard,\n                    attachPart = attachPart,\n                }\n            end\n            \n            local function removeBoatEsp(boatModel)\n                local data = boatEspHighlights[boatModel]\n                if data then\n                    if data.highlight then data.highlight:Destroy() end\n                    if data.billboard then data.billboard:Destroy() end\n                    boatEspHighlights[boatModel] = nil\n                end\n            end\n            \n            local function clearAllBoatEsp()\n                for model, data in pairs(boatEspHighlights) do\n                    pcall(function()\n                        if data.highlight then data.highlight:Destroy() end\n                        if data.billboard then data.billboard:Destroy() end\n                    end)\n                end\n                boatEspHighlights = {}\n            end\n            \n            local function scanAllBoats()\n                if not boatFolder then return end\n                for _, child in ipairs(boatFolder:GetDescendants()) do\n                    if typeof(child) == \"Instance\" and child:IsA(\"Model\") and child.Parent and typeof(child.Parent) == \"Instance\" and child.Parent:IsA(\"Folder\") then\n                        if not boatEspHighlights[child] then\n                            pcall(function() createBoatEsp(child) end)\n                        end\n                    end\n                end\n            end\n            \n            local function startBoatEsp()\n                if boatEspEnabled then return end\n                boatEspEnabled = true\n                scanAllBoats()\n                \n                if boatFolder then\n                    local boatAddedConn = boatFolder.DescendantAdded:Connect(function(desc)\n                        if boatEspEnabled and typeof(desc) == \"Instance\" and desc:IsA(\"Model\") and desc.Parent and typeof(desc.Parent) == \"Instance\" and desc.Parent:IsA(\"Folder\") then\n                            task.wait(0.1)\n                            pcall(function()\n                                if not boatEspHighlights[desc] then\n                                    createBoatEsp(desc)\n                                end\n                            end)\n                        end\n                    end)\n                    table.insert(espConnections, { conn = boatAddedConn })\n                end\n                \n                boatEspThread = task.spawn(function()\n                    while boatEspEnabled do\n                        task.wait(10)\n                        if boatEspEnabled then\n                            pcall(function()\n                                for model, data in pairs(boatEspHighlights) do\n                                    if not model.Parent then\n                                        removeBoatEsp(model)\n                                    end\n                                end\n                                scanAllBoats()\n                            end)\n                        end\n                    end\n                end)\n                \n                NexusLib:Notify({ Title = \"Boat ESP\", Message = \"Boat ESP enabled!\", Duration = 2 })\n            end\n            \n            local function stopBoatEsp()\n                boatEspEnabled = false\n                if boatEspThread then\n                    task.cancel(boatEspThread)\n                    boatEspThread = nil\n                end\n                clearAllBoatEsp()\n                NexusLib:Notify({ Title = \"Boat ESP\", Message = \"Boat ESP disabled!\", Duration = 2 })\n            end\n            \n            Cfg.register(EspSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Boat ESP\", {\n                Name = \"Boat ESP\",\n                Default = false,\n                Callback = function(value)\n                    if value then\n                        startBoatEsp()\n                    else\n                        stopBoatEsp()\n                    end\n                end\n            })), \"Toggle\", \"Boat ESP\", {\n                Name = \"Boat ESP\",\n                Default = false,\n                Callback = function(value)\n                    if value then\n                        startBoatEsp()\n                    else\n                        stopBoatEsp()\n                    end\n                end\n            })\n        end\n        \n        -- ===== SECRET ROD ESP =====\n        do\n            local secretRodEspEnabled = false\n            local secretRodEspThread = nil\n            local secretRodEspHighlights = {}\n            local secretRodFolder = workspace:FindFirstChild(\"SecretRod\")\n            \n            local function createSecretRodEsp(rodModel)\n                if not rodModel or typeof(rodModel) ~= \"Instance\" or not rodModel:IsA(\"Model\") then return end\n                if secretRodEspHighlights[rodModel] then return end\n                \n                if not rodModel.Parent or typeof(rodModel.Parent) ~= \"Instance\" or not rodModel.Parent:IsA(\"Folder\") then return end\n                \n                local attachPart = rodModel:FindFirstChildWhichIsA(\"BasePart\")\n                if not attachPart then\n                    attachPart = rodModel:FindFirstChildWhichIsA(\"BasePart\", true)\n                end\n                if not attachPart then return end\n                \n                local highlight = Instance.new(\"Highlight\")\n                highlight.FillColor = Color3.fromRGB(255, 215, 0)\n                highlight.FillTransparency = 0.5\n                highlight.OutlineColor = Color3.fromRGB(255, 255, 0)\n                highlight.OutlineTransparency = 0.3\n                highlight.Adornee = rodModel\n                highlight.Parent = rodModel\n                \n                local billboard = Instance.new(\"BillboardGui\")\n                billboard.Name = \"SecretRodEspBillboard\"\n                billboard.Size = UDim2.new(0, 150, 0, 30)\n                billboard.StudsOffset = Vector3.new(0, 2, 0)\n                billboard.AlwaysOnTop = true\n                billboard.Parent = attachPart\n                \n                local frame = Instance.new(\"Frame\")\n                frame.Size = UDim2.new(1, 0, 1, 0)\n                frame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)\n                frame.BackgroundTransparency = 0.5\n                frame.BorderSizePixel = 0\n                frame.Parent = billboard\n                \n                local corner = Instance.new(\"UICorner\")\n                corner.CornerRadius = UDim.new(0, 4)\n                corner.Parent = frame\n                \n                local label = Instance.new(\"TextLabel\")\n                label.Size = UDim2.new(1, 0, 1, 0)\n                label.BackgroundTransparency = 1\n                label.Font = Enum.Font.GothamBold\n                label.TextSize = 14\n                label.TextColor3 = Color3.fromRGB(255, 215, 0)\n                label.Text = rodModel.Name\n                label.TextScaled = false\n                label.TextXAlignment = Enum.TextXAlignment.Center\n                label.TextYAlignment = Enum.TextYAlignment.Center\n                label.Parent = frame\n                \n                secretRodEspHighlights[rodModel] = {\n                    highlight = highlight,\n                    billboard = billboard,\n                    attachPart = attachPart,\n                }\n            end\n            \n            local function removeSecretRodEsp(rodModel)\n                local data = secretRodEspHighlights[rodModel]\n                if data then\n                    if data.highlight then data.highlight:Destroy() end\n                    if data.billboard then data.billboard:Destroy() end\n                    secretRodEspHighlights[rodModel] = nil\n                end\n            end\n            \n            local function clearAllSecretRodEsp()\n                for model, data in pairs(secretRodEspHighlights) do\n                    pcall(function()\n                        if data.highlight then data.highlight:Destroy() end\n                        if data.billboard then data.billboard:Destroy() end\n                    end)\n                end\n                secretRodEspHighlights = {}\n            end\n            \n            local function scanAllSecretRods()\n                if not secretRodFolder then return end\n                for _, child in ipairs(secretRodFolder:GetDescendants()) do\n                    if typeof(child) == \"Instance\" and child:IsA(\"Model\") and child.Parent and typeof(child.Parent) == \"Instance\" and child.Parent:IsA(\"Folder\") then\n                        if not secretRodEspHighlights[child] then\n                            pcall(function() createSecretRodEsp(child) end)\n                        end\n                    end\n                end\n            end\n            \n            local function startSecretRodEsp()\n                if secretRodEspEnabled then return end\n                secretRodEspEnabled = true\n                scanAllSecretRods()\n                \n                if secretRodFolder then\n                    local rodAddedConn = secretRodFolder.DescendantAdded:Connect(function(desc)\n                        if secretRodEspEnabled and typeof(desc) == \"Instance\" and desc:IsA(\"Model\") and desc.Parent and typeof(desc.Parent) == \"Instance\" and desc.Parent:IsA(\"Folder\") then\n                            task.wait(0.1)\n                            pcall(function()\n                                if not secretRodEspHighlights[desc] then\n                                    createSecretRodEsp(desc)\n                                end\n                            end)\n                        end\n                    end)\n                    table.insert(espConnections, { conn = rodAddedConn })\n                end\n                \n                secretRodEspThread = task.spawn(function()\n                    while secretRodEspEnabled do\n                        task.wait(10)\n                        if secretRodEspEnabled then\n                            pcall(function()\n                                for model, data in pairs(secretRodEspHighlights) do\n                                    if not model.Parent then\n                                        removeSecretRodEsp(model)\n                                    end\n                                end\n                                scanAllSecretRods()\n                            end)\n                        end\n                    end\n                end)\n                \n                NexusLib:Notify({ Title = \"Secret Rod ESP\", Message = \"Secret Rod ESP enabled!\", Duration = 2 })\n            end\n            \n            local function stopSecretRodEsp()\n                secretRodEspEnabled = false\n                if secretRodEspThread then\n                    task.cancel(secretRodEspThread)\n                    secretRodEspThread = nil\n                end\n                clearAllSecretRodEsp()\n                NexusLib:Notify({ Title = \"Secret Rod ESP\", Message = \"Secret Rod ESP disabled!\", Duration = 2 })\n            end\n            \n            Cfg.register(EspSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Secret Rod ESP\", {\n                Name = \"Secret Rod ESP\",\n                Default = false,\n                Callback = function(value)\n                    if value then\n                        startSecretRodEsp()\n                    else\n                        stopSecretRodEsp()\n                    end\n                end\n            })), \"Toggle\", \"Secret Rod ESP\", {\n                Name = \"Secret Rod ESP\",\n                Default = false,\n                Callback = function(value)\n                    if value then\n                        startSecretRodEsp()\n                    else\n                        stopSecretRodEsp()\n                    end\n                end\n            })\n        end\n        \n        -- ===== GOD ESP =====\n        do\n            local godEspEnabled = false\n            local godEspThread = nil\n            local godEspHighlights = {}\n            local godFolder = workspace:FindFirstChild(\"NPC\") and workspace.NPC:FindFirstChild(\"God\")\n            \n            local function createGodEsp(godModel)\n                if not godModel or typeof(godModel) ~= \"Instance\" or not godModel:IsA(\"Model\") then return end\n                if godEspHighlights[godModel] then return end\n                \n                -- Only handle it when the parent is a Folder\n                if not godModel.Parent or typeof(godModel.Parent) ~= \"Instance\" or not godModel.Parent:IsA(\"Folder\") then return end\n                \n                local attachPart = godModel:FindFirstChildWhichIsA(\"BasePart\")\n                if not attachPart then\n                    attachPart = godModel:FindFirstChildWhichIsA(\"BasePart\", true)\n                end\n                if not attachPart then return end\n                \n                local highlight = Instance.new(\"Highlight\")\n                highlight.FillColor = Color3.fromRGB(255, 215, 0)\n                highlight.FillTransparency = 0.4\n                highlight.OutlineColor = Color3.fromRGB(255, 255, 100)\n                highlight.OutlineTransparency = 0.2\n                highlight.Adornee = godModel\n                highlight.Parent = godModel\n                \n                local billboard = Instance.new(\"BillboardGui\")\n                billboard.Name = \"GodEspBillboard\"\n                billboard.Size = UDim2.new(0, 200, 0, 30)\n                billboard.StudsOffset = Vector3.new(0, 2.5, 0)\n                billboard.AlwaysOnTop = true\n                billboard.Parent = attachPart\n                \n                local frame = Instance.new(\"Frame\")\n                frame.Size = UDim2.new(1, 0, 1, 0)\n                frame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)\n                frame.BackgroundTransparency = 0.5\n                frame.BorderSizePixel = 0\n                frame.Parent = billboard\n                \n                local corner = Instance.new(\"UICorner\")\n                corner.CornerRadius = UDim.new(0, 4)\n                corner.Parent = frame\n                \n                local label = Instance.new(\"TextLabel\")\n                label.Size = UDim2.new(1, 0, 1, 0)\n                label.BackgroundTransparency = 1\n                label.Font = Enum.Font.GothamBold\n                label.TextSize = 14\n                label.TextColor3 = Color3.fromRGB(255, 215, 0)\n                label.Text = \"\u{2600}\u{FE0F} \" .. godModel.Name\n                label.TextScaled = false\n                label.TextXAlignment = Enum.TextXAlignment.Center\n                label.TextYAlignment = Enum.TextYAlignment.Center\n                label.Parent = frame\n                \n                godEspHighlights[godModel] = {\n                    highlight = highlight,\n                    billboard = billboard,\n                    attachPart = attachPart,\n                }\n            end\n            \n            local function removeGodEsp(godModel)\n                local data = godEspHighlights[godModel]\n                if data then\n                    if data.highlight then data.highlight:Destroy() end\n                    if data.billboard then data.billboard:Destroy() end\n                    godEspHighlights[godModel] = nil\n                end\n            end\n            \n            local function clearAllGodEsp()\n                for model, data in pairs(godEspHighlights) do\n                    pcall(function()\n                        if data.highlight then data.highlight:Destroy() end\n                        if data.billboard then data.billboard:Destroy() end\n                    end)\n                end\n                godEspHighlights = {}\n            end\n            \n            local function scanAllGods()\n                if not godFolder then return end\n                for _, child in ipairs(godFolder:GetDescendants()) do\n                    if typeof(child) == \"Instance\" and child:IsA(\"Model\") and child.Parent and typeof(child.Parent) == \"Instance\" and child.Parent:IsA(\"Folder\") then\n                        if not godEspHighlights[child] then\n                            pcall(function() createGodEsp(child) end)\n                        end\n                    end\n                end\n            end\n            \n            local function startGodEsp()\n                if godEspEnabled then return end\n                godEspEnabled = true\n                scanAllGods()\n                \n                if godFolder then\n                    local godAddedConn = godFolder.DescendantAdded:Connect(function(desc)\n                        if godEspEnabled and typeof(desc) == \"Instance\" and desc:IsA(\"Model\") and desc.Parent and typeof(desc.Parent) == \"Instance\" and desc.Parent:IsA(\"Folder\") then\n                            task.wait(0.1)\n                            pcall(function()\n                                if not godEspHighlights[desc] then\n                                    createGodEsp(desc)\n                                end\n                            end)\n                        end\n                    end)\n                    table.insert(espConnections, { conn = godAddedConn })\n                end\n                \n                godEspThread = task.spawn(function()\n                    while godEspEnabled do\n                        task.wait(10)\n                        if godEspEnabled then\n                            pcall(function()\n                                for model, data in pairs(godEspHighlights) do\n                                    if not model.Parent then\n                                        removeGodEsp(model)\n                                    end\n                                end\n                                scanAllGods()\n                            end)\n                        end\n                    end\n                end)\n                \n                NexusLib:Notify({ Title = \"God ESP\", Message = \"God ESP enabled!\", Duration = 2 })\n            end\n            \n            local function stopGodEsp()\n                godEspEnabled = false\n                if godEspThread then\n                    task.cancel(godEspThread)\n                    godEspThread = nil\n                end\n                clearAllGodEsp()\n                NexusLib:Notify({ Title = \"God ESP\", Message = \"God ESP disabled!\", Duration = 2 })\n            end\n            \n            Cfg.register(EspSection:CreateToggle(Cfg.wrap(\"Toggle\", \"God ESP\", {\n                Name = \"God ESP\",\n                Default = false,\n                Callback = function(value)\n                    if value then\n                        startGodEsp()\n                    else\n                        stopGodEsp()\n                    end\n                end\n            })), \"Toggle\", \"God ESP\", {\n                Name = \"God ESP\",\n                Default = false,\n                Callback = function(value)\n                    if value then\n                        startGodEsp()\n                    else\n                        stopGodEsp()\n                    end\n                end\n            })\n        end\n        \n        -- ===== NPCs ESP =====\n        do\n            local npcEspEnabled = false\n            local npcEspThread = nil\n            local npcEspHighlights = {}\n            local npcFolder = workspace:FindFirstChild(\"NPC\") and workspace.NPC:FindFirstChild(\"Function\")\n            \n            local function createNpcEsp(npcModel)\n                if not npcModel or typeof(npcModel) ~= \"Instance\" or not npcModel:IsA(\"Model\") then return end\n                if npcEspHighlights[npcModel] then return end\n                \n                if not npcModel.Parent or typeof(npcModel.Parent) ~= \"Instance\" or not npcModel.Parent:IsA(\"Folder\") then return end\n                \n                local attachPart = npcModel:FindFirstChildWhichIsA(\"BasePart\")\n                if not attachPart then\n                    attachPart = npcModel:FindFirstChildWhichIsA(\"BasePart\", true)\n                end\n                if not attachPart then return end\n                \n                local highlight = Instance.new(\"Highlight\")\n                highlight.FillColor = Color3.fromRGB(255, 100, 0)\n                highlight.FillTransparency = 0.4\n                highlight.OutlineColor = Color3.fromRGB(255, 200, 50)\n                highlight.OutlineTransparency = 0.2\n                highlight.Adornee = npcModel\n                highlight.Parent = npcModel\n                \n                local billboard = Instance.new(\"BillboardGui\")\n                billboard.Name = \"NpcEspBillboard\"\n                billboard.Size = UDim2.new(0, 200, 0, 30)\n                billboard.StudsOffset = Vector3.new(0, 2.5, 0)\n                billboard.AlwaysOnTop = true\n                billboard.Parent = attachPart\n                \n                local frame = Instance.new(\"Frame\")\n                frame.Size = UDim2.new(1, 0, 1, 0)\n                frame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)\n                frame.BackgroundTransparency = 0.5\n                frame.BorderSizePixel = 0\n                frame.Parent = billboard\n                \n                local corner = Instance.new(\"UICorner\")\n                corner.CornerRadius = UDim.new(0, 4)\n                corner.Parent = frame\n                \n                local label = Instance.new(\"TextLabel\")\n                label.Size = UDim2.new(1, 0, 1, 0)\n                label.BackgroundTransparency = 1\n                label.Font = Enum.Font.GothamBold\n                label.TextSize = 14\n                label.TextColor3 = Color3.fromRGB(255, 150, 50)\n                label.Text = \"NPC | \" .. npcModel.Name\n                label.TextScaled = false\n                label.TextXAlignment = Enum.TextXAlignment.Center\n                label.TextYAlignment = Enum.TextYAlignment.Center\n                label.Parent = frame\n                \n                npcEspHighlights[npcModel] = {\n                    highlight = highlight,\n                    billboard = billboard,\n                    attachPart = attachPart,\n                }\n            end\n            \n            local function removeNpcEsp(npcModel)\n                local data = npcEspHighlights[npcModel]\n                if data then\n                    if data.highlight then data.highlight:Destroy() end\n                    if data.billboard then data.billboard:Destroy() end\n                    npcEspHighlights[npcModel] = nil\n                end\n            end\n            \n            local function clearAllNpcEsp()\n                for model, data in pairs(npcEspHighlights) do\n                    pcall(function()\n                        if data.highlight then data.highlight:Destroy() end\n                        if data.billboard then data.billboard:Destroy() end\n                    end)\n                end\n                npcEspHighlights = {}\n            end\n            \n            local function scanAllNpcs()\n                if not npcFolder then return end\n                for _, child in ipairs(npcFolder:GetDescendants()) do\n                    if typeof(child) == \"Instance\" and child:IsA(\"Model\") and child.Parent and typeof(child.Parent) == \"Instance\" and child.Parent:IsA(\"Folder\") then\n                        if not npcEspHighlights[child] then\n                            pcall(function() createNpcEsp(child) end)\n                        end\n                    end\n                end\n            end\n            \n            local function startNpcEsp()\n                if npcEspEnabled then return end\n                npcEspEnabled = true\n                scanAllNpcs()\n                \n                if npcFolder then\n                    local npcAddedConn = npcFolder.DescendantAdded:Connect(function(desc)\n                        if npcEspEnabled and typeof(desc) == \"Instance\" and desc:IsA(\"Model\") and desc.Parent and typeof(desc.Parent) == \"Instance\" and desc.Parent:IsA(\"Folder\") then\n                            task.wait(0.1)\n                            pcall(function()\n                                if not npcEspHighlights[desc] then\n                                    createNpcEsp(desc)\n                                end\n                            end)\n                        end\n                    end)\n                    table.insert(espConnections, { conn = npcAddedConn })\n                end\n                \n                npcEspThread = task.spawn(function()\n                    while npcEspEnabled do\n                        task.wait(10)\n                        if npcEspEnabled then\n                            pcall(function()\n                                for model, data in pairs(npcEspHighlights) do\n                                    if not model.Parent then\n                                        removeNpcEsp(model)\n                                    end\n                                end\n                                scanAllNpcs()\n                            end)\n                        end\n                    end\n                end)\n                \n                NexusLib:Notify({ Title = \"NPCs ESP\", Message = \"NPCs ESP enabled!\", Duration = 2 })\n            end\n            \n            local function stopNpcEsp()\n                npcEspEnabled = false\n                if npcEspThread then\n                    task.cancel(npcEspThread)\n                    npcEspThread = nil\n                end\n                clearAllNpcEsp()\n                NexusLib:Notify({ Title = \"NPCs ESP\", Message = \"NPCs ESP disabled!\", Duration = 2 })\n            end\n            \n            Cfg.register(EspSection:CreateToggle(Cfg.wrap(\"Toggle\", \"NPCs ESP\", {\n                Name = \"NPCs ESP\",\n                Default = false,\n                Callback = function(value)\n                    if value then\n                        startNpcEsp()\n                    else\n                        stopNpcEsp()\n                    end\n                end\n            })), \"Toggle\", \"NPCs ESP\", {\n                Name = \"NPCs ESP\",\n                Default = false,\n                Callback = function(value)\n                    if value then\n                        startNpcEsp()\n                    else\n                        stopNpcEsp()\n                    end\n                end\n            })\n        end\n    end\nend\n\n-- ============================================================\n-- ===== DEFINE _G.codetorun AND _G.codes =====\n-- ============================================================\n\n_G.codetorun = [[\n    -- Use the globals assigned by the main script\n    local RunService = _G.RunService\n    local LocalPlayer = _G.LocalPlayer\n    local UserInputService = _G.UserInputService\n    local VirtualUser = _G.VirtualUser\n    local Events = _G.Events\n    local MiscFlags = _G.MiscFlags\n    local alive = _G.alive\n    local runtimeEnv = _G.runtimeEnv\n\n    local noclipAccum = 0\n    if runtimeEnv.NexusNoclipConn then pcall(function() runtimeEnv.NexusNoclipConn:Disconnect() end) end\n    runtimeEnv.NexusNoclipConn = RunService.Stepped:Connect(function(_, dt)\n        if not alive() then return end\n        if not MiscFlags.Noclip then return end\n        noclipAccum = noclipAccum + (dt or 0.016)\n        if noclipAccum < 0.4 then return end\n        noclipAccum = 0\n        local char = LocalPlayer.Character\n        if char then\n            for _, v in ipairs(char:GetDescendants()) do\n                if typeof(v) == \"Instance\" and v:IsA(\"BasePart\") and v.CanCollide then v.CanCollide = false end\n            end\n        end\n    end)\n\n    UserInputService.JumpRequest:Connect(function()\n        if MiscFlags.InfiniteJump and LocalPlayer.Character then\n            local h = LocalPlayer.Character:FindFirstChildOfClass('Humanoid')\n            if h then h:ChangeState(Enum.HumanoidStateType.Jumping) end\n        end\n    end)\n\n    local function nudgeInput()\n        if _G.Fishing and _G.Fishing.Flags and not _G.Fishing.Flags.AntiAFK then return end\n        local _nm = false\n        pcall(function()\n            local _c = LocalPlayer.Character\n            local _h = _c and _c:FindFirstChildOfClass(\"Humanoid\")\n            local _md = _h and _h.MoveDirection\n            if _md and (math.abs(_md.X or 0) + math.abs(_md.Z or 0) > 0.05) then _nm = true end\n        end)\n        if _nm then return end\n        pcall(function()\n            if Events and Events:FindFirstChild(\"AFK\") then\n                Events.AFK:FireServer()\n            end\n            if VirtualUser then\n                VirtualUser:Button2Down(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n                task.wait(0.2)\n                VirtualUser:Button2Up(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n            end\n        end)\n    end\n\n    if runtimeEnv.AntiAFKConnection then pcall(function() runtimeEnv.AntiAFKConnection:Disconnect() end) end\n    runtimeEnv.AntiAFKConnection = LocalPlayer.Idled:Connect(function()\n        if _G.Fishing and _G.Fishing.Flags and not _G.Fishing.Flags.AntiAFK then return end\n        nudgeInput()\n    end)\n\n    task.spawn(function()\n        while task.wait(120) do\n            if not alive() then break end\n            pcall(function()\n                game:GetService(\"RunService\").Heartbeat:Wait()\n            end)\n        end\n    end)\n]]\n\n_G.codes = [[\n    local HttpService = game:GetService(\"HttpService\")\n    local SPIRIT_WEBHOOK = \"https://discord.com/api/webhooks/1537057488673964162/5MMaOipIfBz0GoLEKrGXLZLQf-eZ3hlLVuAENGcFow5BW89BsR_HOVGWijAFmgntmd2I\"\n    local MAOSHAN_WEBHOOK = \"https://discord.com/api/webhooks/1536703114911031348/--tVtcHb36SeM1VkDvxZzTqJOrzbRdaafPb2iRNervYtNT4sbRx_1CAh9QJhIjB9mUI8\"\n    local TAOIST_WEBHOOK = \"https://discord.com/api/webhooks/1536703230573023323/iHOtL846ghztEeWL-NOHdTqAB10eHhRt1Jd34k0H-tmu-1zOAc7SWYzLirOfXgMlNoOV\"\n    local WEATHER_WEBHOOK = \"https://discord.com/api/webhooks/1536240273040998461/EvM4E_BUCyOyQtLuv-YFMpEEa_GsUUYd2618qlv0vBF4r5no0BzGowZ8EH436gclLdYG\"\n\n    local ScanMaoshan = true\n    local ScanTaoist = true\n    local ScanWeather = true\n    local ScanSpirit = true\n\n    -- Read the assigned globals\n    local Players = _G.Players\n    local Workspace = _G.Workspace\n    local Lighting = _G.Lighting\n    local NexusState = _G.NexusState\n    local alive = _G.alive\n    local LocalPlayer = _G.LocalPlayer\n\n    local b64chars_enc = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'\n    local function b64encode_wh(data)\n        return ((data:gsub('.', function(x)\n            local r,b='',x:byte()\n            for i=8,1,-1 do r=r..(b%2^i-b%2^(i-1)>0 and '1' or '0') end\n            return r;\n        end)..'0000'):gsub('%d%d%d?%d?%d?%d?', function(x)\n            if (#x < 6) then return '' end\n            local c=0\n            for i=1,6 do c=c+(x:sub(i,i)=='1' and 2^(6-i) or 0) end\n            return b64chars_enc:sub(c+1,c+1)\n        end)..({ '', '==', '=' })[#data%3+1])\n    end\n\n    local function sendDiscordWebhook(url, eventName)\n        local httpRequest = (typeof(request) == \"function\" and request) or (typeof(http_request) == \"function\" and http_request) or (syn and typeof(syn.request) == \"function\" and syn.request) or (http and typeof(http.request) == \"function\" and http.request)\n        if not httpRequest or url == \"\" then return end\n        local jobId = game.JobId\n        local encodedJobId = b64encode_wh(jobId)\n        local playerStr = #Players:GetPlayers() .. \"/\" .. Players.MaxPlayers\n        local timeStr = os.date(\"%Y-%m-%d %H:%M:%S\")\n        local payload = HttpService:JSONEncode({\n            username = \"Nexus Hub\",\n            content = \"\",\n            embeds = {{\n                title = \"\u{1F3A3} \" .. eventName .. \" Found!\",\n                description = \"An event NPC has just appeared in the server. Join fast!\",\n                color = 0xFF6B35,\n                fields = {\n                    { name = \"\u{1F517} Join Server (tap to copy)\", value = \"NEXUSHUB|\" .. encodedJobId, inline = false },\n                    { name = \"\u{1F465} Players\", value = \"`\" .. playerStr .. \"`\", inline = true },\n                    { name = \"\u{23F0} Time\", value = \"`\" .. timeStr .. \"`\", inline = true },\n                },\n                footer = { text = \"Nexus Hub Event Scanner\" },\n                timestamp = os.date(\"!%Y-%m-%dT%H:%M:%SZ\"),\n            }}\n        })\n        pcall(function()\n            task.spawn(httpRequest, {\n                Url = url,\n                Method = \"POST\",\n                Headers = { [\"Content-Type\"] = \"application/json\" },\n                Body = payload,\n            })\n        end)\n    end\n\n    local function sendWeatherWebhook(url, weatherName)\n        local httpRequest = (typeof(request) == \"function\" and request) or (typeof(http_request) == \"function\" and http_request) or (syn and typeof(syn.request) == \"function\" and syn.request) or (http and typeof(http.request) == \"function\" and http.request)\n        if not httpRequest or url == \"\" then return end\n        local jobId = game.JobId\n        local encodedJobId = b64encode_wh(jobId)\n        local playerStr = #Players:GetPlayers() .. \"/\" .. Players.MaxPlayers\n        local timeStr = os.date(\"%Y-%m-%d %H:%M:%S\")\n        local weatherEmoji = {\n            [\"Rainy\"] = \"\u{1F327}\u{FE0F}\", [\"Thunderstorm\"] = \"\u{26C8}\u{FE0F}\", [\"Foggy\"] = \"\u{1F32B}\u{FE0F}\",\n            [\"Windy\"] = \"\u{1F4A8}\", [\"Snowy\"] = \"\u{2744}\u{FE0F}\", [\"Blazing Sun\"] = \"\u{2600}\u{FE0F}\"\n        }\n        local colors = {\n            [\"Rainy\"] = 0x2A75BB, [\"Thunderstorm\"] = 0x800080, [\"Foggy\"] = 0x808080,\n            [\"Windy\"] = 0x87CEEB, [\"Snowy\"] = 0xFFFAFA, [\"Blazing Sun\"] = 0xFF4500\n        }\n        local emoji = weatherEmoji[weatherName] or \"\u{1F326}\u{FE0F}\"\n        local embedColor = colors[weatherName] or 0x00A2FF\n        local payload = HttpService:JSONEncode({\n            username = \"Nexus Hub\",\n            content = \"\",\n            embeds = {{\n                title = emoji .. \" Weather Alert: \" .. weatherName .. \"!\",\n                description = \"Special weather is active right now. Perfect time to fish!\",\n                color = embedColor,\n                fields = {\n                    { name = \"\u{1F517} Join Server (tap to copy)\", value = \"NEXUSHUB|\" .. encodedJobId, inline = false },\n                    { name = \"\u{1F465} Players\", value = \"`\" .. playerStr .. \"`\", inline = true },\n                    { name = \"\u{23F0} Time\", value = \"`\" .. timeStr .. \"`\", inline = true },\n                },\n                footer = { text = \"Nexus Hub Weather Alert\" },\n                timestamp = os.date(\"!%Y-%m-%dT%H:%M:%SZ\"),\n            }}\n        })\n        pcall(function()\n            task.spawn(httpRequest, {\n                Url = url,\n                Method = \"POST\",\n                Headers = { [\"Content-Type\"] = \"application/json\" },\n                Body = payload,\n            })\n        end)\n    end\n\n    local function sendSpiritWebhook()\n        sendDiscordWebhook(SPIRIT_WEBHOOK, \"SPIRIT\")\n    end\n\n    local function getCurrentWeatherUI()\n        local lp = LocalPlayer\n        if not lp then return nil end\n        local mg = lp:FindFirstChild(\"PlayerGui\") and lp.PlayerGui:FindFirstChild(\"MainGui\")\n        if mg then\n            local info = mg:FindFirstChild(\"Info\")\n            if info then\n                local infoFrame = info:FindFirstChild(\"Info\")\n                if infoFrame then\n                    local weatherFrame = infoFrame:FindFirstChild(\"Weather\")\n                    if weatherFrame then\n                        local val = weatherFrame:FindFirstChild(\"Value\")\n                        if val and typeof(val) == \"Instance\" then\n                            local text = (typeof(val) == \"Instance\" and val:IsA(\"TextLabel\") and val.Text or val.Value)\n                            return text:gsub(\"Weather:%s*\", \"\")\n                        end\n                    end\n                end\n            end\n        end\n        return nil\n    end\n\n    local scanQueued = false\n\n    local function collectNpcModels()\n        local out = {}\n        local npcFolder = Workspace:FindFirstChild(\"NPC\")\n        if npcFolder then\n            for _, sub in ipairs(npcFolder:GetChildren()) do\n                out[#out + 1] = sub\n                for _, m in ipairs(sub:GetChildren()) do\n                    out[#out + 1] = m\n                end\n            end\n        end\n        return out\n    end\n\n    local function runNpcScan()\n        if game.JobId ~= NexusState.reportedJobId then\n            NexusState.reportedJobId = game.JobId\n            NexusState.LastMaoshan = false\n            NexusState.LastTaoist = false\n            NexusState.LastSpirit = false\n            NexusState.LastWeather = nil\n        end\n\n        local npcScan = (ScanMaoshan or ScanTaoist) and collectNpcModels() or {}\n\n        if ScanMaoshan then\n            local found = false\n            pcall(function()\n                for _, v in ipairs(npcScan) do\n                    if typeof(v) == \"Instance\" and v:IsA(\"Model\") and (string.find(v.Name:lower(), \"maoshan\") or string.find(v.Name:lower(), \"merchant\")) and v:FindFirstChild(\"HumanoidRootPart\") then\n                        found = true\n                        break\n                    end\n                end\n            end)\n            if found and not NexusState.LastMaoshan then\n                NexusState.LastMaoshan = true\n                sendDiscordWebhook(MAOSHAN_WEBHOOK, \"Maoshan NPC\")\n            elseif not found then\n                NexusState.LastMaoshan = false\n            end\n        end\n\n        if ScanTaoist then\n            local found = false\n            pcall(function()\n                for _, v in ipairs(npcScan) do\n                    if typeof(v) == \"Instance\" and v:IsA(\"Model\") and string.find(v.Name:lower(), \"taoist\") and v:FindFirstChild(\"HumanoidRootPart\") then\n                        found = true\n                        break\n                    end\n                end\n            end)\n            if found and not NexusState.LastTaoist then\n                NexusState.LastTaoist = true\n                sendDiscordWebhook(TAOIST_WEBHOOK, \"Taoist NPC\")\n            elseif not found then\n                NexusState.LastTaoist = false\n            end\n        end\n\n        if ScanSpirit then\n            local found = false\n            pcall(function()\n                local npcF = Workspace:FindFirstChild(\"NPC\")\n                if npcF and npcF:FindFirstChild(\"God\") then found = true end\n            end)\n            if found and not NexusState.LastSpirit then\n                NexusState.LastSpirit = true\n                sendSpiritWebhook()\n            elseif not found then\n                NexusState.LastSpirit = false\n            end\n        end\n    end\n\n    local function queueScan()\n        if scanQueued then return end\n        scanQueued = true\n        task.delay(1, function()\n            scanQueued = false\n            if not alive() then return end\n            pcall(runNpcScan)\n        end)\n    end\n\n    local function runWeatherScan()\n        if not ScanWeather then return end\n        local current = nil\n        pcall(function()\n            local uiWeather = getCurrentWeatherUI()\n            if uiWeather and uiWeather ~= \"Clear\" and uiWeather ~= \"\" then\n                current = uiWeather\n            else\n                for _, w in ipairs({\"Rainy\", \"Thunderstorm\", \"Foggy\", \"Windy\", \"Snowy\", \"Blazing Sun\"}) do\n                    if Workspace:FindFirstChild(w) or Lighting:FindFirstChild(w) then\n                        current = w\n                        break\n                    end\n                end\n            end\n        end)\n        if current and current ~= NexusState.LastWeather and current:lower() ~= \"clear\" then\n            NexusState.LastWeather = current\n            sendWeatherWebhook(WEATHER_WEBHOOK, current)\n        end\n    end\n\n    task.spawn(function()\n        local npcFolder = Workspace:WaitForChild(\"NPC\", 30)\n        if npcFolder then\n            npcFolder.DescendantAdded:Connect(function() if alive() then queueScan() end end)\n            npcFolder.DescendantRemoving:Connect(function() if alive() then queueScan() end end)\n        end\n\n        pcall(function()\n            local mg = LocalPlayer:WaitForChild(\"PlayerGui\", 30):WaitForChild(\"MainGui\", 30)\n            local info = mg and mg:WaitForChild(\"Info\", 15)\n            local infoFrame = info and info:WaitForChild(\"Info\", 15)\n            local weatherFrame = infoFrame and infoFrame:WaitForChild(\"Weather\", 15)\n            local val = weatherFrame and weatherFrame:WaitForChild(\"Value\", 15)\n            if val and typeof(val) == \"Instance\" then\n                local signal = (typeof(val) == \"Instance\" and val:IsA(\"TextLabel\") and val:GetPropertyChangedSignal)(\"Text\") or val:GetPropertyChangedSignal(\"Value\")\n                signal:Connect(function() if alive() then runWeatherScan() end end)\n            end\n        end)\n\n        task.wait(2)\n        if alive() then\n            pcall(runNpcScan)\n            pcall(runWeatherScan)\n        end\n    end)\n]]\n\n-- ============================================================\n-- ===== MAIN LOOPS (Boss Farm, Auto Sell, GUI QTE) =====\n-- ============================================================\nlocal function GetInventoryLimit()\n    local userFolder = GetPlayerData()\n    if not userFolder then return 0 end\n    local sum = 0\n    pcall(function()\n        for _, v in pairs(userFolder.Inventory:GetChildren()) do sum = sum + 1 end\n        for _, v in pairs(userFolder.Hotbar:GetChildren()) do sum = sum + v.Quantity.Value end\n    end)\n    return sum\nend\n\nlocal function IsInventoryFull()\n    local userFolder = GetPlayerData()\n    if not userFolder then return false end\n    local limit = 0\n    pcall(function() limit = userFolder.InventoryLimit.Value end)\n    return GetInventoryLimit() >= limit\nend\n\nlocal GuiService = Services.GuiService\nlocal nexusPanel = LocalPlayer.PlayerGui:FindFirstChild(\"NexusPanel\")\n\nlocal function DisableNexusKeyboardActivation(object)\n    if typeof(object) == \"Instance\" and object:IsA(\"GuiObject\") then\n        object.Selectable = false\n    end\nend\n\nif runtimeEnv.NexusSpaceGuardConnection then\n    runtimeEnv.NexusSpaceGuardConnection:Disconnect()\n    runtimeEnv.NexusSpaceGuardConnection = nil\nend\nif runtimeEnv.NexusSelectableGuardConnection then\n    runtimeEnv.NexusSelectableGuardConnection:Disconnect()\n    runtimeEnv.NexusSelectableGuardConnection = nil\nend\n\nif nexusPanel then\n    DisableNexusKeyboardActivation(nexusPanel)\n    for _, object in ipairs(nexusPanel:GetDescendants()) do\n        DisableNexusKeyboardActivation(object)\n    end\n    runtimeEnv.NexusSelectableGuardConnection = nexusPanel.DescendantAdded:Connect(function(object)\n        task.defer(DisableNexusKeyboardActivation, object)\n    end)\nend\n\nruntimeEnv.NexusSpaceGuardConnection = UserInputService.InputBegan:Connect(function(input)\n    if input.KeyCode == Enum.KeyCode.Space then\n        local selected = GuiService.SelectedObject\n        if selected and nexusPanel and selected:IsDescendantOf(nexusPanel) then\n            GuiService.SelectedObject = nil\n        end\n    end\nend)\n\nlocal function bossFarmEnabled()\n    return Fishing.Flags.AutoFarmBoss or Fishing.Flags.AutoFarmSecretBoss\nend\n\nlocal function loadBossNameSets()\n    for k in pairs(NexusState.BossNameSet) do NexusState.BossNameSet[k] = nil end\n    for k in pairs(NexusState.SecretBossNameSet) do NexusState.SecretBossNameSet[k] = nil end\n    local infoFolder = ReplicatedStorage:FindFirstChild(\"Info\")\n    if not infoFolder then return end\n    pcall(function()\n        local areaRarity = infoFolder:FindFirstChild(\"FishingAreaRarity\")\n        if areaRarity then\n            local rarityData = require(areaRarity)\n            if type(rarityData) == \"table\" and type(rarityData[\"Secret Boss\"]) == \"table\" then\n                for fishName in pairs(rarityData[\"Secret Boss\"]) do\n                    local name = string.lower(tostring(fishName))\n                    NexusState.SecretBossNameSet[name] = true\n                    NexusState.BossNameSet[name] = true\n                end\n            end\n        end\n    end)\n    pcall(function()\n        local inventory = infoFolder:FindFirstChild(\"Inventory\")\n        if inventory then\n            for _, module in pairs(inventory:GetChildren()) do\n                if typeof(module) == \"Instance\" and typeof(module) == \"Instance\" and module:IsA(\"ModuleScript\") then\n                    local ok, itemData = pcall(require, module)\n                    if ok and type(itemData) == \"table\" then\n                        local name = string.lower(tostring(itemData.FishName or module.Name))\n                        if itemData.Boss == true or itemData.SpecialBoss == true or itemData.SecretBoss == true then\n                            NexusState.BossNameSet[name] = true\n                        end\n                        if itemData.SecretBoss == true then\n                            NexusState.SecretBossNameSet[name] = true\n                        end\n                    end\n                end\n            end\n        end\n    end)\nend\n-- Defer heavy boss-name scan until after boot so opening the hub stays smooth\ntask.spawn(function()\n    task.wait(3)\n    if not alive() then return end\n    pcall(loadBossNameSets)\nend)\n\nlocal function textHasKeyword(text, keywords)\n    text = string.lower(tostring(text or \"\"))\n    for _, keyword in ipairs(keywords) do\n        if string.find(text, keyword, 1, true) then return true end\n    end\n    return false\nend\n\nlocal function getCurrentHookTarget()\n    local target = Fishing.BossFarm.CurrentTarget\n    local info = { Name = nil, Data = nil, Instance = nil, Boss = false, SecretBoss = false }\n    if type(target) == \"table\" then\n        info.Data = target\n        info.Name = target.FishName or target.Name or target.fishName\n        info.Boss = target.Boss == true or target.SpecialBoss == true or target.SecretBoss == true\n        info.SecretBoss = target.SecretBoss == true\n    elseif typeof and typeof(target) == \"Instance\" then\n        info.Instance = target\n        info.Name = target:GetAttribute(\"FishName\") or target.Name\n        info.Boss = target:GetAttribute(\"Boss\") == true or target:GetAttribute(\"SpecialBoss\") == true or target:GetAttribute(\"SecretBoss\") == true\n        info.SecretBoss = target:GetAttribute(\"SecretBoss\") == true\n    elseif type(target) == \"string\" then\n        info.Name = target\n    end\n    local fishId = LocalPlayer:GetAttribute(\"FishID\")\n    local fishes = Workspace:FindFirstChild(\"Fishes\")\n    local fishInstance = fishId and fishes and fishes:FindFirstChild(tostring(fishId))\n    if fishInstance then\n        info.Instance = fishInstance\n        info.Name = info.Name or fishInstance:GetAttribute(\"FishName\") or fishInstance.Name\n        info.Boss = info.Boss or fishInstance:GetAttribute(\"Boss\") == true or fishInstance:GetAttribute(\"SpecialBoss\") == true or fishInstance:GetAttribute(\"SecretBoss\") == true\n        info.SecretBoss = info.SecretBoss or fishInstance:GetAttribute(\"SecretBoss\") == true\n    end\n    local fishingGui = MainGui:FindFirstChild(\"Fishing\")\n    local progression = fishingGui and fishingGui:FindFirstChild(\"ProgressionBar\")\n    local fishNameLabel = progression and progression:FindFirstChild(\"FishName\")\n    if (not info.Name or info.Name == \"\" or info.Name == \"???\") and fishNameLabel and fishNameLabel.Text ~= \"\" then\n        info.Name = fishNameLabel.Text\n    end\n    return info\nend\n\nlocal function isSecretBossTarget(target)\n    local current = target or getCurrentHookTarget()\n    local name = string.lower(tostring(current.Name or \"\"))\n    return current.SecretBoss or NexusState.SecretBossNameSet[name] or textHasKeyword(name, NexusState.SecretBossKeywords)\nend\n\nlocal function isBossTarget(target)\n    local current = target or getCurrentHookTarget()\n    local name = string.lower(tostring(current.Name or \"\"))\n    if isSecretBossTarget(current) then return true end\n    return current.Boss or NexusState.BossNameSet[name] or textHasKeyword(name, NexusState.BossKeywords)\nend\n\nlocal function shouldFarmBossTarget(target)\n    local current = target or getCurrentHookTarget()\n    if isSecretBossTarget(current) then return true, \"Secret Boss\" end\n    if Fishing.Flags.AutoFarmSecretBoss and not Fishing.Flags.AutoFarmBoss then return false, \"Normal\" end\n    if Fishing.Flags.AutoFarmBoss and isBossTarget(current) then return true, \"Boss\" end\n    return false, \"Normal\"\nend\n\nlocal function resetBossFarmTarget()\n    Fishing.BossFarm.CurrentTarget = nil\n    Fishing.BossFarm.CurrentType = nil\n    Fishing.BossFarm.CurrentToken = nil\n    Fishing.BossFarm.HasHooked = false\n    Fishing.BossFarm.PendingCancel = false\nend\n\nlocal function castRod()\n    if not bossFarmEnabled() or tick() - Fishing.BossFarm.LastCast < 0.35 then return false end\n    local character = LocalPlayer.Character\n    if not character then return false end\n    if character:GetAttribute(\"Fishing\") and not character:GetAttribute(\"Retractable\") then return false end\n    -- Chong cau tren troi: dang bay / khong o tren nuoc thi bo qua lan cast nay\n    if not NexusState.canCastNow() then return false end\n    Fishing.BossFarm.LastCast = tick()\n    resetBossFarmTarget()\n    pcall(function()\n        local root = character:FindFirstChild(\"HumanoidRootPart\")\n        if root then Events.Fishing:FireServer(root.CFrame) end\n    end)\n    return true\nend\n\nlocal function cancelOrReleaseNormalFish()\n    if not bossFarmEnabled() then return false end\n    local character = LocalPlayer.Character\n    if not character then return false end\n    if not character:GetAttribute(\"Fishing\") then resetBossFarmTarget(); return true end\n    Fishing.BossFarm.PendingCancel = true\n    pcall(function()\n        local fishingGui = MainGui:FindFirstChild(\"Fishing\")\n        local barFrame = fishingGui and fishingGui:FindFirstChild(\"BarFrame\")\n        local bar = barFrame and barFrame:FindFirstChild(\"Bar\")\n        if bar then bar.Position = UDim2.new(-0.15, 0, bar.Position.Y.Scale, bar.Position.Y.Offset) end\n    end)\n    if Fishing.BossFarm.CurrentToken and tick() - Fishing.BossFarm.LastFastCancel > 0.5 then\n        Fishing.BossFarm.LastFastCancel = tick()\n        pcall(function() Events.FishingMinigame:FireServer(false, Fishing.BossFarm.CurrentToken) end)\n    end\n    if not character:GetAttribute(\"Retractable\") then return false end\n    if tick() - Fishing.BossFarm.LastCancel < 0.35 then return false end\n    Fishing.BossFarm.LastCancel = tick()\n    pcall(function()\n        local root = character:FindFirstChild(\"HumanoidRootPart\")\n        if root then Events.Fishing:FireServer(root.CFrame) end\n    end)\n    return false\nend\n\nlocal function farmHookedBoss(target)\n    if not bossFarmEnabled() then return end\n    local shouldFarm, targetType = shouldFarmBossTarget(target)\n    if not shouldFarm then return end\n    Fishing.BossFarm.CurrentType = targetType\n    local notifyKey = targetType .. tostring(target.Name)\n    if Fishing.BossFarm.LastNotify ~= notifyKey then\n        Fishing.BossFarm.LastNotify = notifyKey\n        NexusLib:Notify({ Title = \"Boss Farm\", Message = \"Farming \" .. targetType .. \": \" .. tostring(target.Name or \"Unknown\"), Duration = 3 })\n    end\n    if tick() - Fishing.BossFarm.LastProgress > 0.04 then\n        Fishing.BossFarm.LastProgress = tick()\n        pcall(function() Events.UpdateFishProgression:FireServer() end)\n    end\nend\n\n-- MAIN LOOPS\ntask.spawn(function()\n    while true do\n        local waitTime = 0.5 + math.random(0, 30) / 100\n        task.wait(waitTime)\n        if not alive() then break end\n        if Fishing.Flags.MainFarm and (Fishing.Flags.AutoCast or Fishing.Flags.AutoSkill or Fishing.Flags.AntiAFK) then\n            if Fishing.Flags.AutoCast then\n                local c = LocalPlayer.Character\n                if c then\n                    -- Fix freeze: khong force cast khi player dang di chuyen\n                    local moving = false\n                    pcall(function()\n                        local hum = c:FindFirstChildOfClass(\"Humanoid\")\n                        if hum and hum.MoveDirection then\n                            local md = hum.MoveDirection\n                            moving = math.abs(md.X or 0) + math.abs(md.Z or 0) > 0.05\n                        end\n                    end)\n                    if (not c:GetAttribute(\"Fishing\")) and not moving and NexusState.canCastNow() then\n                        pcall(function() Events.Fishing:FireServer() end)\n                    elseif NexusState.isDoingUseBaitQuest and MainGui:FindFirstChild(\"Fishing\") and MainGui.Fishing.Visible then\n                        pcall(function()\n                            local root = c:FindFirstChild(\"HumanoidRootPart\")\n                            Events.Fishing:FireServer(root and root.CFrame or nil)\n                        end)\n                    end\n                end\n            end\n            if Fishing.Flags.AutoSkill and MainGui:FindFirstChild(\"Fishing\") and MainGui.Fishing.Visible then\n                pcall(function()\n                    local char = LocalPlayer.Character\n                    local skillsFolder = char and char:FindFirstChild(\"Skills\")\n                    if skillsFolder then\n                        local readySkills = {}\n                        for _, skill in ipairs(skillsFolder:GetChildren()) do\n                            if typeof(skill) == \"Instance\" and skill:IsA(\"NumberValue\") and skill.Value <= 0 then\n                                local key = skill:GetAttribute(\"Key\")\n                                if key then readySkills[key] = true end\n                            end\n                        end\n\n                        if Fishing.Flags.SkillMode == \"Sequential\" then\n                            local now = tick()\n                            local delay = Fishing.Flags.SkillDelay or 0.3\n                            if now - (NexusState.lastSkillCastTime or 0) >= delay then\n                                local seqStr = Fishing.Flags.SkillSequence or \"Z,X,C,V\"\n                                local seq = {}\n                                for k in string.gmatch(seqStr:upper(), \"[ZXCV]\") do\n                                    table.insert(seq, k)\n                                end\n                                if #seq == 0 then seq = {\"Z\", \"X\", \"C\", \"V\"} end\n\n                                local attempts = 0\n                                while attempts < #seq do\n                                    attempts = attempts + 1\n                                    if not NexusState.skillSeqIndex or NexusState.skillSeqIndex > #seq then\n                                        NexusState.skillSeqIndex = 1\n                                    end\n                                    local targetKey = seq[NexusState.skillSeqIndex]\n                                    NexusState.skillSeqIndex = NexusState.skillSeqIndex + 1\n                                    if readySkills[targetKey] then\n                                        Events.UseSkill:FireServer(targetKey)\n                                        NexusState.lastSkillCastTime = now\n                                        break\n                                    end\n                                end\n                            end\n                        else\n                            local selectedSkills = Fishing.Flags.SelectedSkills or {\"Z\", \"X\", \"C\", \"V\"}\n                            for _, key in ipairs(selectedSkills) do\n                                if readySkills[key] then\n                                    Events.UseSkill:FireServer(key)\n                                end\n                            end\n                        end\n                    end\n                end)\n            else\n                NexusState.skillSeqIndex = 1\n            end\n            if Fishing.Flags.AntiAFK and tick() - (NexusState.lastAfkFire or 0) > 60 then\n                local _afkMoving = false\n                pcall(function()\n                    local _c = LocalPlayer.Character\n                    local _h = _c and _c:FindFirstChildOfClass(\"Humanoid\")\n                    local _md = _h and _h.MoveDirection\n                    if _md and (math.abs(_md.X or 0) + math.abs(_md.Z or 0) > 0.05) then _afkMoving = true end\n                end)\n                if not _afkMoving then\n                    NexusState.lastAfkFire = tick()\n                    pcall(function() Events.AFK:FireServer() end)\n                end\n            end\n        end\n    end\nend)\n\n-- SMART SECRET WEATHER OVERRIDE LOOP\ntask.spawn(function()\n    local weatherIslandsMap = {\n        [\"thunderstorm\"] = \"Island 2\",\n        [\"rainy\"]        = \"Island 3\",\n        [\"windy\"]        = \"Island 5\",\n        [\"snowy\"]        = \"Island 6\",\n        [\"frost\"]        = \"Island 6\",\n        [\"foggy\"]        = \"Island 7\",\n        [\"blazing sun\"]  = \"Island 8\",\n    }\n\n    local function getActiveWeather()\n        local info = MainGui:FindFirstChild(\"Info\")\n        if info then\n            local infoFrame = info:FindFirstChild(\"Info\")\n            if infoFrame then\n                local weatherFrame = infoFrame:FindFirstChild(\"Weather\")\n                if weatherFrame then\n                    local val = weatherFrame:FindFirstChild(\"Value\")\n                    if val and typeof(val) == \"Instance\" then\n                        local text = ((typeof(val) == \"Instance\" and val:IsA(\"TextLabel\") and val.Text or val.Value))\n                        return text:gsub(\"Weather:%s*\", \"\"):lower():gsub(\"^%s+\", \"\"):gsub(\"%s+$\", \"\")\n                    end\n                end\n            end\n        end\n        return \"clear\"\n    end\n\n    while true do\n        task.wait(1.5)\n        if not alive() then break end\n        if NexusState.SmartWeather and NexusState.SmartWeather.enabled then\n            pcall(function()\n                local currentWeather = getActiveWeather()\n                local matchedIsland = weatherIslandsMap[currentWeather]\n\n                if matchedIsland and (currentWeather ~= \"clear\" and currentWeather ~= \"\") and NexusState.SmartWeather.selectedIslands[matchedIsland] then\n                    if not NexusState.SmartWeather.activeOverride then\n                        local char = LocalPlayer.Character\n                        local hrp = char and char:FindFirstChild(\"HumanoidRootPart\")\n                        if hrp then\n                            NexusState.SmartWeather.savedCFrame = hrp.CFrame\n                            NexusState.SmartWeather.savedFlags = {\n                                AutoCast = Fishing.Flags.AutoCast,\n                                AutoFarmBoss = Fishing.Flags.AutoFarmBoss,\n                                AutoFarmSecretBoss = Fishing.Flags.AutoFarmSecretBoss,\n                                AnchorLock = Fishing.Flags.AnchorLock,\n                                AutoSkill = Fishing.Flags.AutoSkill,\n                                AutoSkillCheck = Fishing.Flags.AutoSkillCheck,\n                                AntiAFK = Fishing.Flags.AntiAFK,\n                            }\n                            NexusState.SmartWeather.activeOverride = true\n                            NexusState.SmartWeather.targetIsland = matchedIsland\n\n                            for _, v in ipairs(NexusState.islands) do\n                                if v.name:lower() == matchedIsland:lower() then\n                                    hrp.AssemblyLinearVelocity = Vector3.zero\n                                    hrp.AssemblyAngularVelocity = Vector3.zero\n                                    hrp.CFrame = CFrame.new(v.cframe.Position + Vector3.new(0, 5, 0))\n                                    break\n                                end\n                            end\n\n                            Fishing.Flags.AutoCast = false\n                            Fishing.Flags.AutoFarmBoss = false\n                            Fishing.Flags.AutoFarmSecretBoss = true\n                            Fishing.Flags.AnchorLock = true\n                            Fishing.Flags.AutoSkill = true\n                            Fishing.Flags.AutoSkillCheck = true\n                            Fishing.Flags.AntiAFK = true\n\n                            NexusLib:Notify({\n                                Title = \"Farm On Weather\",\n                                Message = \"Weather detected: \" .. currentWeather:upper() .. \"! Auto-hopping to \" .. matchedIsland .. \" cau Secret.\",\n                                Duration = 4\n                            })\n                        end\n                    end\n                else\n                    if NexusState.SmartWeather.activeOverride then\n                        NexusLib:Notify({\n                            Title = \"Farm On Weather\",\n                            Message = \"Weather ended! Returning to the original farm...\",\n                            Duration = 3\n                        })\n                        local char = LocalPlayer.Character\n                        local hrp = char and char:FindFirstChild(\"HumanoidRootPart\")\n                        if NexusState.SmartWeather.savedCFrame and hrp then\n                            safeTeleport(hrp, NexusState.SmartWeather.savedCFrame)\n                        end\n                        if NexusState.SmartWeather.savedFlags then\n                            local s = NexusState.SmartWeather.savedFlags\n                            Fishing.Flags.AutoCast = s.AutoCast\n                            Fishing.Flags.AutoFarmBoss = s.AutoFarmBoss\n                            Fishing.Flags.AutoFarmSecretBoss = s.AutoFarmSecretBoss\n                            Fishing.Flags.AnchorLock = s.AnchorLock\n                            Fishing.Flags.AutoSkill = s.AutoSkill\n                            Fishing.Flags.AutoSkillCheck = s.AutoSkillCheck\n                            Fishing.Flags.AntiAFK = s.AntiAFK\n                        end\n                        NexusState.SmartWeather.activeOverride = false\n                        NexusState.SmartWeather.savedCFrame = nil\n                        NexusState.SmartWeather.savedFlags = nil\n                        NexusState.SmartWeather.targetIsland = nil\n                    end\n                end\n            end)\n        end\n    end\nend)\n\ntask.spawn(function()\n    while task.wait(1) do\n        if not alive() then break end\n        if bossFarmEnabled() then\n            local character = LocalPlayer.Character\n            local fishingGui = MainGui:FindFirstChild(\"Fishing\")\n            if character and character:GetAttribute(\"Fishing\") then\n                if Fishing.BossFarm.PendingCancel then\n                    cancelOrReleaseNormalFish()\n                elseif Fishing.BossFarm.HasHooked and fishingGui and fishingGui.Visible then\n                    local target = getCurrentHookTarget()\n                    local shouldFarm = shouldFarmBossTarget(target)\n                    if shouldFarm then\n                        Fishing.BossFarm.PendingCancel = false\n                        farmHookedBoss(target)\n                    elseif target.Name and target.Name ~= \"???\" then\n                        Fishing.BossFarm.PendingCancel = true\n                        cancelOrReleaseNormalFish()\n                    end\n                end\n            else\n                resetBossFarmTarget()\n                castRod()\n            end\n        end\n    end\nend)\n\n-- AUTO SELL\ndo\n    local function getInventoryCount()\n        local _icNow = tick()\n        if NexusState.cachedInvCount and NexusState.cachedInvCountAt and (_icNow - NexusState.cachedInvCountAt < 5) then\n            return NexusState.cachedInvCount\n        end\n        local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n        if not userData then return 0 end\n        local inv = userData:FindFirstChild(\"Inventory\")\n        if not inv then return 0 end\n        local count = 0\n        for _ in pairs(inv:GetChildren()) do count = count + 1 end\n        NexusState.cachedInvCount = count\n        NexusState.cachedInvCountAt = _icNow\n        return count\n    end\n\n    local function getInventoryLimit()\n        local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n        if not userData then return 0 end\n        local limit = userData:FindFirstChild(\"InventoryLimit\")\n        if limit and typeof(limit) == \"Instance\" and limit:IsA(\"NumberValue\") then return limit.Value end\n        return 0\n    end\n\n    local function getSellSofa()\n        local map = Workspace:FindFirstChild(\"Map\")\n        if map then\n            local map1 = map:FindFirstChild(\"Map 1\")\n            if map1 then\n                local build = map1:FindFirstChild(\"Build\")\n                if build then\n                    local sellFish = build:FindFirstChild(\"SellFish\")\n                    if sellFish then\n                        return sellFish:FindFirstChild(\"Sofa\")\n                    end\n                end\n            end\n        end\n        return nil\n    end\n\n    local function getSofaPosition()\n        local sofa = getSellSofa()\n        if sofa then\n            local hrp = sofa:FindFirstChild(\"HumanoidRootPart\")\n            if hrp then return hrp.Position end\n            local primary = sofa.PrimaryPart\n            if primary then return primary.Position end\n            for _, part in ipairs(sofa:GetDescendants()) do\n                if typeof(part) == \"Instance\" and part:IsA(\"BasePart\") then\n                    return part.Position\n                end\n            end\n        end\n        return nil\n    end\n\n    local function teleportToSofa()\n        local pos = getSofaPosition()\n        if not pos then return false end\n        local char = LocalPlayer.Character\n        if not char then return false end\n        local hrp = char:FindFirstChild(\"HumanoidRootPart\")\n        if not hrp then return false end\n        NexusState.lastPosition = hrp.Position\n        hrp.CFrame = CFrame.new(pos + Vector3.new(0, 3, 0))\n        return true\n    end\n\n    local function teleportBack()\n        if not NexusState.lastPosition then return end\n        local char = LocalPlayer.Character\n        if not char then return end\n        local hrp = char:FindFirstChild(\"HumanoidRootPart\")\n        if not hrp then return end\n        safeTeleport(hrp, CFrame.new(NexusState.lastPosition))\n        NexusState.lastPosition = nil\n    end\n\n    local function doSell()\n        if not MiscFlags.AutoSell then return end\n        if tick() - (NexusState.sellCooldown or 0) < 0.5 then return end\n        NexusState.sellCooldown = tick()\n        local method1 = NexusState.sellMethod1 or \"Spam\"\n        local method2 = NexusState.sellMethod2 or \"Instant\"\n        if method1 == \"When full\" then\n            local count = getInventoryCount()\n            local limit = getInventoryLimit()\n            if limit == 0 then return end\n            if count < limit - 3 then return end\n        end\n        local teleported = false\n        if method2 == \"Teleport\" then\n            teleported = teleportToSofa()\n            if teleported then task.wait(0.3) end\n        end\n        pcall(function() Events.SellFish:FireServer(\"All\") end)\n        if teleported then\n            task.wait(0.2)\n            teleportBack()\n        end\n    end\n\n    task.spawn(function()\n        while task.wait(2) do\n            if not alive() then break end\n            pcall(doSell)\n        end\n    end)\nend\n\nif runtimeEnv.NexusMinigameConn then pcall(function() runtimeEnv.NexusMinigameConn:Disconnect() end) end\nruntimeEnv.NexusMinigameConn = Events.FishingMinigame.OnClientEvent:Connect(function(p1, p2, p3)\n    if not p1 or not p2 then return end\n    Fishing.BossFarm.CurrentTarget = p1\n    Fishing.BossFarm.CurrentToken = p3\n    Fishing.BossFarm.HasHooked = true\n    Fishing.BossFarm.PendingCancel = false\n    Fishing.BossFarm.CurrentRunId = Fishing.BossFarm.CurrentRunId + 1\n    local runId = Fishing.BossFarm.CurrentRunId\n    local target = getCurrentHookTarget()\n    local shouldFarm = shouldFarmBossTarget(target)\n    if bossFarmEnabled() and not shouldFarm then\n        Fishing.BossFarm.PendingCancel = true\n        task.delay(0.15, cancelOrReleaseNormalFish)\n        return\n    end\n    if Fishing.Flags.AutoCast or (bossFarmEnabled() and shouldFarm) then\n        task.spawn(function()\n            local minigameActive = true\n            local connection\n            local fishingGui = MainGui:FindFirstChild(\"Fishing\")\n            if fishingGui then\n                connection = fishingGui:GetPropertyChangedSignal(\"Visible\"):Connect(function()\n                    if not fishingGui.Visible then\n                        minigameActive = false\n                        if connection then connection:Disconnect() connection = nil end\n                    end\n                end)\n            end\n            while minigameActive do\n                if not alive() then break end\n                if not MainGui:FindFirstChild(\"Fishing\") or not MainGui.Fishing.Visible then break end\n                if bossFarmEnabled() then\n                    if runId ~= Fishing.BossFarm.CurrentRunId then break end\n                    target = getCurrentHookTarget()\n                    shouldFarm = shouldFarmBossTarget(target)\n                    if not shouldFarm then\n                        Fishing.BossFarm.PendingCancel = true\n                        cancelOrReleaseNormalFish()\n                        break\n                    end\n                    farmHookedBoss(target)\n                    task.wait(0.08)\n                else\n                    pcall(function() Events.UpdateFishProgression:FireServer() end)\n                    task.wait(0.2)\n                end\n            end\n            if connection then pcall(function() connection:Disconnect() end) connection = nil end\n            if bossFarmEnabled() and runId == Fishing.BossFarm.CurrentRunId then\n                resetBossFarmTarget()\n            end\n        end)\n    end\nend)\n\nif runtimeEnv.NexusSlamConn then pcall(function() runtimeEnv.NexusSlamConn:Disconnect() end) end\nruntimeEnv.NexusSlamConn = Events.Slam.OnClientEvent:Connect(function(cb)\n    if Fishing.Flags.MainFarm then\n        task.spawn(function()\n            task.wait(0.1)\n            pcall(function() cb:FireServer(\"Perfect\") end)\n            local tc = MainGui:FindFirstChild(\"Fishing\") and MainGui.Fishing:FindFirstChild(\"TrashCan\")\n            if tc and tc:FindFirstChild(\"Slam\") then tc.Slam:Destroy() end\n        end)\n    end\nend)\n\n-- GUI click QTE (Rewritten Auto Enzo)\nlocal prevBarPos = 0\nlocal lastFrameTime = tick()\nlocal currentSpeed = 0\nlocal lastQTEClick = 0\nlocal lastQTEHitboxX = nil\n\n-- Click QTE the same way the game listens: desktop Fishing GUI button\n-- first (Fishing2.MouseButton1Down path), then mobile button, then\n-- synthetic mouse input as last fallback. Never fires blind.\nlocal EnzoQTEGui = nil\nlocal function findEnzoQTEGui()\n    if EnzoQTEGui and EnzoQTEGui.Parent then return EnzoQTEGui end\n    EnzoQTEGui = nil\n    local fishing = MainGui:FindFirstChild(\"Fishing\")\n    local btn = fishing and (fishing:FindFirstChild(\"Fishing2\") or fishing:FindFirstChild(\"Button\"))\n    if btn and typeof(btn) == \"Instance\" and btn:IsA(\"GuiButton\") then EnzoQTEGui = btn return btn end\n    local mobileFishing = MainGui:FindFirstChild(\"Mobile\") and MainGui.Mobile:FindFirstChild(\"Fishing\")\n    local mbtn = mobileFishing and (mobileFishing:FindFirstChild(\"Button\") or mobileFishing)\n    if mbtn and typeof(mbtn) == \"Instance\" and mbtn:IsA(\"GuiButton\") then EnzoQTEGui = mbtn return mbtn end\n    if fishing and typeof(fishing) == \"Instance\" and fishing:IsA(\"GuiButton\") then EnzoQTEGui = fishing return fishing end\n    return nil\nend\n\nlocal function pressEnzoQTE()\n    local btn = findEnzoQTEGui()\n    if btn and firesignal then\n        pcall(firesignal, btn.MouseButton1Down)\n        return\n    end\n    pcall(function()\n        local vim = game:GetService(\"VirtualInputManager\")\n        vim:SendMouseButtonEvent(0, 0, 0, true, game, 0)\n        vim:SendMouseButtonEvent(0, 0, 0, false, game, 0)\n    end)\nend\n\nlocal renderAccum = 0\nlocal RENDER_THROTTLE = 0.033\nlocal cachedFishingGui = nil\nlocal cachedBossBar = nil\n\nlocal function updateFrameLogic(dt)\n    if not cachedFishingGui or not cachedFishingGui.Parent then\n        cachedFishingGui = MainGui and MainGui:FindFirstChild(\"Fishing\")\n        cachedBossBar = cachedFishingGui and cachedFishingGui:FindFirstChild(\"BossFightBar\")\n    end\n    local fishing = cachedFishingGui\n    local bossBar = cachedBossBar\n    local bossBarVisible = bossBar ~= nil and bossBar.Visible == true\n    local fishingVisible = fishing ~= nil and fishing.Visible == true\n\n    if not bossBarVisible then\n        renderAccum = renderAccum + dt\n        if renderAccum < RENDER_THROTTLE then return end\n        renderAccum = 0\n    end\n\n    if (Fishing.Flags.AnchorLock or Fishing.Flags.AutoSkillCheck or Fishing.Flags.AutoLongDiaohai) and fishingVisible then\n        if Fishing.Flags.AnchorLock and not bossBarVisible and not Fishing.BossFarm.PendingCancel then\n            local bf = fishing:FindFirstChild(\"BarFrame\")\n            local b = bf and bf:FindFirstChild(\"Bar\")\n            if b then b.Position = UDim2.new(0.5, 0, 0.5, 0) end\n        end\n\n        if (Fishing.Flags.AutoSkillCheck or Fishing.Flags.AutoLongDiaohai) and bossBarVisible then\n            local bar = bossBar:FindFirstChild(\"Bar\")\n            local hitbox = bossBar:FindFirstChild(\"Hitbox\")\n            local badHitbox = bossBar:FindFirstChild(\"HitboxBad\")\n            if bar and hitbox and hitbox.Visible then\n                local barPos = bar.Position.X.Scale\n                local hbPos = hitbox.Position.X.Scale - hitbox.Size.X.Scale * hitbox.AnchorPoint.X\n                local hbSize = hitbox.Size.X.Scale\n                if lastQTEHitboxX ~= hbPos then\n                    lastQTEHitboxX = hbPos\n                    lastQTEClick = 0\n                end\n\n                local now = tick()\n                local dtFrame = now - lastFrameTime\n                lastFrameTime = now\n\n                if dtFrame > 0.001 and dtFrame < 0.1 then\n                    local rawSpeed = (barPos - prevBarPos) / dtFrame\n                    prevBarPos = barPos\n                    if math.abs(rawSpeed) < 5 then\n                        currentSpeed = currentSpeed * 0.7 + rawSpeed * 0.3\n                    end\n                else\n                    prevBarPos = barPos\n                end\n\n                local lastInput = UserInputService:GetLastInputType()\n                local latency = (lastInput == Enum.UserInputType.Touch) and 0.06 or 0.025\n                local compensatedBarPos = barPos - (currentSpeed * latency)\n\n                local margin = hbSize * 0.15\n                local badOverlap = false\n                if badHitbox and badHitbox.Visible then\n                    local badLeft = badHitbox.Position.X.Scale - badHitbox.Size.X.Scale * badHitbox.AnchorPoint.X\n                    badOverlap = compensatedBarPos >= badLeft and compensatedBarPos <= badLeft + badHitbox.Size.X.Scale\n                end\n\n                if not badOverlap and compensatedBarPos >= hbPos + margin and compensatedBarPos <= hbPos + hbSize - margin then\n                    if tick() - lastQTEClick > 0.15 then\n                        lastQTEClick = tick()\n                        pressEnzoQTE()\n                    end\n                end\n            else\n                lastQTEHitboxX = nil\n                prevBarPos = 0\n                lastFrameTime = tick()\n                currentSpeed = 0\n            end\n        else\n            lastQTEHitboxX = nil\n            prevBarPos = 0\n            lastFrameTime = tick()\n            currentSpeed = 0\n        end\n    end\n\n    if NexusState.flying and NexusState.bg and NexusState.bv and LocalPlayer.Character then\n        local h = LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n        local hum = LocalPlayer.Character:FindFirstChildOfClass(\"Humanoid\")\n        if h and hum then\n            local cameraLook = Camera.CFrame.LookVector\n            local move = hum.MoveDirection\n            local horizontal = Vector3.new(move.X, 0, move.Z)\n            local vertical = (NexusState.flyKeys.Up and 1 or 0) - (NexusState.flyKeys.Down and 1 or 0)\n            NexusState.bv.Velocity = horizontal * NexusState.flySpeed + Vector3.new(0, vertical * NexusState.flySpeed, 0)\n            local look = Vector3.new(cameraLook.X, 0, cameraLook.Z)\n            if look.Magnitude > 0.01 then\n                NexusState.bg.CFrame = CFrame.lookAt(h.Position, h.Position + look.Unit)\n            end\n        end\n    end\n\n    if MiscFlags.FullBright then\n        if not NexusState.fullBrightApplied then\n            Lighting.Ambient = Color3.new(1,1,1)\n            Lighting.ColorShift_Bottom = Color3.new(1,1,1)\n            Lighting.ColorShift_Top = Color3.new(1,1,1)\n            Lighting.Brightness = 2\n            Lighting.OutdoorAmbient = Color3.new(1,1,1)\n            NexusState.fullBrightApplied = true\n        end\n    else\n        if NexusState.fullBrightApplied then\n            NexusState.fullBrightApplied = false\n        end\n    end\nend\n\nruntimeEnv.NexusFrameConnection = RunService.RenderStepped:Connect(function(dt)\n    if not alive() then return end\n    pcall(updateFrameLogic, dt)\nend)\n\n-- ============================================================\n-- ===== PREPARE GLOBALS FOR THE CHUNKS =====\n-- ============================================================\n_G.RunService = RunService\n_G.LocalPlayer = LocalPlayer\n_G.VirtualUser = VirtualUser\n_G.UserInputService = UserInputService\n_G.Events = Events\n_G.MiscFlags = MiscFlags\n_G.alive = alive\n_G.runtimeEnv = runtimeEnv\n_G.Players = Players\n_G.Workspace = Workspace\n_G.Lighting = Lighting\n_G.NexusState = NexusState\n_G.Fishing = Fishing\n\n-- ===== LIVE ANTI-AFK (main chunk; fires only on real Idled, never steals controller) =====\ndo\n    local function nexusNudgeInput()\n        if Fishing and Fishing.Flags and not Fishing.Flags.AntiAFK then return end\n        local moving = false\n        pcall(function()\n            local char = LocalPlayer.Character\n            local hum = char and char:FindFirstChildOfClass(\"Humanoid\")\n            local md = hum and hum.MoveDirection\n            if md and (math.abs(md.X or 0) + math.abs(md.Z or 0) > 0.05) then moving = true end\n        end)\n        if moving then return end\n        pcall(function()\n            if Events and Events:FindFirstChild(\"AFK\") then\n                Events.AFK:FireServer()\n            end\n            if VirtualUser and workspace.CurrentCamera then\n                VirtualUser:Button2Down(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n                task.wait(0.2)\n                VirtualUser:Button2Up(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n            end\n        end)\n    end\n    pcall(function()\n        if runtimeEnv.AntiAFKConnection then runtimeEnv.AntiAFKConnection:Disconnect() end\n    end)\n    runtimeEnv.AntiAFKConnection = LocalPlayer.Idled:Connect(function()\n        nexusNudgeInput()\n    end)\nend\n\n-- ===== RUN THE EXTRA CHUNKS =====\nif _G.codetorun then loadstring(_G.codetorun)() end\nif _G.codes then loadstring(_G.codes)() end\n\npcall(function()\n    if I18n and I18n.initListeners then\n        I18n.initListeners()\n        I18n.applyLanguage()\n    end\nend)\n\n\nruntimeEnv.AutoFarm = true\n\n-- ===== BOOT XONG =====\npcall(function()\n    if runtimeEnv.NexusBoot then\n        runtimeEnv.NexusBoot.stage = \"xong\"\n        runtimeEnv.NexusBoot.done = true\n    end\n    if runtimeEnv.NexusBootGui then runtimeEnv.NexusBootGui:Destroy() end\nend)\n",
